local config = {
  ui_story_5033_50330101_X1_dialog_content = "B-Bantu aku...",
  ui_story_5033_50330101_X2_dialog_content = "Tolong... Aduh...",
  ui_story_5033_50330101_1_dialog_content = "<color=#e8d9bb>Dug!</color>",
  ui_story_5033_50330101_2_dialog_content = "Lihat, Ibu! Orang itu di sana jatuh saat berjalan!",
  ui_story_5033_50330101_3_dialog_content = "Tunggu disini. Biarkan aku pergi melihat-lihat.",
  ui_story_5033_50330101_4_dialog_content = "A-Apa ini...?",
  ui_story_5033_50330101_5_dialog_content = "<size=45>Aaaagh!</size>",
  ui_story_5033_50330101_6_dialog_content = "<color=#e8d9bb>Jalan yang tidak dikenal di Umbraton</color>",
  ui_story_5033_50330101_7_dialog_content = "(Aku terlambat...)",
  ui_story_5033_50330101_8_dialog_content = "Apakah Anda yakin tidak melihat orang lain di sekitar?",
  ui_story_5033_50330101_9_dialog_content = "Tidak... Dan anak saya hanya melihat korban jatuh.",
  ui_story_5033_50330101_10_dialog_content = "Dia terhuyung-huyung sedikit sebelum ambruk.",
  ui_story_5033_50330101_11_dialog_content = "Saat aku menghubunginya, dia sudah...",
  ui_story_5033_50330101_12_dialog_content = "Baiklah, mengerti.",
  ui_story_5033_50330101_13_dialog_content = "Aku akan menangani ini. Anda bisa pergi sekarang.",
  ui_story_5033_50330101_14_dialog_content = "Tidak terlalu aman di Umbraton akhir-akhir ini, jadi cobalah untuk tidak mengambil jalan terpencil.",
  ui_story_5033_50330101_15_dialog_content = "Ah...",
  ui_story_5033_50330101_16_dialog_content = "Oke terima kasih...",
  ui_story_5033_50330101_17_dialog_content = "Ayo pergi, nak. Dan berhenti mengintip.",
  ui_story_5033_50330101_18_dialog_content = "*Berdesah*",
  ui_story_5033_50330101_19_dialog_content = "(Jalan buntu lainnya. Masih tidak bisa mengejar pelakunya.)",
  ui_story_5033_50330101_20_dialog_content = "(Satu-satunya hal yang pasti adalah orang ini meninggal dengan cara yang sama seperti <color=#FFB400>korban sebelumnya</color>.)",
  ui_story_5033_50330101_21_dialog_content = "Tunggu sebentar!",
  ui_story_5033_50330101_22_dialog_content = "(Masih ada napas samar yang keluar darinya, bisakah dia ...)",
  ui_story_5033_50330101_23_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_5033_50330101_24_dialog_content = "Maaf, Shadowlord, yang tersisa hanyalah korban. Saksi tidak melihat orang lain.",
  ui_story_5033_50330101_25_dialog_content = "Siapa getah sial itu?",
  ui_story_5033_50330101_26_dialog_content = "Orang luar kota yang mendapatkan kekayaannya dari taruhan kuda. Dia jatuh tepat di luar rumahnya. Sepertinya dia sedang dalam perjalanan ke suatu tempat. Tetapi...",
  ui_story_5033_50330101_27_dialog_content = "Berdasarkan pemeriksaan awal saya, saya pikir dia masih bisa diselamatkan.",
  ui_story_5033_50330101_28_dialog_content = "Kita harus mengambil kesempatan ini.",
  ui_story_5033_50330101_29_dialog_content = "Aku akan mengirim seseorang untuk menyadarkannya sekarang. Anda tetap pada kasus ini.",
  ui_story_5033_50330101_30_dialog_content = "Ada apa dengan pelaku kali ini?",
  ui_story_5033_50330101_31_dialog_content = "Jika kita hubungkan kejahatan ini dengan kasus-kasus masa lalu, luka pada korban identik dengan <color=#FFB400>pembunuhan biarawati</color> beberapa tahun lalu.",
  ui_story_5033_50330101_32_dialog_content = "Sebuah detail penting diabaikan dalam semua penyelidikan sebelumnya.",
  ui_story_5033_50330101_33_dialog_content = "Semua korban mengalami luka kecil di tubuh mereka sebelum ambruk tiba-tiba karena alasan yang belum ditentukan.",
  ui_story_5033_50330101_34_dialog_content = "Potongannya selalu terlalu kecil untuk dilihat dengan mata telanjang dan sepertinya tidak mematikan.",
  ui_story_5033_50330101_35_dialog_content = "Tapi setelah diperiksa lebih dekat dari korban terbaru kami, saya cukup yakin itu adalah luka pisau.",
  ui_story_5033_50330101_36_dialog_content = "Pelakunya sangat terampil. Pisau masuk dengan cepat dan tepat, mengenai tempat yang tepat.",
  ui_story_5033_50330101_37_dialog_content = "Corax, saya menempatkan Anda pada kasus untuk membawa pelaku hidup-hidup.",
  ui_story_5033_50330101_38_dialog_content = "Anda seorang dokter. Anda harus tahu apa yang harus dilakukan.",
  ui_story_5033_50330101_39_dialog_content = "... Tolong beri saya lebih banyak waktu, Pak.",
  ui_story_5033_50330101_40_dialog_content = "Apa rencanamu?",
  ui_story_5033_50330101_41_dialog_content = "Saya akan tetap pada rencana awal dan tidak memperhatikan.",
  ui_story_5033_50330101_42_dialog_content = "Bertindak dengan cepat dan hati-hati.",
  ui_story_5033_50330101_43_dialog_content = "Saya harus.",
  ui_story_5033_50330101_44_dialog_content = "<color=#e8d9bb>Sebulan kemudian, di Konvensi Barang Rumah Tangga di Umbraton</color>",
  ui_story_5033_50330101_45_dialog_content = "<size=45>Ekstra, ekstra!</size>",
  ui_story_5033_50330101_46_dialog_content = "Berita Umbraton baru keluar dari oven! Dapatkan pers lezat Anda sekarang!",
  ui_story_5033_50330101_47_dialog_content = "(Siapa yang mendeskripsikan koran seperti itu?!)",
  ui_story_5033_50330101_48_dialog_content = "Hei!",
  ui_story_5033_50330101_49_dialog_content = "PlayerName! Sungguh pemandangan yang langka! Apakah Anda sendirian di Umbraton?",
  ui_story_5033_50330101_50_dialog_content = "(Oh tidak, aku tertangkap!)",
  ui_story_5033_50330101_51_dialog_content = "Jadi, bagaimana dengan mengambil salinannya? Anda tidak ingin melewatkan ini!",
  ui_story_5033_50330101_52_dialog_content = "\"Umbraton telah diganggu oleh <color=#FFB400>pembunuhan berantai misterius</color> dalam beberapa minggu terakhir\"...",
  ui_story_5033_50330101_53_dialog_content = "\"Beberapa orang yang terkait dengan <color=#FFB400>pasar gelap</color> ditemukan tewas di rumah mereka\"...",
  ui_story_5033_50330101_54_dialog_content = "\"Korban menunjukkan <color=#FFB400>tanda-tanda perjuangan yang aneh</color>, dan pembunuhnya masih buron\"...",
  ui_story_5033_50330101_55_dialog_content = "Bagaimana dengan itu? Apakah Anda mendapatkan dorongan untuk merebut kertas sekarang?",
  ui_story_5033_50330101_56_dialog_content = "Tidak, aku baik-baik saja! Saya di sini bukan untuk membeli kertas hari ini.",
  ui_story_5033_50330101_57_dialog_content = "Ayo, PlayerName, Anda sudah di sini. Anda harus membeli sesuatu!",
  ui_story_5033_50330101_58_dialog_content = "Sebenarnya...",
  ui_story_5033_50330101_59_dialog_content = "<color=#e8d9bb>Beberapa hari yang lalu di Cloud Gardens</color>",
  ui_story_5033_50330101_60_dialog_content = "(Fiuh, akhirnya, Cloud Gardens lebih rapi sekarang.)",
  ui_story_5033_50330101_61_dialog_content = "(Saya telah mengerjakan proyek ini begitu lama, saya layak istirahat.)",
  ui_story_5033_50330101_62_dialog_content = "Tapi ini belum cukup baik.",
  ui_story_5033_50330101_63_dialog_content = "Apa?! Bagaimana Anda tahu apa saya—",
  ui_story_5033_50330101_64_dialog_content = "Wajahmu memberitahuku bahwa kamu akan menyerah, PlayerName.",
  ui_story_5033_50330101_65_dialog_content = "Kami sudah menyiapkan perabotan dasar, tapi masih terlalu kosong dan polos.",
  ui_story_5033_50330101_66_dialog_content = "Nih!",
  ui_story_5033_50330101_67_dialog_content = "Wah, tumpukan apa ini?",
  ui_story_5033_50330101_68_dialog_content = "Katalog peserta pameran tahunan Umbraton Home Goods Convention!",
  ui_story_5033_50330101_69_dialog_content = "Anda tidak ingin tahu berapa banyak koneksi yang harus saya lalui untuk mengumpulkan semuanya!",
  ui_story_5033_50330101_70_dialog_content = "... Anda telah merencanakan ini selamanya, bukan.",
  ui_story_5033_50330101_71_dialog_content = "Mari kita tidak memikirkan detail-detail kecil!",
  ui_story_5033_50330101_72_dialog_content = "Lagi pula, renovasi bukanlah masalah sepele. Bagaimanapun, ini adalah rumah Anda.",
  ui_story_5033_50330101_73_dialog_content = "Sekarang bayangkan akhirnya bisa pulang dan bersantai setelah perjalanan panjang. Apa yang kamu lihat?",
  ui_story_5033_50330101_74_dialog_content = "Oh, aku ingin meringkuk di kursi malas.",
  ui_story_5033_50330101_75_dialog_content = "Bagaimana perasaan kursi untuk Anda, apakah itu terbuat dari satin lembut atau kulit dingin?",
  ui_story_5033_50330101_76_dialog_content = "Kulit untuk kursi malas, tentu saja! Dan itu akan terlihat lebih keren.",
  ui_story_5033_50330101_77_dialog_content = "Melihat? Perabotan dan dekorasi tidak hanya membantu kepuasan, tetapi juga merupakan cara yang baik untuk memamerkan gaya Anda!",
  ui_story_5033_50330101_78_dialog_content = "Semua hal yang masuk ke rumah Anda harus dipilih dengan cermat.",
  ui_story_5033_50330101_79_dialog_content = "WW-Tunggu sebentar!",
  ui_story_5033_50330101_80_dialog_content = "Anda tidak mencoba membuat saya membaca semua brosur ini, bukan?",
  ui_story_5033_50330101_81_dialog_content = "Ini tidak seperti Anda punya sesuatu untuk dilakukan dalam beberapa hari ke depan!",
  ui_story_5033_50330101_82_dialog_content = "Dan Anda harus menangani setiap langkah dalam renovasi secara pribadi.",
  ui_story_5033_50330101_83_dialog_content = "Baiklah sekarang, tidak ada waktu untuk mengobrol.",
  ui_story_5033_50330101_84_dialog_content = "Kita harus bersiap-siap. Belanja adalah perang, lho!",
  ui_story_5033_50330101_85_dialog_content = "Ingat bahan, finishing, dan gaya untuk setiap item.",
  ui_story_5033_50330101_86_dialog_content = "Teliti dan evaluasi semuanya dengan seksama sebelum membuat daftar akhir, jadi Anda akan dipersenjatai untuk konvensi!",
  ui_story_5033_50330101_87_dialog_content = "Ya, Wakil Perwira!",
  ui_story_5033_50330101_88_dialog_content = "Sama seperti itu, kami melihat-lihat brosur selama empat hari penuh dengan sedikit tidur.",
  ui_story_5033_50330101_89_dialog_content = "Wow, mengesankan!",
  ui_story_5033_50330101_90_dialog_content = "Ya. Vice sangat fokus pada laser sehingga dia bisa membakarnya dengan matanya.",
  ui_story_5033_50330101_91_dialog_content = "Saya pikir yang harus saya lakukan adalah mengikuti Vice di sekitar konvensi.",
  ui_story_5033_50330101_92_dialog_content = "Tapi...",
  ui_story_5033_50330101_93_dialog_content = "<color=#e8d9bb>Tepat sebelum keberangkatan</color>",
  ui_story_5033_50330101_94_dialog_content = "Ya ampun, aku sangat menyesal, PlayerName!!!",
  ui_story_5033_50330101_95_dialog_content = "Saya baru saja mendapat tugas mendesak dari Komandan Hiiro ...",
  ui_story_5033_50330101_96_dialog_content = "Jadi, saya akhirnya datang sendiri tanpa petunjuk atau anggaran apa pun.",
  ui_story_5033_50330101_97_dialog_content = "Sayang sekali, PlayerName. Konvensi <color=#FFB400>dibatalkan</color> menit terakhir.",
  ui_story_5033_50330101_98_dialog_content = "Apa?!",
  ui_story_5033_50330101_99_dialog_content = "Itu karena pembunuhan berantai yang membuat semua orang gelisah.",
  ui_story_5033_50330101_100_dialog_content = "Karena masalah keamanan, Umbraton membatalkan semua pertemuan besar untuk sementara waktu.",
  ui_story_5033_50330101_101_dialog_content = "B-benarkah?!",
  ui_story_5033_50330101_102_dialog_content = "Betapa beruntungnya...",
  ui_story_5033_50330101_103_dialog_content = "Jangan depresi semua. Umbraton memiliki banyak barang untuk dijual.",
  ui_story_5033_50330101_104_dialog_content = "Lihatlah ke sekeliling dan Anda mungkin menemukan sesuatu yang keren!",
  ui_story_5033_50330101_105_dialog_content = "Yah, harus lari sekarang!",
  ui_story_5033_50330101_106_dialog_content = "Terima kasih, Wendy!",
  ui_story_5033_50330101_107_dialog_content = "Ke mana saya harus pergi?",
  ui_story_5033_50330101_108_dialog_content = "Hmm? Apakah ini kios yang mengkhususkan diri dalam... kartu pos?",
  ui_story_5033_50330101_109_dialog_content = "Warna ini sangat cantik.",
  ui_story_5033_50330101_110_dialog_content = "Kartu pos juga bisa menjadi dekorasi rumah lho.",
  ui_story_5033_50330101_111_dialog_content = "Jangan ragu untuk melihat melalui mereka. Mereka menyoroti berbagai kota dan lokasi di sekitar Umbraton.",
  ui_story_5033_50330101_112_dialog_content = "(Yah, setidaknya aku punya cukup uang untuk membeli kartu pos...)",
  ui_story_5033_50330101_113_dialog_content = "Saya kira saya akan mengambil yang saya pegang saat itu.",
  ui_story_5033_50330101_114_dialog_content = "Terima kasih, dan silakan datang lagi!",
  ui_story_5033_50330101_115_dialog_content = "(Kota di kartu pos ini disebut... <color=#FFB400>Euphoria</color>?)",
  ui_story_5033_50330101_116_dialog_content = "(Dan tulisan di belakang—\"Selamat datang di <color=#FFB400>Wonderland</color>\"...)",
  ui_story_5033_50330101_117_dialog_content = "(Belum pernah ke sana. Akan menyenangkan untuk memeriksanya kapan-kapan.)",
  ui_story_5033_50330101_118_dialog_content = "(Terapi ritel moderat memang meningkatkan suasana hati seseorang.)",
  ui_story_5033_50330101_119_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5033_50330101_120_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5033_50330101_121_dialog_content = "Kartu pos saya!!!",
  ui_story_5033_50330101_122_dialog_content = "Astaga... Kemana perginya?",
  ui_story_5033_50330101_123_dialog_content = "Berhenti di sana, kalian berdua!",
  ui_story_5033_50330101_124_dialog_content = "*Terengah-engah*",
  ui_story_5033_50330101_125_dialog_content = "...",
  ui_story_5033_50330101_126_dialog_content = "(Sungguh pria yang tampak aneh. Apakah penampilan seperti ini adalah mode terbaru di Umbraton?)",
  ui_story_5033_50330101_127_dialog_content = "(Tunggu, kenapa dia terlihat familiar?)",
  ui_story_5033_50330101_128_dialog_content = "Saya tidak tahu mengapa Anda menghentikan kami ...",
  ui_story_5033_50330101_129_dialog_content = "Tapi terima kasih bagaimanapun, PlayerName.",
  ui_story_5033_50330101_130_dialog_content = "Nah, sejak pria itu tertangkap...",
  ui_story_5033_50330101_131_dialog_content = "Saya bisa mengambilnya dari sini.",
  ui_story_5033_50330101_132_dialog_content = "Corax?! Kenapa kamu berpakaian seperti ini?",
  ui_story_5033_50330101_133_dialog_content = "Tolong, Pak, saya mohon, saya tidak ada hubungannya dengan itu!",
  ui_story_5033_50330101_134_dialog_content = "Kecuali jika Anda memberi saya sesuatu yang berharga ...",
  ui_story_5033_50330101_135_dialog_content = "Aku akan membawamu langsung ke Shadowlord.",
  ui_story_5033_50330101_136_dialog_content = "Tapi aku tidak tahu apa-apa!",
  ui_story_5033_50330101_137_dialog_content = "Benarkah?",
  ui_story_5033_50330101_138_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5033_50330101_139_dialog_content = "Tidak, jangan! Oke, saya akan bicara, singkirkan itu!",
  ui_story_5033_50330101_140_dialog_content = "Aku pasti berbisnis dengan mereka, tapi aku tidak membunuh siapa pun!",
  ui_story_5033_50330101_141_dialog_content = "Mereka semua memulai bisnis gelap dan menggunakan uang mereka untuk mengeksploitasi penjahat Umbraton!",
  ui_story_5033_50330101_142_dialog_content = "Itu semua berita lama. Ada yang lain?",
  ui_story_5033_50330101_143_dialog_content = "D-dan...",
  ui_story_5033_50330101_144_dialog_content = "Sebelum mati, mereka semua mengunjungi <color=#FFB400>Euphoria</color>!",
  ui_story_5033_50330101_145_dialog_content = "Seharusnya, <color=#FFB400>Grim Reaper</color> muncul di sana!",
  ui_story_5033_50330101_146_dialog_content = "Malaikat maut?",
  ui_story_5033_50330101_147_dialog_content = "I-Itu benar... Siapapun yang tidak mematuhi Grim Reaper...",
  ui_story_5033_50330101_148_dialog_content = "Itu merenggut hidup mereka beberapa hari kemudian!",
  ui_story_5033_50330101_149_dialog_content = "Mereka pasti mati karena Grim Reaper, yang tidak boleh dibicarakan!",
  ui_story_5033_50330101_150_dialog_content = "Tapi bukankah Euforia sudah...",
  ui_story_5033_50330101_151_dialog_content = "Anda sebaiknya mengatakan yang sebenarnya.",
  ui_story_5033_50330101_152_dialog_content = "Saya, saya bersumpah!",
  ui_story_5033_50330101_153_dialog_content = "...",
  ui_story_5033_50330101_154_option_content = "Force Boost!",
  ui_story_5033_50330101_155_dialog_content = "Eh, dia mengatakan yang sebenarnya, Corax.",
  ui_story_5033_50330101_156_dialog_content = "Saya tidak merasakan apa pun selain stres dan ketakutan.",
  ui_story_5033_50330101_157_dialog_content = "Terima kasih atas bantuan besarnya, PlayerName.",
  ui_story_5033_50330101_158_dialog_content = "A-Apa yang kamu lakukan sekarang?!",
  ui_story_5033_50330101_159_dialog_content = "Saya ingin Anda pergi ke Euphoria bersama saya.",
  ui_story_5033_50330101_160_dialog_content = "Sekarang juga?!",
  ui_story_5033_50330101_161_dialog_content = "Aku di bawah perintah Shadowlord untuk pergi ke sana dan menyelidiki pembunuhan berantai di Umbraton.",
  ui_story_5033_50330101_162_dialog_content = "Saya akan menjelaskan sisanya di jalan.",
  ui_story_5033_50330101_163_dialog_content = "Untuk menghindari Colossus Anda menarik perhatian yang tidak perlu, kami akan menggunakan pesawat.",
  ui_story_5033_50330101_164_dialog_content = "Sampai jumpa di Shuttle Hub besok pagi.",
  ui_story_5033_50330101_165_dialog_content = "Maksudku tentu saja, aku memang ingin melihat Euphoria, tapi...",
  ui_story_5033_50330101_166_dialog_content = "Kalau begitu, sampai jumpa besok.",
  ui_story_5033_50330101_167_dialog_content = "Tunggu, biarkan aku selesai!",
  ui_story_5033_50330101_168_dialog_content = "Anda setidaknya bisa membiarkan saya memikirkannya ...",
  ui_story_5033_50330201_1_dialog_content = "<color=#e8d9bb>Pusat Antar-Jemput</color>",
  ui_story_5033_50330201_2_dialog_content = "(Nah, inilah aku. Aku bahkan sampai di sini lebih awal dari yang dijanjikan...)",
  ui_story_5033_50330201_3_dialog_content = "(Saya jarang datang ke sini karena saya bepergian di Soroz.)",
  ui_story_5033_50330201_4_dialog_content = "(Kuharap aku bisa mengirim kartu pos kembali ke Eraveil... Kalau saja aku tidak kehilangan kartu pos yang kumiliki kemarin.)",
  ui_story_5033_50330201_5_dialog_content = "Kartu posku... Ugh...",
  ui_story_5033_50330201_6_dialog_content = "Maafkan aku karena mendengar ratapanmu.",
  ui_story_5033_50330201_7_dialog_content = "Jika itu kartu pos yang membuat Anda kesal,",
  ui_story_5033_50330201_8_dialog_content = "Saya kebetulan memiliki satu pada saya. Ini, ambil.",
  ui_story_5033_50330201_9_dialog_content = "Wah, tidak mungkin! Itu gambar yang sama, bahkan!",
  ui_story_5033_50330201_10_dialog_content = "Aku tidak bisa menerima ini. aku bahkan tidak mengenalmu...",
  ui_story_5033_50330201_11_dialog_content = "Itu lebih cocok untukmu. Ambillah, dan saya bisa menyebutnya perbuatan baik saya untuk hari itu.",
  ui_story_5033_50330201_12_dialog_content = "Sungguh, simpanlah. Aku tidak membutuhkannya lagi.",
  ui_story_5033_50330201_13_dialog_content = "Anda tidak?",
  ui_story_5033_50330201_14_dialog_content = "Ya, karena aku akan kembali.",
  ui_story_5033_50330201_15_dialog_content = "Sudah empat belas tahun sejak saya berada di Euphoria terakhir.",
  ui_story_5033_50330201_16_dialog_content = "Maaf untuk bertele-tele.",
  ui_story_5033_50330201_17_dialog_content = "Itu keren, saya masih menunggu seseorang untuk muncul. Jadi, aku harus memanggilmu apa?",
  ui_story_5033_50330201_18_dialog_content = "...",
  ui_story_5033_50330201_19_dialog_content = "Anne baik-baik saja.",
  ui_story_5033_50330201_20_dialog_content = "aku PlayerName. Ini akan menjadi pertama kalinya saya di Euphoria.",
  ui_story_5033_50330201_21_dialog_content = "Anda terdengar seperti Anda mengetahuinya dengan baik. Keberatan memberitahu saya sedikit tentang hal itu?",
  ui_story_5033_50330201_22_dialog_content = "Saya melihat kartu pos yang menjulukinya \"<color=#FFB400>Wonderland</color>.\"",
  ui_story_5033_50330201_23_dialog_content = "Itu benar. Untuk orang luar saat itu, itu pasti bisa dianggap semacam negeri ajaib.",
  ui_story_5033_50330201_24_dialog_content = "Mereka datang untuk mengejar kebahagiaan yang tidak dapat mereka temukan di tempat lain.",
  ui_story_5033_50330201_25_dialog_content = "Namun, yang paling memikat bukanlah suasana atau pemandangan yang nyaman",
  ui_story_5033_50330201_26_dialog_content = "melainkan, <color=#FFB400>pasar gelap</color> yang berkembang di dalam bayang-bayang bangunan uniknya.",
  ui_story_5033_50330201_27_dialog_content = "Pasar gelap?!",
  ui_story_5033_50330201_28_dialog_content = "Bukankah Umbraton juga punya? Mengapa pergi ke Euforia?",
  ui_story_5033_50330201_29_dialog_content = "Itu awalnya sangat mirip dengan Umbraton, tetapi Euphoria secara hukum milik pribadi.",
  ui_story_5033_50330201_30_dialog_content = "Seperti yang mungkin bisa Anda tebak, melintasi batas demi keuntungan dan keinginan pribadi adalah hal biasa di sana.",
  ui_story_5033_50330201_31_dialog_content = "Kasino besar, produsen senjata swasta... Apa pun yang bisa Anda bayangkan ada di sana.",
  ui_story_5033_50330201_32_dialog_content = "Kedengarannya bahkan lebih liberal daripada Umbraton.",
  ui_story_5033_50330201_33_dialog_content = "Terima kasih untuk primernya. Saya menantikan kunjungannya.",
  ui_story_5033_50330201_34_dialog_content = "Tapi saya khawatir Anda hanya akan kecewa jika Anda pergi ke Euphoria dengan prasangka apa pun.",
  ui_story_5033_50330201_35_dialog_content = "Apa maksudmu?",
  ui_story_5033_50330201_36_dialog_content = "Beberapa saat setelah aku pergi, Euphoria tiba-tiba menghilang.",
  ui_story_5033_50330201_37_dialog_content = "Aku bahkan tidak pernah mendengar ada yang menyebut nama itu sejak saat itu.",
  ui_story_5033_50330201_38_dialog_content = "Seolah-olah kota itu sengaja dilupakan.",
  ui_story_5033_50330201_39_dialog_content = "Kota yang terlupakan, ya...",
  ui_story_5033_50330201_40_dialog_content = "PlayerName!",
  ui_story_5033_50330201_41_dialog_content = "Maaf untuk menunggu.",
  ui_story_5033_50330201_42_dialog_content = "Tidak masalah. Saya telah berbicara dengan biarawati ini di sini yang juga pergi ke Euforia.",
  ui_story_5033_50330201_43_dialog_content = "Anne, ini Corax. Dia bepergian dengan saya.",
  ui_story_5033_50330201_44_dialog_content = "Pesawat akan lepas landas. Kita harus naik sekarang.",
  ui_story_5033_50330201_45_dialog_content = "Sangat jarang menemukan penerbangan ke Euphoria, jadi jangan sampai ketinggalan.",
  ui_story_5033_50330201_46_dialog_content = "B-baiklah…",
  ui_story_5033_50330201_47_dialog_content = "<color=#e8d9bb>Di pesawat</color>",
  ui_story_5033_50330201_48_dialog_content = "Bagaimanapun, saya secara resmi mengambil kasus dari Shadowlord sebulan yang lalu.",
  ui_story_5033_50330201_49_dialog_content = "Umbraton telah melihat kejahatan kekerasan akhir-akhir ini yang menargetkan beberapa tempat untuk perdagangan bawah tanah, serta mereka yang terlibat dalam perdagangan tersebut.",
  ui_story_5033_50330201_50_dialog_content = "Peristiwa tersebut merugikan perekonomian.",
  ui_story_5033_50330201_51_dialog_content = "Ini harus menjadi investigasi rahasia karena beberapa alasan.",
  ui_story_5033_50330201_52_dialog_content = "Dari kesaksian pria itu kemarin, saya hanya harus pergi ke sana.",
  ui_story_5033_50330201_53_dialog_content = "Jadi maksudmu setiap petunjuk mengarah ke Euforia?",
  ui_story_5033_50330201_54_dialog_content = "Oh, berbicara tentang <color=#FFB400>pembunuhan biarawati</color> yang memulai semuanya, kita memiliki seseorang sebelum kita yang mungkin bisa membantu.",
  ui_story_5033_50330201_55_dialog_content = "...",
  ui_story_5033_50330201_56_dialog_content = "Tidak masalah, saya bisa bekerja sama.",
  ui_story_5033_50330201_57_dialog_content = "Tenang, saya hanya ingin mengajukan beberapa pertanyaan sederhana.",
  ui_story_5033_50330201_58_dialog_content = "Apakah Anda mengenal seorang biarawati bernama <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330201_59_dialog_content = "Aku tahu tentang dia, ya.",
  ui_story_5033_50330201_60_dialog_content = "Tapi yang aku tahu dia dipindahkan dari Euphoria ke Umbraton. Apakah dia...?",
  ui_story_5033_50330201_61_dialog_content = "Dia adalah salah satu korban pertama.",
  ui_story_5033_50330201_62_dialog_content = "... Semoga dia beristirahat dengan tenang.",
  ui_story_5033_50330201_63_dialog_content = "Mungkin begitulah nasib kami para biarawati.",
  ui_story_5033_50330201_64_dialog_content = "Tidak bisa menghindarinya bahkan dengan meninggalkan Euphoria, kurasa.",
  ui_story_5033_50330201_65_dialog_content = "Tidak berusaha bersikap kasar, tetapi Anda tampaknya tidak terlalu terkejut.",
  ui_story_5033_50330201_66_dialog_content = "Biarawati tidak punya tempat di Euforia lagi.",
  ui_story_5033_50330201_67_dialog_content = "Jika Anda terjebak sendirian di jalanan dan tidak punya cukup uang,",
  ui_story_5033_50330201_68_dialog_content = "bahkan bagaimana Anda mati terserah nasib untuk memutuskan.",
  ui_story_5033_50330201_69_dialog_content = "Kedengarannya seperti tempat yang damai...",
  ui_story_5033_50330201_70_dialog_content = "Namun Anda naik pesawat ke Euphoria seperti kami.",
  ui_story_5033_50330201_71_dialog_content = "Saya berusaha untuk menjauh dari itu semua dengan pergi.",
  ui_story_5033_50330201_72_dialog_content = "Tapi ada sesuatu yang memanggilku kembali sekarang.",
  ui_story_5033_50330201_73_dialog_content = "... Anda tahu, tidak ada yang saya sembunyikan. Saya akan kembali ke <color=#FFB400>melihat teman</color>.",
  ui_story_5033_50330201_74_dialog_content = "Saya kira kita tidak akan pergi dengan cara yang sama.",
  ui_story_5033_50330201_75_dialog_content = "Saya pikir kita hampir sampai, dilihat dari pemandangan di bawah.",
  ui_story_5033_50330201_76_dialog_content = "<color=#e8d9bb>Jalan di Euforia</color>",
  ui_story_5033_50330201_77_dialog_content = "Saya kira ini adalah di mana kita mengucapkan selamat tinggal.",
  ui_story_5033_50330201_78_dialog_content = "Semoga sukses dengan kasus Anda.",
  ui_story_5033_50330201_79_dialog_content = "Terima kasih. Anda juga berhati-hati.",
  ui_story_5033_50330201_80_dialog_content = "(Dia pergi dengan tergesa-gesa. Dia juga tampaknya tidak terlalu peduli dengan keselamatannya...)",
  ui_story_5033_50330201_81_dialog_content = "<color=#e8d9bb>Aduh, aduh—</color>",
  ui_story_5033_50330201_82_dialog_content = "Di sini sunyi, seperti yang dikatakan Anne.",
  ui_story_5033_50330201_83_dialog_content = "Bangunannya rusak atau dirusak, dan tidak ada orang yang terlihat...",
  ui_story_5033_50330201_84_dialog_content = "Kurasa apa yang disebut Negeri Ajaib ini hanyalah desa yang ditinggalkan.",
  ui_story_5033_50330201_85_dialog_content = "Jadi kamu juga pernah mendengar julukan Euphoria, ya?",
  ui_story_5033_50330201_86_dialog_content = "Jangan kecewa. Saya mendapat beberapa info berguna dari Taki sebelum saya pergi.",
  ui_story_5033_50330201_87_dialog_content = "Kalau begitu, mari kita mulai pertunjukan ini...",
  ui_story_5033_50330201_88_dialog_content = "Hmm?",
  ui_story_5033_50330201_89_dialog_content = "Ada apa?",
  ui_story_5033_50330201_90_dialog_content = "Aku merasakan sesuatu yang aneh di udara...",
  ui_story_5033_50330201_91_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330201_92_dialog_content = "<size=45>Grah!!!</size>",
  ui_story_5033_50330201_93_dialog_content = "Seperti yang dikatakan laporan itu, langit mendung yang terus-menerus di daerah itu dan kabut tebal membuat taman bermain alami untuk Eclipsites ...",
  ui_story_5033_50330201_94_dialog_content = "Apapun jenis Eclipsites itu, kita hanya perlu melawan mereka!",
  ui_story_5033_50330201_95_dialog_content = "Pisau es!",
  ui_story_5033_50330202_1_dialog_content = "<size=45>Pisau es!!</size>",
  ui_story_5033_50330202_2_dialog_content = "Pergi dari sana, PlayerName!",
  ui_story_5033_50330202_3_dialog_content = "<size=45>Graaah!</size>",
  ui_story_5033_50330202_4_dialog_content = "(Saya telah melalui skenario yang sama persis ini jutaan kali sekarang!)",
  ui_story_5033_50330202_5_dialog_content = "(Ada cakar Eclipsite raksasa di atas kepalaku.)",
  ui_story_5033_50330202_6_dialog_content = "(Jika saya tidak merunduk, kepala saya akan terbelah dalam sedetik.)",
  ui_story_5033_50330202_7_dialog_content = "Menjauh!!",
  ui_story_5033_50330202_8_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5033_50330202_9_dialog_content = "...",
  ui_story_5033_50330202_10_dialog_content = "Apakah itu kapak? Apakah mereka benar-benar melawan Eclipsites dengan kapak?",
  ui_story_5033_50330202_11_dialog_content = "<color=#e8d9bb>*Memotong kapak*</color>",
  ui_story_5033_50330202_12_dialog_content = "<color=#e8d9bb>*Mengayunkan kapak dan memotong*</color>",
  ui_story_5033_50330202_13_dialog_content = "Mereka terlihat seperti ayunan yang serampangan, namun mereka menyerang organ vital dengan cara yang sama.",
  ui_story_5033_50330202_14_dialog_content = "Jelas, orang-orang ini tahu bagaimana menangani Eclipsites.",
  ui_story_5033_50330202_15_dialog_content = "Apakah kamu baik-baik saja, PlayerName? Anda tidak terlihat terluka.",
  ui_story_5033_50330202_16_dialog_content = "Aku baik-baik saja, hanya sedikit takut.",
  ui_story_5033_50330202_17_dialog_content = "Apakah mereka Euforia lokal?",
  ui_story_5033_50330202_18_dialog_content = "Hati-hati bagaimana Anda mengulitinya. Kulit dada harus utuh.",
  ui_story_5033_50330202_19_dialog_content = "Tarik kukunya, potong tanduknya. Oh, dan matanya juga...",
  ui_story_5033_50330202_20_dialog_content = "Aduh!",
  ui_story_5033_50330202_21_dialog_content = "Aku bilang untuk berhati-hati, bajingan! Beri aku pisau itu!",
  ui_story_5033_50330202_22_dialog_content = "Mata hancur. Taruh di tumpukan sampah dan bakar.",
  ui_story_5033_50330202_23_dialog_content = "Apakah mereka membedah Eclipsite? Apa yang mereka inginkan dengan semua itu?",
  ui_story_5033_50330202_24_dialog_content = "...",
  ui_story_5033_50330202_25_dialog_content = "Waktu untuk pergi, PlayerName.",
  ui_story_5033_50330202_26_dialog_content = "Sekarang? Tapi mereka menyelamatkanku, bukankah aku harus berterima kasih pada mereka?",
  ui_story_5033_50330202_27_dialog_content = "Dengarkan baik-baik.",
  ui_story_5033_50330202_28_dialog_content = "Perhatikan baik-baik apa yang mereka lakukan.",
  ui_story_5033_50330202_29_dialog_content = "Mereka tidak berusaha menyelamatkanmu. Fokus mereka bukan pada Anda sejak awal.",
  ui_story_5033_50330202_30_dialog_content = "Persembunyian dan organ Eclipsite, itulah yang mereka kejar. Mungkin dijual dengan harga yang sangat murah—satu seharga 200, dua seharga 300.",
  ui_story_5033_50330202_31_dialog_content = "Mereka mungkin telah mengikuti Eclipsites untuk sementara waktu sekarang. Kami hanya pejalan kaki jaminan.",
  ui_story_5033_50330202_32_dialog_content = "Euforia, kota yang terlupakan seperti apa adanya, jelas berjalan di atas seperangkat aturan yang sama sekali berbeda.",
  ui_story_5033_50330202_33_dialog_content = "<size=33>Jika kita tidak pergi sekarang, tempat ini akan menyedot kita dan menelan kita utuh.</size>",
  ui_story_5033_50330202_34_dialog_content = "Oke. Lalu mari—",
  ui_story_5033_50330202_35_dialog_content = "Tunggu, Anda orang luar.",
  ui_story_5033_50330202_36_dialog_content = "Anda tidak bisa datang dan pergi sesuka Anda di sini.",
  ui_story_5033_50330202_37_dialog_content = "<size=45>Kami tidak ingat memberi Anda izin untuk pergi!</size>",
  ui_story_5033_50330202_38_dialog_content = "<color=#e8d9bb>Dentang!</color>",
  ui_story_5033_50330202_39_dialog_content = "Jangan bilang kamu tidak tahu aturan Euphoria.",
  ui_story_5033_50330202_40_dialog_content = "Dia baru saja membuat lubang di tanah ...",
  ui_story_5033_50330202_41_dialog_content = "<size=33>Saya rasa sekarang sudah terlambat.</size>",
  ui_story_5033_50330202_42_dialog_content = "Kabarnya Euphoria adalah tempat yang ramah yang membuat semua orang merasa diterima.",
  ui_story_5033_50330202_43_dialog_content = "Tentu saja, keramahan ini harus dibalas.",
  ui_story_5033_50330202_44_dialog_content = "Ini dia. Lakukan penghitungan Anda.",
  ui_story_5033_50330202_45_dialog_content = "Anda datang ke sini.",
  ui_story_5033_50330202_46_dialog_content = "Siapa, saya?",
  ui_story_5033_50330202_47_dialog_content = "Siapa lagi? <size=33>Hitung ini di sana.</size>",
  ui_story_5033_50330202_48_dialog_content = "Adapun Anda ... Bicaralah, dari mana Anda berasal?",
  ui_story_5033_50330202_49_dialog_content = "Kita...",
  ui_story_5033_50330202_50_dialog_content = "(Mengapa Corax hanya melirikku? Sekarang mungkin bukan waktunya untuk jujur.)",
  ui_story_5033_50330202_51_dialog_content = "(Tapi ini adalah kotapraja Umbraton, jadi kita mungkin bisa membuat mereka mundur jika mereka tahu kita dari sana.)",
  ui_story_5033_50330202_52_dialog_content = "Kami dari Eraveil, utara Lumopolis. Ini adalah kota kecil yang terisolasi dari seluruh dunia.",
  ui_story_5033_50330202_53_dialog_content = "Hah?",
  ui_story_5033_50330202_54_dialog_content = "Eraveil...",
  ui_story_5033_50330202_55_dialog_content = "Siapa yang kau coba bodohi?",
  ui_story_5033_50330202_56_dialog_content = "Itu benar.",
  ui_story_5033_50330202_57_dialog_content = "(Dia benar-benar menjualnya dengan wajah datar.)",
  ui_story_5033_50330202_58_dialog_content = "(Dia mungkin juga mencoba menyiratkan bahwa mereka sangat tidak berbudaya...)",
  ui_story_5033_50330202_59_dialog_content = "Uh, bos, saya pikir Eraveil adalah tempat yang nyata.",
  ui_story_5033_50330202_60_dialog_content = "Baik. Pertanyaan berikutnya: apa yang Anda lakukan, dan mengapa Anda ada di sini?",
  ui_story_5033_50330202_61_dialog_content = "Kami di sini untuk bisnis, menjual sampah, Anda tahu bagaimana kelanjutannya. Hanya mencoba mengikis.",
  ui_story_5033_50330202_62_dialog_content = "Lalu mengapa Anda tidak memiliki apa-apa pada Anda?",
  ui_story_5033_50330202_63_dialog_content = "Kami hanya memeriksa tempat itu. Dan kami memang membawa persembahan, bukan?",
  ui_story_5033_50330202_64_dialog_content = "Adapun siapa kita, dia sopir saya. Dan aku, aku—",
  ui_story_5033_50330202_65_dialog_content = "<size=45>Saya sudah selesai menghitung!</size>",
  ui_story_5033_50330202_66_dialog_content = "Saya mendapat total 1.235! <size=33>Itu uang yang banyak, bos. Keduanya kaya.</size>",
  ui_story_5033_50330202_67_dialog_content = "Baiklah.",
  ui_story_5033_50330202_68_dialog_content = "Melihat kami telah memberikan persembahan kami, saya pikir kami dapat membatalkan upacara penyambutan kecil ini.",
  ui_story_5033_50330202_69_dialog_content = "Kami akan pergi sekarang. Tidak perlu menemani kami.",
  ui_story_5033_50330202_70_dialog_content = "Anda memang mengeluarkan uang, tapi tidak cukup.",
  ui_story_5033_50330202_71_dialog_content = "Apa maksudmu?",
  ui_story_5033_50330202_72_dialog_content = "Harganya baru saja naik.",
  ui_story_5033_50330202_73_dialog_content = "Berapa harganya?",
  ui_story_5033_50330202_74_dialog_content = "20.000.",
  ui_story_5033_50330202_75_dialog_content = "Dan itu akan dilakukan?",
  ui_story_5033_50330202_76_dialog_content = "Mari kita lihat dulu.",
  ui_story_5033_50330202_77_dialog_content = "Mereka merampok kita, Corax! Mereka tidak akan membiarkan kita pergi bahkan jika kita memberi mereka semua uang kita.",
  ui_story_5033_50330202_78_dialog_content = "Jangan khawatir.",
  ui_story_5033_50330202_79_dialog_content = "Saya mendapat 20.000 pada saya. Anda bahkan dapat meminta lebih banyak, tetapi Anda harus datang untuk mengambilnya sendiri.",
  ui_story_5033_50330202_80_dialog_content = "Hanya ada dua dari kami dan selusin dari Anda. Tidak ada alasan bagi Anda untuk takut.",
  ui_story_5033_50330202_81_dialog_content = "<color=#e8d9bb>Jepret!</color>",
  ui_story_5033_50330202_82_dialog_content = "<size=45>Aduh!</size>",
  ui_story_5033_50330202_83_dialog_content = "Bos!!!!",
  ui_story_5033_50330202_84_dialog_content = "Apakah Anda memiliki keinginan kematian sialan?!",
  ui_story_5033_50330202_85_dialog_content = "(Tapi lengannya patah!)",
  ui_story_5033_50330202_86_dialog_content = "(Itu menjuntai seperti mie basah.)",
  ui_story_5033_50330202_87_dialog_content = "(Namun itu diregenerasi dalam sedetik.)",
  ui_story_5033_50330202_88_dialog_content = "Berhenti berteriak begitu keras. Lenganmu baik-baik saja.",
  ui_story_5033_50330202_89_dialog_content = "Lihat saja sendiri.",
  ui_story_5033_50330202_90_dialog_content = "Tapi itu rusak, dan aku merasakannya!",
  ui_story_5033_50330202_91_dialog_content = "K-kamu—",
  ui_story_5033_50330202_92_dialog_content = "Simpan uangnya. Tepatnya 20.000. Apakah Anda tidak ingin tahu apa yang saya lakukan untuk mencari nafkah?",
  ui_story_5033_50330202_93_dialog_content = "Saya seorang dokter.",
  ui_story_5033_50330202_94_dialog_content = "Aku bisa menyembuhkanmu, dan aku juga bisa menghancurkan setiap tulang di tubuhmu.",
  ui_story_5033_50330202_95_dialog_content = "Bukan hanya Anda, tetapi semua orang di belakang Anda juga.",
  ui_story_5033_50330202_96_dialog_content = "...",
  ui_story_5033_50330202_97_dialog_content = "Jadi, apakah kita bebas untuk pergi sekarang?",
  ui_story_5033_50330202_98_dialog_content = "Anda tunggu saja! Anda akan menyesali ini!",
  ui_story_5033_50330301_1_dialog_content = "(Kami akhirnya menyingkirkan mereka...)",
  ui_story_5033_50330301_2_dialog_content = "Mengapa Anda membuang begitu banyak waktu dengan mereka, Corax?",
  ui_story_5033_50330301_3_dialog_content = "Anda bisa saja menjatuhkan nama Istvan.",
  ui_story_5033_50330301_4_dialog_content = "Mereka mungkin terlihat kejam, tapi mereka hanyalah sekelompok bajingan jalanan.",
  ui_story_5033_50330301_5_dialog_content = "Tidak mungkin mereka menentang Shadowlord of Umbraton.",
  ui_story_5033_50330301_6_dialog_content = "Itu akan menjadi jalan keluar yang mudah, tetapi akan ada akibatnya.",
  ui_story_5033_50330301_7_dialog_content = "Umbraton sangat kuat, tetapi Shadowlord lebih suka menjaga hal-hal sederhana.",
  ui_story_5033_50330301_8_dialog_content = "Membawanya ke atas akan dianggap sebagai provokasi.",
  ui_story_5033_50330301_9_dialog_content = "Apakah itu sebabnya Anda memberi isyarat kepada saya sebelumnya?",
  ui_story_5033_50330301_10_dialog_content = "Ya. Tapi itu untuk keselamatan kita sendiri dan juga privasi Shadowlord.",
  ui_story_5033_50330301_11_dialog_content = "... Apakah ini benar-benar serius?",
  ui_story_5033_50330301_12_dialog_content = "Banyak Euphorian membenci Umbraton. \"Banyak\" adalah pernyataan yang meremehkan, sungguh.",
  ui_story_5033_50330301_13_dialog_content = "Keduanya belum melakukan bisnis yang layak satu sama lain selama bertahun-tahun.",
  ui_story_5033_50330301_14_dialog_content = "<color=#FFB400>Dua belas tahun yang lalu</color>, Darkover menyapu Umbraton dan semua wilayah sekitarnya.",
  ui_story_5033_50330301_15_dialog_content = "Kota-kota dari berbagai ukuran jatuh, memaksa Umbraton menjalani restrukturisasi.",
  ui_story_5033_50330301_16_dialog_content = "Ada kekacauan di mana-mana, dan Euphoria adalah salah satu kota yang paling terpukul.",
  ui_story_5033_50330301_17_dialog_content = "Eclipsites yang Umbraton kalahkan semuanya menyerbu masuk ke Euphoria.",
  ui_story_5033_50330301_18_dialog_content = "Tapi Shadowlord tidak memiliki kekuatan saat itu, jadi dia tidak bisa membantu siapa pun.",
  ui_story_5033_50330301_19_dialog_content = "Setelah perang mereda, teori konspirasi \"Umbraton menggunakan Darkover untuk menghancurkan Euphoria\" mulai beredar.",
  ui_story_5033_50330301_20_dialog_content = "Tapi saya pikir Anne mengatakan bahwa Euphoria milik pribadi?",
  ui_story_5033_50330301_21_dialog_content = "Apakah pemiliknya meninggalkannya begitu saja?",
  ui_story_5033_50330301_22_dialog_content = "Itu benar, tapi itu menjadi tanah tak bertuan setelah invasi Eclipsite.",
  ui_story_5033_50330301_23_dialog_content = "Para penyintas bersatu dan membentuk banyak <color=#FFB400>koperasi kecil</color>.",
  ui_story_5033_50330301_24_dialog_content = "Beberapa fasilitas pasokan dapat dipulihkan setelah perbaikan dasar.",
  ui_story_5033_50330301_25_dialog_content = "Begitu populasi di sekitarnya mulai bertambah, tempat-tempat tertentu kembali beroperasi.",
  ui_story_5033_50330301_26_dialog_content = "Koperasi juga secara bertahap berkembang menjadi <color=#FFB400>geng</color>.",
  ui_story_5033_50330301_27_dialog_content = "Euforia pasti mengalami perubahan drastis...",
  ui_story_5033_50330301_28_dialog_content = "Jadi pemandangan di depan kita ini adalah hasil dari kota yang terjebak dalam stasis setelah perang.",
  ui_story_5033_50330301_29_dialog_content = "Jalanan mungkin kosong sekarang, tapi pasti ada mata di balik bayangan yang mengawasi kita.",
  ui_story_5033_50330301_30_dialog_content = "Baiklah, kita harus bergerak dan mencoba untuk tidak mencolok.",
  ui_story_5033_50330301_31_dialog_content = "Sebelum saya pergi, Taki memberi saya dua pilihan dan menghubungi kontaknya untuk keduanya.",
  ui_story_5033_50330301_32_dialog_content = "Opsi A adalah mengunjungi <color=#FFB400>Gustav</color> di Pekerjaan Ganjil Euphoria.",
  ui_story_5033_50330301_33_dialog_content = "Opsi B adalah menemukan <color=#FFB400>Nekoyashiki</color>, Pekerjaan Ganjil yang berkeliaran.",
  ui_story_5033_50330301_34_dialog_content = "Kedengarannya seperti pilihan antara sesuatu yang \"resmi\" dan sesuatu yang \"informal\".",
  ui_story_5033_50330301_35_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5033_50330301_36_option_content = "Gustav Pekerjaan Ganjil di Euforia.",
  ui_story_5033_50330301_37_dialog_content = "Odd Jobs lokal yang memiliki reputasi baik, seperti Taki, akan memiliki info yang lebih andal.",
  ui_story_5033_50330301_38_dialog_content = "Juga, Pekerjaan Ganjil resmi akan memiliki lebih banyak koneksi, sehingga lebih banyak prospek.",
  ui_story_5033_50330301_39_dialog_content = "Itu masuk akal, tapi...",
  ui_story_5033_50330301_40_dialog_content = "Kami akan diekspos begitu kami pergi ke sana.",
  ui_story_5033_50330301_41_dialog_content = "Semua geng lain yang memiliki koneksi di sana akan menangkap angin dari kita.",
  ui_story_5033_50330301_42_dialog_content = "Kedengarannya agak berbahaya...",
  ui_story_5033_50330301_43_option_content = "Nekoyashiki, Pekerjaan Ganjil yang berkeliaran.",
  ui_story_5033_50330301_44_dialog_content = "Dia terdengar penuh teka-teki, dan tidak ada yang akan memperhatikan jika kita mencoba menemukannya.",
  ui_story_5033_50330301_45_dialog_content = "Dan Odd Jobs yang berkeliaran mungkin memiliki info rahasia.",
  ui_story_5033_50330301_46_dialog_content = "Kau benar.",
  ui_story_5033_50330301_47_dialog_content = "Kontak seperti itu sebenarnya lebih aman.",
  ui_story_5033_50330301_48_dialog_content = "Ayo cari Nekoyashiki ini.",
  ui_story_5033_50330301_49_dialog_content = "Apakah dia bisa diandalkan?",
  ui_story_5033_50330301_50_dialog_content = "Ini bukan masalah keandalan, tetapi kepercayaan, dengan Odd Jobs.",
  ui_story_5033_50330301_51_dialog_content = "Karena hanya kita yang bisa menentukan apa yang bisa dipercaya?",
  ui_story_5033_50330301_52_dialog_content = "Sangat cerdas.",
  ui_story_5033_50330301_53_dialog_content = "Bagi Gustav, Nekoyashiki hanyalah gorengan kecil.",
  ui_story_5033_50330301_54_dialog_content = "Jika Anda akhirnya pergi bersamanya, akan sulit untuk melacaknya.",
  ui_story_5033_50330301_55_dialog_content = "Keberadaannya tidak dapat diprediksi, tetapi dia meninggalkan simbol, biasanya di suatu tempat di gedung tempat dia berada...",
  ui_story_5033_50330301_56_dialog_content = "Itu yang Taki katakan padaku. Adapun simbol ...",
  ui_story_5033_50330301_57_dialog_content = "Apakah itu <color=#FFB400>grafiti berbentuk bekas luka</color>?",
  ui_story_5033_50330301_58_dialog_content = "Bagaimana Anda tahu, PlayerName?",
  ui_story_5033_50330301_59_dialog_content = "Saya baru saja melihat satu. Lihat, itu ada di papan nama restoran itu.",
  ui_story_5033_50330301_60_dialog_content = "Seolah-olah itu memberi isyarat bagi kita untuk datang.",
  ui_story_5033_50330301_61_dialog_content = "Aku tahu tidak ada yang terpeleset oleh penjaja intel ini.",
  ui_story_5033_50330301_62_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_5033_50330301_63_dialog_content = "Ada yang masuk?",
  ui_story_5033_50330301_64_dialog_content = "Disini sangat sepi. Apakah restoran ini ditinggalkan?",
  ui_story_5033_50330301_65_dialog_content = "... Tidak!",
  ui_story_5033_50330301_66_dialog_content = "Turun, Corax!",
  ui_story_5033_50330301_67_dialog_content = "<color=#e8d9bb>Aduh... Bang!</color>",
  ui_story_5033_50330301_68_dialog_content = "Sial, merindukan mereka.",
  ui_story_5033_50330301_69_dialog_content = "Keluar dari jalan. Giliran saya!",
  ui_story_5033_50330301_70_dialog_content = "<color=#e8d9bb>Aduh... Bang!</color>",
  ui_story_5033_50330301_71_dialog_content = "Anda lagi?! Kami datang dengan damai!",
  ui_story_5033_50330301_72_dialog_content = "Kami lambat dalam undian terakhir kali.",
  ui_story_5033_50330301_73_dialog_content = "Anda membuat marah orang yang salah ketika Anda mematahkan lengan bos.",
  ui_story_5033_50330301_74_dialog_content = "<size=33>Apakah kita tidak berada di tempat yang tepat?</size>",
  ui_story_5033_50330301_75_dialog_content = "<size=33>Tidak mungkin, informasi Taki tidak pernah salah.</size>",
  ui_story_5033_50330301_76_dialog_content = "<size=33>Mungkin ada lebih banyak situasi ini daripada yang kita pikirkan.</size>",
  ui_story_5033_50330301_77_dialog_content = "Sudahlah. Ayolah, kita harus membela diri.",
  ui_story_5033_50330301_78_dialog_content = "Hah?",
  ui_story_5033_50330301_79_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5033_50330301_80_dialog_content = "Anda berani melawan?",
  ui_story_5033_50330301_81_dialog_content = "Graah...",
  ui_story_5033_50330301_82_dialog_content = "Eclipsites, di atas geng? Berantakan sekali.",
  ui_story_5033_50330301_83_dialog_content = "Kita harus menyingkirkan Eclipsites dulu!",
  ui_story_5033_50330302_1_dialog_content = "Graah...",
  ui_story_5033_50330302_2_dialog_content = "Ada terlalu banyak dari mereka. Kita harus istirahat untuk itu, PlayerName!",
  ui_story_5033_50330302_3_dialog_content = "Ke mana?!",
  ui_story_5033_50330302_4_dialog_content = "Ayo pergi dari sini dulu!",
  ui_story_5033_50330302_5_dialog_content = "Mereka kabur, bos!",
  ui_story_5033_50330302_6_dialog_content = "Kejar mereka!",
  ui_story_5033_50330302_7_dialog_content = "<color=#e8d9bb>Sebuah gang di Euforia</color>",
  ui_story_5033_50330302_8_dialog_content = "Heh, heh...",
  ui_story_5033_50330302_9_dialog_content = "(Saya tidak tahu di mana saya sekarang ...)",
  ui_story_5033_50330302_10_dialog_content = "Keren!!!",
  ui_story_5033_50330302_11_dialog_content = "(Dan saya punya Eclipsites di ekor saya!)",
  ui_story_5033_50330302_12_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5033_50330302_13_dialog_content = "Ugh...",
  ui_story_5033_50330302_14_dialog_content = "Kutukan... Mundur!",
  ui_story_5033_50330302_15_dialog_content = "Hei, kenapa Eclipsites mengejar mereka?",
  ui_story_5033_50330302_16_dialog_content = "<size=45><color=#e8d9bb>Menjerit!</color></size>",
  ui_story_5033_50330302_17_dialog_content = "Siapa di sana?!",
  ui_story_5033_50330302_18_dialog_content = "(Itu adalah suara yang aneh...)",
  ui_story_5033_50330302_19_dialog_content = "Grah...",
  ui_story_5033_50330302_20_dialog_content = "(Eklipsites juga hilang!)",
  ui_story_5033_50330302_21_dialog_content = "Aku baru saja pergi sebentar, namun para preman mengambil alih markasku...",
  ui_story_5033_50330302_22_dialog_content = "Lanjutkan dan terima kasih. Saya menganggap penyelamatan sebagai permintaan pertama Anda.",
  ui_story_5033_50330302_23_dialog_content = "Tuan <color=#FFB400>Nekoyashiki</color>, saya kira?",
  ui_story_5033_50330302_24_dialog_content = "Jika bukan karena Taki, aku tidak akan banyak berurusan denganmu dan formalitas mewahmu.",
  ui_story_5033_50330302_25_dialog_content = "Panggil saja aku Nekoyashiki.",
  ui_story_5033_50330302_26_dialog_content = "Apa yang terjadi disana? Apa jeritan itu?",
  ui_story_5033_50330302_27_dialog_content = "Untuk bertahan. Saya tidak tahu mengapa, tetapi berteriak dengan cara yang benar membuat mereka menjauh.",
  ui_story_5033_50330302_28_dialog_content = "Aku tidak pandai menggunakan senjata, tapi setidaknya aku bisa membela diri dengan beberapa teriakan melawan Eclipsites.",
  ui_story_5033_50330302_29_dialog_content = "Dalam keadaan darurat, saya bahkan dapat menggunakannya dengan cara yang baru saja saya lakukan.",
  ui_story_5033_50330302_30_dialog_content = "Jadi, apakah Anda percaya padaku sekarang, teman-teman Taki?",
  ui_story_5033_50330302_31_dialog_content = "Itu sangat mengesankan. Saya kira itu sesuatu yang rahasia hanya untuk Anda.",
  ui_story_5033_50330302_32_dialog_content = "Punya nilai pasti. Sekarang beri tahu saya apa yang ingin Anda ketahui.",
  ui_story_5033_50330302_33_dialog_content = "Saya Corax, dan ini adalah PlayerName. Kami di sini untuk menyelidiki rantai pembunuhan berantai baru-baru ini di Umbraton.",
  ui_story_5033_50330302_34_dialog_content = "Saya tahu sedikit tentang si pembunuh sekarang, kecuali untuk modus operandi tertentu.",
  ui_story_5033_50330302_35_dialog_content = "Keberatan memberikan rincian lebih lanjut?",
  ui_story_5033_50330302_36_dialog_content = "Secara khusus, setiap korban meninggal karena luka robek yang aneh.",
  ui_story_5033_50330302_37_dialog_content = "Luka kecil yang seharusnya tidak berakibat fatal. Para korban akan tersandung seperti zombie sebelum tiba-tiba mati.",
  ui_story_5033_50330302_38_dialog_content = "(Mereka menemukan itu, persis seperti yang <color=#FFB400>dia</color> prediksi.)",
  ui_story_5033_50330302_39_dialog_content = "Hmm, itu cara yang kasar untuk pergi.",
  ui_story_5033_50330302_40_dialog_content = "Sepertinya Anda bukan orang yang bisa diremehkan, jika Anda bisa melacak jalan Anda ke sini hanya dari itu.",
  ui_story_5033_50330302_41_dialog_content = "Hanya <color=#FFB400>dia</color> yang tahu sejarah yang terkait dengan teknik itu di seluruh Euforia.",
  ui_story_5033_50330302_42_dialog_content = "?!",
  ui_story_5033_50330302_43_dialog_content = "Tolong jelaskan.",
  ui_story_5033_50330302_44_dialog_content = "Saya akan mengajak Anda melihat <color=#FFB400>Darah Gagak</color>. Mereka tahu lebih banyak daripada saya.",
  ui_story_5033_50330302_45_dialog_content = "<color=#e8d9bb>Aduh, aduh...</color>",
  ui_story_5033_50330302_46_dialog_content = "Saya melihat gagak sudah ada di sini.",
  ui_story_5033_50330302_47_dialog_content = "Itu artinya mereka menyambut kalian berdua, pengunjung dari Umbraton.",
  ui_story_5033_50330302_48_dialog_content = "<color=#e8d9bb>Di gang lain belum lama ini</color>",
  ui_story_5033_50330302_49_dialog_content = "(Oh tidak, jalan buntu!)",
  ui_story_5033_50330302_50_dialog_content = "<color=#e8d9bb>Cek, lempar, lempar...</color>",
  ui_story_5033_50330302_51_dialog_content = "(Apakah Pollux dan Casta mengikutiku?!)",
  ui_story_5033_50330302_52_dialog_content = "(Saya tidak ingin mati di sini!)",
  ui_story_5033_50330302_53_dialog_content = "Anda bersikeras mencari masalah, jadi sekarang masalah telah datang untuk menemukan Anda.",
  ui_story_5033_50330302_54_dialog_content = "T-Tapi aku tidak melakukan apa-apa selain mengemis uang dari dua pengunjung...",
  ui_story_5033_50330302_55_dialog_content = "Bisnis apa yang dimiliki Raven's Blood dengan mereka?",
  ui_story_5033_50330302_56_dialog_content = "Jangan berpikir Anda banyak yang bisa merangkak ke atas hanya karena dealer yang teduh telah turun seperti lalat!",
  ui_story_5033_50330302_57_dialog_content = "Euforia tidak akan pernah tunduk pada kalian berdua wanita gila!",
  ui_story_5033_50330302_58_dialog_content = "Begitu menurutmu?",
  ui_story_5033_50330302_59_dialog_content = "Jangan mendekat! Aku punya pisau!",
  ui_story_5033_50330302_60_dialog_content = "Aku bilang jangan mendekat!!",
  ui_story_5033_50330302_61_dialog_content = "Nngh, pisauku! A-Apa yang kamu pikir kamu lakukan?!",
  ui_story_5033_50330302_62_dialog_content = "Belati tidak cukup untuk melindungi diri sendiri. Ini lebih berbahaya daripada yang pernah Anda alami.",
  ui_story_5033_50330302_63_dialog_content = "Coba senjata yang lebih cocok untuk diri sendiri lain kali.",
  ui_story_5033_50330302_64_dialog_content = "Aku sama sekali tidak mengerti maksudmu.",
  ui_story_5033_50330302_65_dialog_content = "Aku baru saja menyelamatkanmu dari semua Eclipsites itu. Apakah Anda masih tidak mengerti situasi yang Anda hadapi?",
  ui_story_5033_50330302_66_dialog_content = "Apakah Anda terlalu padat untuk mengetahuinya?",
  ui_story_5033_50330302_67_dialog_content = "Ingrates tidak hidup lama di Euphoria.",
  ui_story_5033_50330302_68_dialog_content = "Ugh! Jauhkan pisau itu dariku! Oke, saya akan bicara, saya akan memberi tahu Anda semua yang saya tahu!",
  ui_story_5033_50330302_69_dialog_content = "Anda ditipu untuk datang ke sini bahkan tanpa tahu cara memegang belati.",
  ui_story_5033_50330302_70_dialog_content = "Saya akan memberi Anda sedikit firasat betapa kecilnya majikan Anda peduli pada hidup Anda.",
  ui_story_5033_50330302_71_dialog_content = "Apakah saya menggunakan leher Anda sebagai penyangga tergantung pada seberapa kooperatif Anda.",
  ui_story_5033_50330302_72_dialog_content = "Aku bilang aku akan bicara!",
  ui_story_5033_50330302_73_dialog_content = "Banyak penduduk lokal seperti saya berkumpul untuk melakukan penyergapan di kota.",
  ui_story_5033_50330302_74_dialog_content = "Berbaring dalam penyergapan?",
  ui_story_5033_50330302_75_dialog_content = "Ya, kepala desa tidak berpikir sudah waktunya untuk bergerak.",
  ui_story_5033_50330302_76_dialog_content = "Dia ingin kami menyusup ke geng dan berbaur dengan mereka di atas bar dan meja judi.",
  ui_story_5033_50330302_77_dialog_content = "Itu saja?",
  ui_story_5033_50330302_78_dialog_content = "Anda tidak pernah bertanya-tanya apa yang mereka ingin Anda lakukan selanjutnya?",
  ui_story_5033_50330302_79_dialog_content = "M-Pindahkan pedangnya!",
  ui_story_5033_50330302_80_dialog_content = "Oke, jadi saya mendengar sesuatu terjadi di sekitar geng beberapa hari yang lalu.",
  ui_story_5033_50330302_81_dialog_content = "Siapa pun yang mempekerjakan kami ingin kami menyebarkan <color=#FFB400>rumor</color> ke seluruh kota.",
  ui_story_5033_50330302_82_dialog_content = "Itu saja yang saya tahu, sumpah! Aku bahkan tidak tahu rumor macam apa itu!",
  ui_story_5033_50330302_83_dialog_content = "Aku tahu.",
  ui_story_5033_50330302_84_dialog_content = "Apakah Anda tidak akan membiarkan saya pergi? Saya memberi tahu Anda semua yang saya tahu!",
  ui_story_5033_50330302_85_dialog_content = "Izinkan saya memberi Anda pelajaran lain tentang rumah tentang bertahan hidup di Euforia ...",
  ui_story_5033_50330302_86_dialog_content = "Jangan percaya siapa pun di sini.",
  ui_story_5033_50330302_87_dialog_content = "Ah!",
  ui_story_5033_50330302_88_dialog_content = "Setiap saat, Anda hanya menjatuhkan mereka dan membuangnya ke tempat sampah.",
  ui_story_5033_50330302_89_dialog_content = "Jika orang mengetahui bahwa Pollux yang terhormat sebenarnya sangat penyayang...",
  ui_story_5033_50330302_90_dialog_content = "Bagaimana mereka masih bisa mempercayai reputasi yang terkait dengan nama itu?",
  ui_story_5033_50330302_91_dialog_content = "Mereka tidak seharusnya. Yang terbaik adalah tidak mempercayai siapa pun dalam Euforia. Apalagi saya.",
  ui_story_5033_50330302_92_dialog_content = "<color=#e8d9bb>Aduh, aduh...</color>",
  ui_story_5033_50330302_93_dialog_content = "Hmm, sesuatu terjadi di ujung Nekoyashiki.",
  ui_story_5033_50330302_94_dialog_content = "Ya, mereka melacak Nekoyashiki seperti yang saya perkirakan.",
  ui_story_5033_50330302_95_dialog_content = "Meskipun lebih cepat dari yang saya kira.",
  ui_story_5033_50330302_96_dialog_content = "Ayo pergi ke <color=#FFB400>tempat biasa</color> dan tunggu Nekoyashiki dan dua tamu dari Umbraton seperti yang kita bicarakan.",
  ui_story_5033_50330302_97_dialog_content = "Ini sama sekali tidak sepertimu, Pollux. Sekali lagi, mengapa kita bertemu mereka?",
  ui_story_5033_50330302_98_dialog_content = "Aku punya motif tersembunyi. Aku tahu Shadowlord mengirim mereka.",
  ui_story_5033_50330302_99_dialog_content = "Apakah ini tentang <color=#FFB400>anak-anak</color>?",
  ui_story_5033_50330302_100_dialog_content = "Anak-anak, dan Euphoria juga, tentu saja.",
  ui_story_5033_50330302_101_dialog_content = "Aku menunggu badai datang dan membasuh kotoran.",
  ui_story_5033_50330302_102_dialog_content = "Casta—",
  ui_story_5033_50330302_103_dialog_content = "Ya?",
  ui_story_5033_50330302_104_dialog_content = "Kapan langit Euphoria berubah menjadi abu-abu berlumpur abadi?",
  ui_story_5033_50330302_105_dialog_content = "Mm...",
  ui_story_5033_50330302_106_dialog_content = "Kapan itu dimulai, saya bertanya-tanya?",
  ui_story_5033_50330401_1_dialog_content = "Darah Raven yang Anda sebutkan... Apakah itu salah satu dari banyak geng Euphoria?",
  ui_story_5033_50330401_2_dialog_content = "Sebenarnya, Anda membuat keputusan yang tepat untuk mencari bantuan saya.",
  ui_story_5033_50330401_3_dialog_content = "Jika Anda pergi ke orang lain, Anda harus melewati rintangan untuk menemukan Raven's Blood.",
  ui_story_5033_50330401_4_dialog_content = "Geng ini hanya terdiri dari dua wanita: <color=#FFB400>Pollux</color> dan <color=#FFB400>Casta</color>, tetapi mereka tetap cocok untuk geng-geng besar.",
  ui_story_5033_50330401_5_dialog_content = "Pollux bukan satu untuk perebutan kekuasaan antara geng. Bahkan hanya segelintir orang yang mampu menemukannya.",
  ui_story_5033_50330401_6_dialog_content = "Apakah Pollux \"dia\" yang Anda sebutkan?",
  ui_story_5033_50330401_7_dialog_content = "Ya.",
  ui_story_5033_50330401_8_dialog_content = "Dia tahu kedatanganmu di Euphoria dan sedang menunggumu datang padaku.",
  ui_story_5033_50330401_9_dialog_content = "Lebih banyak telinga ke tanah sangat penting untuk bertahan hidup di sini, bukan?",
  ui_story_5033_50330401_10_dialog_content = "Ha, Anda tidak akan menangkap saya berdebat tentang itu, terutama dengan pengunjung prestise tersebut.",
  ui_story_5033_50330401_11_dialog_content = "Ngomong-ngomong, dia menyuruhku untuk membawa kalian sendiri padanya. Ke \"tempat biasa,\" seperti yang dia katakan.",
  ui_story_5033_50330401_12_dialog_content = "Mudah-mudahan, dia akan membantu dalam penyelidikan saya.",
  ui_story_5033_50330401_13_dialog_content = "Apakah Anda mencurigainya?",
  ui_story_5033_50330401_14_dialog_content = "Tenang, saya tidak akan menangkap siapa pun tanpa alasan.",
  ui_story_5033_50330401_15_dialog_content = "Bahkan jika saya memiliki tersangka, saya masih menginginkan bukti nyata sebelum membawa siapa pun.",
  ui_story_5033_50330401_16_dialog_content = "Mengapa? Tunggu apa lagi, korban lagi tertembak?",
  ui_story_5033_50330401_17_dialog_content = "Saya tidak akan pernah berharap lebih banyak orang yang tidak bersalah menjadi korban.",
  ui_story_5033_50330401_18_dialog_content = "Ini adalah masalah yang sangat serius, Tuan Nekoyashiki. Saya harap Anda dapat memperlakukannya dengan hormat.",
  ui_story_5033_50330401_19_dialog_content = "Astaga, kau punya tongkat di pantatmu, bukan? Saya hanya menemukan kecurigaan Anda tidak masuk akal.",
  ui_story_5033_50330401_20_dialog_content = "Itu tidak terdengar sangat meyakinkan datang dari saya karena saya adalah teman mereka, ya?",
  ui_story_5033_50330401_21_dialog_content = "Pokoknya, aku akan membawamu ke tempat mereka menunggu dulu.",
  ui_story_5033_50330401_22_dialog_content = "Kemudian Anda bisa memutuskan sendiri.",
  ui_story_5033_50330401_23_dialog_content = "(Dia terdengar sangat yakin akan kepolosan mereka...)",
  ui_story_5033_50330401_24_dialog_content = "Jadi, di mana tempat yang Anda bicarakan ini?",
  ui_story_5033_50330401_25_dialog_content = "Oh, kita hampir sampai.",
  ui_story_5033_50330401_26_dialog_content = "Kami akan pergi ke <color=#FFB400>gereja tua</color>. Dulu pemandangan untuk dilihat, sebelum ditinggalkan.",
  ui_story_5033_50330401_27_dialog_content = "(Sebuah gereja?)",
  ui_story_5033_50330401_28_dialog_content = "Biarawati tidak punya tempat di Euforia lagi.",
  ui_story_5033_50330401_29_dialog_content = "(Para biarawati semuanya sudah pergi, tapi gereja masih ada di sini, ya?)",
  ui_story_5033_50330401_30_dialog_content = "<color=#e8d9bb>Euphoria: Gereja Tua</color>",
  ui_story_5033_50330401_31_dialog_content = "Ini sama kumuhnya dengan semua bangunan lainnya.",
  ui_story_5033_50330401_32_dialog_content = "Dan seperti semua bangunan lainnya, itu hanya bagus untuk tempat berteduh.",
  ui_story_5033_50330401_33_dialog_content = "Euforia tidak pernah memiliki penyelamat, dan tidak ada seorang pun di sini yang berdoa kepada dewa cahaya lagi.",
  ui_story_5033_50330401_34_dialog_content = "Kota ini telah dibersihkan dari biarawati selama beberapa tahun terakhir. Gereja ini tidak lagi milik denominasi apapun.",
  ui_story_5033_50330401_35_dialog_content = "Para biarawati dibersihkan? Oleh siapa?",
  ui_story_5033_50330401_36_dialog_content = "Jika saya tahu, saya tidak akan hidup cukup lama untuk berada di sini hari ini.",
  ui_story_5033_50330401_37_dialog_content = "Mungkin itu hanya takdir mereka. Anda tidak bernegosiasi dengan Kematian.",
  ui_story_5033_50330401_38_dialog_content = "Grim Reaper yang ada di mana-mana merenggut nyawa mereka beberapa hari kemudian!",
  ui_story_5033_50330401_39_dialog_content = "Mereka pasti mati karena Grim Reaper, yang tidak boleh dibicarakan!",
  ui_story_5033_50330401_40_dialog_content = "(Ini terdengar seperti apa yang dikatakan pria itu...)",
  ui_story_5033_50330401_41_dialog_content = "(Pembunuhan berantai, biarawati yang dibantai... Mungkinkah itu semua pekerjaan Grim Reaper?)",
  ui_story_5033_50330401_42_dialog_content = "Omong-omong, kami bertemu seorang biarawati dalam perjalanan ke sini.",
  ui_story_5033_50330401_43_dialog_content = "Kami berpisah setelah tiba. Aku ingin tahu bagaimana keadaannya sekarang.",
  ui_story_5033_50330401_44_dialog_content = "Apa? Benarkah itu?!",
  ui_story_5033_50330401_45_dialog_content = "Ya, dia datang bersama kami dari Umbraton. Jelas sekali dia adalah seorang biarawati.",
  ui_story_5033_50330401_46_dialog_content = "(Seorang biarawati dari Umbraton?)",
  ui_story_5033_50330401_47_dialog_content = "Anda harus memberi tahu Raven's Blood saat bertemu dengan mereka. Saya yakin mereka akan senang mendengarnya.",
  ui_story_5033_50330401_48_dialog_content = "<color=#e8d9bb>Sementara itu, di gang lain</color>",
  ui_story_5033_50330401_49_dialog_content = "…?",
  ui_story_5033_50330401_50_dialog_content = "Ada apa, Pollux?",
  ui_story_5033_50330401_51_dialog_content = "Jangan bilang bajingan itu masih ada.",
  ui_story_5033_50330401_52_dialog_content = "Tidak, itu bukan mereka.",
  ui_story_5033_50330401_53_dialog_content = "Tapi itulah satu-satunya hal yang saya yakini. Jejak itu datang dan pergi, yang berada di luar mereka.",
  ui_story_5033_50330401_54_dialog_content = "Tak seorang pun di Euphoria bisa melakukan itu.",
  ui_story_5033_50330401_55_dialog_content = "Santai. Bisa jadi hanya seekor kucing.",
  ui_story_5033_50330401_56_dialog_content = "Ayo pergi. Anak-anak sedang menunggu, dan Nekoyashiki akan segera muncul.",
  ui_story_5033_50330401_57_dialog_content = "Anda pergi ke depan. Saya ingin menggandakan kembali ke distrik perbelanjaan itu.",
  ui_story_5033_50330401_58_dialog_content = "Saya tidak benar-benar berpikir bajingan itu sepadan dengan waktu Anda.",
  ui_story_5033_50330401_59_dialog_content = "Siapa yang peduli dengan mereka?",
  ui_story_5033_50330401_60_dialog_content = "Saya hanya ingin memberikan kejutan untuk anak-anak.",
  ui_story_5033_50330401_61_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330401_62_dialog_content = "...",
  ui_story_5033_50330401_63_dialog_content = "(Apakah dia... merasakan kehadiranku?)",
  ui_story_5033_50330401_64_dialog_content = "<color=#e8d9bb>Meong...</color>",
  ui_story_5033_50330401_65_dialog_content = "Meong!",
  ui_story_5033_50330401_66_dialog_content = "Bunuh Pollux.",
  ui_story_5033_50330401_67_dialog_content = "...",
  ui_story_5033_50330401_68_dialog_content = "(... Kesabaran adalah kebajikan yang terlupakan, tampaknya.)",
  ui_story_5033_50330401_69_dialog_content = "<color=#e8d9bb>*Menyobek kertas*</color>",
  ui_story_5033_50330401_70_dialog_content = "Eh?",
  ui_story_5033_50330401_71_dialog_content = "<size=45>Gratis!</size>",
  ui_story_5033_50330401_72_dialog_content = "(Waktu yang tepat.)",
  ui_story_5033_50330401_73_dialog_content = "(Aku akan menghancurkanmu bersama dengan sampah ini.)",
  ui_story_5033_50330502_1_dialog_content = "<color=#e8d9bb>Geng Istvan di Umbraton</color>",
  ui_story_5033_50330502_2_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_5033_50330502_3_dialog_content = "Sepertinya badai akan datang.",
  ui_story_5033_50330502_4_dialog_content = "Sekumpulan awan, artinya bayangan akan menyebar ke seluruh Umbraton.",
  ui_story_5033_50330502_5_dialog_content = "Hanya masalah waktu sebelum mencapai Euphoria juga.",
  ui_story_5033_50330502_6_dialog_content = "Apakah Anda khawatir tentang penyelidikan Corax?",
  ui_story_5033_50330502_7_dialog_content = "Tidak.",
  ui_story_5033_50330502_8_dialog_content = "Saya hanya menunggu cuaca berubah.",
  ui_story_5033_50330502_9_dialog_content = "Selama beberapa hari terakhir, saya mendapatkan perspektif baru tentang kasus Corax.",
  ui_story_5033_50330502_10_dialog_content = "Tapi saya belum punya bukti pasti, jadi itu hanya spekulasi pribadi.",
  ui_story_5033_50330502_11_dialog_content = "Tidak masalah. Mari kita dengarkan.",
  ui_story_5033_50330502_12_dialog_content = "Saya baru menyadarinya saat memindai koran bekas.",
  ui_story_5033_50330502_13_dialog_content = "Empat belas tahun yang lalu, sesuatu terjadi di Euphoria yang menyebabkan kehebohan di Umbraton.",
  ui_story_5033_50330502_14_dialog_content = "Pada saat itu, tempat itu lebih dikenal sebagai \"Tanah Ajaib.\"",
  ui_story_5033_50330502_15_dialog_content = "Anda mungkin tahu tentang insiden itu lebih baik daripada saya.",
  ui_story_5033_50330502_16_dialog_content = "Hmm, saya ingat <color=#FFB400>Insiden Gemini</color>...",
  ui_story_5033_50330502_17_dialog_content = "Ya. Saat itulah pertempuran bawah tanah adalah mode di Euphoria dan membuat banyak orang kaya.",
  ui_story_5033_50330502_18_dialog_content = "Bahkan kapten tentara bayaran di Euphoria berhenti mengandalkan komisi untuk uang.",
  ui_story_5033_50330502_19_dialog_content = "Itu tidak biasa. Satu-satunya komisi yang tersisa untuk mereka mungkin bertarung di arena bawah tanah itu.",
  ui_story_5033_50330502_20_dialog_content = "Apa ironi.",
  ui_story_5033_50330502_21_dialog_content = "Bagaimanapun, seseorang menarik tali di belakang layar, dan di bawah perintah mereka, kapten melatih dua bintang yang sedang naik daun.",
  ui_story_5033_50330502_22_dialog_content = "Mereka adalah dua gadis yang sangat muda yang dilatih di bawah dua rejimen yang sama sekali berbeda oleh kapten ...",
  ui_story_5033_50330502_23_dialog_content = "Satu menjalani pelatihan tentara bayaran internal dan berspesialisasi dalam gaya bertarung mereka.",
  ui_story_5033_50330502_24_dialog_content = "Yang lain bergabung dengan tentara bayaran lain di lapangan dalam pertempuran yang sebenarnya, melatih kemampuan beradaptasinya untuk semua situasi.",
  ui_story_5033_50330502_25_dialog_content = "Euphoria menyebut mereka kembar Gemini kelompok tentara bayaran.",
  ui_story_5033_50330502_26_dialog_content = "Namun pertunjukan resmi pertama yang mereka dapatkan ...",
  ui_story_5033_50330502_27_dialog_content = "Adalah <color=#FFB400>pertarungan sampai mati</color> melawan satu sama lain di sebuah arena.",
  ui_story_5033_50330502_28_dialog_content = "Biar kutebak. Tidak ada pertunjukan histeris emosional sama sekali dan satu membunuh titik kosong lainnya, kan?",
  ui_story_5033_50330502_29_dialog_content = "Ya.",
  ui_story_5033_50330502_30_dialog_content = "Tidak ada laporan tentang bagaimana perkelahian itu terjadi, tetapi menurut gosip dari saksi mata ...",
  ui_story_5033_50330502_31_dialog_content = "Anak yang selamat terluka parah dengan luka robek kecil di sekujur tubuhnya. Dia praktis sudah mati.",
  ui_story_5033_50330502_32_dialog_content = "Setelah kejadian itu, dia menghilang sama sekali, tidak pernah terlihat lagi.",
  ui_story_5033_50330502_33_dialog_content = "Publik kehilangan minat padanya dalam kekacauan yang melanda Umbraton beberapa tahun kemudian.",
  ui_story_5033_50330502_34_dialog_content = "Menurutmu gadis yang mati sebenarnya <color=#FFB400>masih hidup</color>.",
  ui_story_5033_50330502_35_dialog_content = "Ya.",
  ui_story_5033_50330502_36_dialog_content = "Itu terlalu sederhana, bukan? Aku tidak ragu dia tidak bisa selamat, hanya saja...",
  ui_story_5033_50330502_37_dialog_content = "Kami tidak yakin dia satu-satunya yang tahu teknik itu.",
  ui_story_5033_50330502_38_dialog_content = "Bagaimanapun, Euforia tidak lagi seperti dulu.",
  ui_story_5033_50330502_39_dialog_content = "Sebelum Krisis Darkover, perusahaan tentara bayaran itu membual beberapa anggota yang bisa menggunakan keterampilan itu, dan mereka mengajari orang lain...",
  ui_story_5033_50330502_40_dialog_content = "Itu banyak calon tersangka.",
  ui_story_5033_50330502_41_dialog_content = "Anda benar, itulah sebabnya ini hanya spekulasi.",
  ui_story_5033_50330502_42_dialog_content = "Namun, katakanlah ada yang selamat dari pertandingan kematian yang naas itu, dan mereka hidup tanpa nama sampai sekarang.",
  ui_story_5033_50330502_43_dialog_content = "Itu bukan hal yang baik untuk Umbraton atau Euphoria.",
  ui_story_5033_50330502_44_dialog_content = "Tahukah Anda apa hal tersulit bagi peserta reguler dalam pertempuran bawah tanah?",
  ui_story_5033_50330502_45_dialog_content = "Ini bukan bertahan hidup, kan? Karena hidup dan mati adalah setara untuk kursus di sana.",
  ui_story_5033_50330502_46_dialog_content = "Ini segera memotong jaringan busuk dari tubuh Anda.",
  ui_story_5033_50330502_47_dialog_content = "Sesuatu yang begitu sederhana?",
  ui_story_5033_50330502_48_dialog_content = "Karena jaringan tua mencegah pembentukan jaringan sehat.",
  ui_story_5033_50330502_49_dialog_content = "Mengingat waktu, itu merusak fisik Anda dan merampas hak istimewa Anda untuk bersaing.",
  ui_story_5033_50330502_50_dialog_content = "Itu akan menjadi pekerjaan untuk seorang dokter, kan?",
  ui_story_5033_50330502_51_dialog_content = "Saya akan meminta dokter yang paling saya percaya untuk menanganinya.",
  ui_story_5033_50330502_52_dialog_content = "Tapi sekali lagi, bukankah gadis lain seharusnya juga selamat?",
  ui_story_5033_50330502_53_dialog_content = "Setidaknya, ini membuktikan bahwa tidak semua orang yang terkena teknik pedang itu mati.",
  ui_story_5033_50330502_54_dialog_content = "<color=#e8d9bb>Ketuk, ketuk, ketuk—</color>",
  ui_story_5033_50330502_55_dialog_content = "Paman Istvan? Korban yang ditemukan Corax... Dia sudah bangun sekarang.",
  ui_story_5033_50330502_56_dialog_content = "Ah, berbicara tentang iblis.",
  ui_story_5033_50330601_1_dialog_content = "Silakan.",
  ui_story_5033_50330601_2_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_5033_50330601_3_dialog_content = "Lihat, semuanya! Nekoyashiki kembali!",
  ui_story_5033_50330601_4_dialog_content = "Diam. Tidak terlalu keras, Latan. Saya mencari Casta, apakah Anda melihatnya?",
  ui_story_5033_50330601_5_dialog_content = "Casta keluar untuk mengambil roti. Kau ingin aku pergi menjemputnya?",
  ui_story_5033_50330601_6_dialog_content = "Katakan padanya kita punya tamu dari Umbraton.",
  ui_story_5033_50330601_7_dialog_content = "Oke! Kamu bisa bermain dengan yang lain sementara aku pergi menjemputnya!",
  ui_story_5033_50330601_8_dialog_content = "Apakah Anda membawakan kami camilan, Nekoyashiki?",
  ui_story_5033_50330601_9_dialog_content = "Tentu saja.",
  ui_story_5033_50330601_10_dialog_content = "Kemarilah, Nekoyashiki! Membungkuk, saya menemukan sesuatu yang bagus untuk Anda!",
  ui_story_5033_50330601_11_dialog_content = "H-Hei, jangan menarikku seperti itu, nak...",
  ui_story_5033_50330601_12_dialog_content = "Wow... Kenapa banyak sekali anak-anak disini?",
  ui_story_5033_50330601_13_dialog_content = "Anak-anak ini semua diambil oleh Raven's Blood, dan... Aduh! Hei, untuk apa kau menarik rambutku?!",
  ui_story_5033_50330601_14_dialog_content = "Heee! Lihat, saya menemukan kecoa ini tempo hari! Tidak mudah untuk menangkapnya... Apakah kamu menyukainya?",
  ui_story_5033_50330601_15_dialog_content = "Anda bajingan kecil, ke sini!",
  ui_story_5033_50330601_16_dialog_content = "Oh tidak, Nekoyashiki gila! Melarikan diri!!",
  ui_story_5033_50330601_17_dialog_content = "Sepertinya dia tidak punya waktu untuk menjelaskan semuanya padaku sekarang.",
  ui_story_5033_50330601_18_dialog_content = "Tidak banyak yang bisa dijelaskan.",
  ui_story_5033_50330601_19_dialog_content = "Sebagian besar anak-anak ini berakhir di sini setelah ditinggalkan di jalanan.",
  ui_story_5033_50330601_20_dialog_content = "Beberapa menjadi yatim piatu setelah orang tua mereka dibunuh oleh kekerasan geng, dan yang lainnya diselamatkan dari kriminal bawah tanah.",
  ui_story_5033_50330601_21_dialog_content = "Sampai rumah yang aman dan cocok ditemukan untuk mereka, anak-anak ini berada di bawah perlindungan Raven's Blood. Itu kami.",
  ui_story_5033_50330601_22_dialog_content = "Anda pasti Casta yang disebutkan Nekoyashiki.",
  ui_story_5033_50330601_23_dialog_content = "Kami—",
  ui_story_5033_50330601_24_dialog_content = "Tidak perlu perkenalan; kami tahu persis mengapa Anda di sini dan apa yang Anda selidiki. Mari kita tunggu Pollux kembali sebelum kita berbicara.",
  ui_story_5033_50330601_25_dialog_content = "Saya masih perlu memberi makan bajingan ini.",
  ui_story_5033_50330601_26_dialog_content = "Tidak apa-apa. Kami tidak keberatan menunggu.",
  ui_story_5033_50330601_27_dialog_content = "Baiklah, semuanya! Ini hampir tidur siang, jadi selesaikan makan rotimu dan langsung tidur!",
  ui_story_5033_50330601_28_dialog_content = "Oke!",
  ui_story_5033_50330601_29_dialog_content = "*Meringis* Mereka akhirnya melepaskan rambutku... Anak-anak ini adalah sesuatu yang lain.",
  ui_story_5033_50330601_30_dialog_content = "Jika sudah selesai, mari kita lanjutkan percakapan kita.",
  ui_story_5033_50330601_31_dialog_content = "Karena saya anggota Odd Jobs, saya akan memberi tahu semua orang tentang situasinya.",
  ui_story_5033_50330601_32_dialog_content = "Mengenai dua tamu kita di sini, aku mengerti bahwa Taki mengarahkanmu ke arahku.",
  ui_story_5033_50330601_33_dialog_content = "Namun, Raven's Blood jauh lebih berpengetahuan tentang Euphoria, dan dapat membantu Anda lebih banyak daripada yang saya bisa.",
  ui_story_5033_50330601_34_dialog_content = "Sedangkan untuk kalian para wanita Raven's Blood, saya telah membawakan orang-orang yang Anda minta, jadi sekarang saya akan menyerahkan sisanya kepada Anda.",
  ui_story_5033_50330601_35_dialog_content = "Aku akan pergi sekarang, karena aku masih ada urusan lain yang harus kuurus.",
  ui_story_5033_50330601_36_dialog_content = "Pergilah, jangan mengganggu kami dengan kehadiranmu yang menyebalkan. Kami akan memanggil Anda jika kami membutuhkan Anda.",
  ui_story_5033_50330601_37_dialog_content = "Aduh, itu menyakitkan. Menyingkirkanku setelah kau selesai menggunakanku?",
  ui_story_5033_50330601_38_dialog_content = "Andalah yang mengatakan Anda akan pergi, jadi pergilah. Saya masih punya roti untuk disajikan.",
  ui_story_5033_50330601_39_dialog_content = "Biarkan saya membantu Anda, Casta!",
  ui_story_5033_50330601_40_dialog_content = "Saya juga bisa membantu! Saya juga bisa membantu!",
  ui_story_5033_50330601_41_dialog_content = "Baik-baik saja maka. Latan, Anda dapat membagi roti ini di antara anak-anak yang lebih muda. Schewe, Anda bisa membagikan mentega, dan pastikan si kecil mendapat tambahan.",
  ui_story_5033_50330601_42_dialog_content = "Siap!",
  ui_story_5033_50330601_43_dialog_content = "Tentu, saya tahu di mana menteganya. Aku akan pergi mendapatkannya!",
  ui_story_5033_50330601_44_dialog_content = "Maaf, tapi saya harus bertanya... Bagaimana anak-anak mengalami luka-luka itu?",
  ui_story_5033_50330601_45_dialog_content = "Apakah Anda pikir anak yatim piatu akan merasa nyaman di jalanan Euphoria?",
  ui_story_5033_50330601_46_dialog_content = "Mereka terluka oleh orang lain, jadi kami membalut luka mereka... Sesederhana itu.",
  ui_story_5033_50330601_47_dialog_content = "Apakah Anda keberatan jika saya melihat luka mereka? Saya adalah seorang dokter pada suatu waktu.",
  ui_story_5033_50330601_48_dialog_content = "Seorang dokter, ya?",
  ui_story_5033_50330601_49_dialog_content = "Saya dapat melihat bahwa luka mereka telah dibungkus dengan sangat hati-hati, dan perbannya cukup bersih.",
  ui_story_5033_50330601_50_dialog_content = "Tetapi beberapa anak terlihat sedikit lebih buruk untuk dipakai. Mereka akan membutuhkan perhatian ekstra.",
  ui_story_5033_50330601_51_dialog_content = "Heh, itu pasti hari keberuntungan kita. Anda harus menunggu sampai mereka selesai makan.",
  ui_story_5033_50330601_52_dialog_content = "(Hmm? Apakah seseorang menarik tanganku?)",
  ui_story_5033_50330601_53_dialog_content = "Ya? Apakah ada yang salah, gadis kecil?",
  ui_story_5033_50330601_54_dialog_content = "Um... N-Nekoyashiki bilang dia meninggalkan permen di sakumu...",
  ui_story_5033_50330601_55_dialog_content = "A-Dan aku harus bertanya padamu apakah aku menginginkannya.",
  ui_story_5033_50330601_56_dialog_content = "Kapan Nekoyashiki memasukkan permen ke dalam sakuku? Kenapa aku tidak menyadarinya...",
  ui_story_5033_50330601_57_dialog_content = "Hah? Lihat itu. Benar-benar ada permen di sakuku!",
  ui_story_5033_50330601_58_dialog_content = "I-Lalu... Bolehkah aku minta?",
  ui_story_5033_50330601_59_dialog_content = "Tentu saja Anda bisa! Ini dia. Maaf membuat anda menunggu.",
  ui_story_5033_50330601_60_dialog_content = "Terima kasih!",
  ui_story_5033_50330601_61_dialog_content = "Hai! Jangan makan terlalu banyak makanan manis sebelum makan!",
  ui_story_5033_50330601_62_dialog_content = "Oh… Baiklah.",
  ui_story_5033_50330601_63_dialog_content = "<color=#e8d9bb>Kruuk...</color>",
  ui_story_5033_50330601_64_dialog_content = "Lapar?",
  ui_story_5033_50330601_65_dialog_content = "M-Maaf. Semua yang berlarian itu membangkitkan nafsu makan. Sayangnya, saya tidak bisa berbuat apa-apa tentang perut saya yang keroncongan.",
  ui_story_5033_50330601_66_dialog_content = "Saya berjanji saya tidak di sini untuk mencuri roti dari anak-anak sekalipun.",
  ui_story_5033_50330601_67_dialog_content = "Hah, kalian berdua adalah duo yang cukup menarik. Seorang dokter yang berubah menjadi pembunuh, dan seorang anak dalam tubuh remaja.",
  ui_story_5033_50330601_68_dialog_content = "Mungkin Pollux benar mengundang Anda ke sini.",
  ui_story_5033_50330601_69_dialog_content = "Memang, selalu lebih pintar untuk bekerja dengan orang-orang Umbraton daripada melawan mereka.",
  ui_story_5033_50330601_70_dialog_content = "Bau itu — itu croissant!",
  ui_story_5033_50330601_71_dialog_content = "Itu benar, dan saya membawa banyak untuk semua orang, jadi kalian semua bisa makan sepuasnya hari ini.",
  ui_story_5033_50330601_72_dialog_content = "Pergi menyapa tamu kami, Pollux. Saya bisa membagikan ini sendiri. Baiklah, siapa pun yang ingin croissant, ikut saya!",
  ui_story_5033_50330601_73_dialog_content = "Oke!",
  ui_story_5033_50330601_74_dialog_content = "Anda berdua lebih dari diterima untuk memiliki beberapa juga.",
  ui_story_5033_50330601_75_dialog_content = "Terima kasih, kami akan membantu diri kami sendiri kalau begitu.",
  ui_story_5033_50330601_76_dialog_content = "Di Sini, PlayerName.",
  ui_story_5033_50330601_77_dialog_content = "T-Terima kasih...",
  ui_story_5033_50330601_78_dialog_content = "Maaf, saya seharusnya membantu, tetapi yang saya lakukan hanyalah membuat segalanya lebih sulit.",
  ui_story_5033_50330601_79_dialog_content = "Jangan terlalu keras pada diri sendiri.",
  ui_story_5033_50330601_80_dialog_content = "Lagi pula, kami telah menemukan seseorang yang dapat bekerja sama dengan kami di sini yang dapat kami percayai. Itu jauh lebih baik dari yang saya harapkan.",
  ui_story_5033_50330601_81_dialog_content = "Mm. Seseorang yang akan menjalankan tempat penampungan di Euphoria hanya untuk anak-anak...",
  ui_story_5033_50330601_82_dialog_content = "Saya yakin mereka tidak hanya super kuat. Mereka juga harus benar-benar baik.",
  ui_story_5033_50330601_83_dialog_content = "Anda menyanjung kami. Tapi sungguh, merawat semua anak ini bukanlah tugas yang mudah.",
  ui_story_5033_50330601_84_dialog_content = "Anda belum mempertimbangkan untuk mengirim mereka ke tempat yang lebih baik?",
  ui_story_5033_50330601_85_dialog_content = "Umbraton memiliki banyak panti asuhan dengan semua fasilitas yang mereka butuhkan.",
  ui_story_5033_50330601_86_dialog_content = "Tentu kami sudah memikirkannya. Itulah alasan kami memutuskan untuk bekerja sama dengan Anda.",
  ui_story_5033_50330601_87_dialog_content = "Tapi tidak semua orang mampu melihat anak-anak yatim Euphoria seperti anak-anak lainnya. Saya perlu mencari tempat yang bersedia menerima mereka.",
  ui_story_5033_50330601_88_dialog_content = "Aku tahu.",
  ui_story_5033_50330601_89_dialog_content = "Tidak semua anak mau meninggalkan tempat ini juga. Selain itu, Euphoria dan Umbraton belum dalam kondisi terbaik akhir-akhir ini...",
  ui_story_5033_50330601_90_dialog_content = "Saya ingin menunggu sampai semuanya tenang sebelum menemukan solusi jangka panjang.",
  ui_story_5033_50330601_91_dialog_content = "Saya mengerti. Sejauh menyangkut anak-anak, saya dapat menjamin bahwa Umbraton akan menyambut mereka dengan tangan terbuka.",
  ui_story_5033_50330601_92_dialog_content = "Dan karena kita akan menyelidiki beberapa hal untuk sementara waktu, mungkin kita bisa membantu di sini juga?",
  ui_story_5033_50330601_93_dialog_content = "Oh, benar! Saat biarawati tiba di sini, mungkin dia bisa membantu mengurus anak-anak.",
  ui_story_5033_50330601_94_dialog_content = "Biarawati? Apakah Anda mengatakan bahwa gereja mengirim seorang biarawati ke gereja kami?",
  ui_story_5033_50330601_95_dialog_content = "Saya kira demikian. Saat kami berada di pesawat menuju Euphoria, kami bertemu dengan seorang biarawati yang mengatakan bahwa dia akan datang ke sini.",
  ui_story_5033_50330601_96_dialog_content = "Sejujurnya, saya pikir dia akan berada di sini sekarang ...",
  ui_story_5033_50330601_97_dialog_content = "Euphoria sudah lama tidak bertemu biarawati. Mungkin mereka hanya tidak ingin datang.",
  ui_story_5033_50330601_98_dialog_content = "Tapi gereja ini masih berdiri. Bahkan jika itu agak jompo, saya tidak berpikir itu akan menghentikan mereka dari keinginan untuk datang ke sini.",
  ui_story_5033_50330601_99_dialog_content = "Anda tahu, itu adalah seorang biarawati yang memberi saya nama saya ketika dia menemukan saya berkeliaran di jalan-jalan Euphoria dulu sekali.",
  ui_story_5033_50330601_100_dialog_content = "Tetapi setelah saya meninggalkan gereja, saya kehilangan kontak dengannya.",
  ui_story_5033_50330601_101_dialog_content = "Kemudian, sekitar delapan atau sembilan tahun yang lalu, saya mendengar bahwa dia menyelamatkan sekelompok anak dari kekacauan. Dia pergi ke Umbraton berharap untuk menabung lebih banyak, hanya untuk mati dalam kecelakaan di jalan.",
  ui_story_5033_50330601_102_dialog_content = "Akibatnya, gereja ini menjadi rusak dan bahkan vandalisme.",
  ui_story_5033_50330601_103_dialog_content = "Dan saat itulah kalian berdua...",
  ui_story_5033_50330601_104_dialog_content = "Benar. Saat itulah Casta dan saya mendirikan Raven's Blood dan memutuskan untuk memperbaiki tempat ini sehingga bisa menampung anak-anak yang berkeliaran sekali lagi.",
  ui_story_5033_50330601_105_dialog_content = "Tetapi jika gereja telah mengirim seorang biarawati baru untuk mengambil alih, maka mungkin itu lebih baik.",
  ui_story_5033_50330601_106_dialog_content = "\"Semua lebih baik\"? Anda tidak bisa serius, kan, Pollux?",
  ui_story_5033_50330601_107_dialog_content = "Saya pikir... Saya pikir Anda akan mengatakan bahwa bagi kita, tidak ada yang akan mengambil tempat <color=#FFB400>Sister Matilda</color>.",
  ui_story_5033_50330601_108_dialog_content = "Tidak ada yang menggantikannya, Casta.",
  ui_story_5033_50330601_109_dialog_content = "Sepertinya kalian berdua memiliki ikatan emosional yang sangat kuat dengan Sister Matilda ini.",
  ui_story_5033_50330601_110_dialog_content = "Saya sendiri adalah seorang yatim piatu Euforia. Suster Matilda adalah orang yang menerima saya.",
  ui_story_5033_50330601_111_dialog_content = "Jika bukan karena dia, tidak ada yang tahu apa yang akan dilakukan geng-geng di sini padaku. Adapun Pollux...",
  ui_story_5033_50330601_112_dialog_content = "Itu cukup untuk mengenang satu hari, Casta. Giliran kita untuk mendengarkan Mr. Corax dan mempelajari penyelidikannya.",
  ui_story_5033_50330601_113_dialog_content = "Saya sudah tahu inti dari apa yang terjadi, terima kasih kepada Nekoyashiki.",
  ui_story_5033_50330601_114_dialog_content = "Serangkaian pembunuhan misterius telah terjadi di Umbraton, dan Anda curiga bahwa si pembunuh entah bagaimana terhubung dengan Euphoria.",
  ui_story_5033_50330601_115_dialog_content = "Saya pikir kalian berdua akan lebih dari bersedia untuk membantu saya setelah Anda mendengar lebih banyak detail tentang penyelidikan saya.",
  ui_story_5033_50330601_116_dialog_content = "Mengapa demikian?",
  ui_story_5033_50330601_117_dialog_content = "Sungguh menyakitkan saya untuk memberitahu Anda... Tapi Suster Matilda tidak meninggal dalam kecelakaan.",
  ui_story_5033_50330601_118_dialog_content = "Kami mengetahui dari gereja setempat bahwa luka misterius di tubuhnya sama persis dengan korban lain dalam kasus tersebut.",
  ui_story_5033_50330601_119_dialog_content = "Apa?!",
  ui_story_5033_50330601_120_dialog_content = "<color=#e8d9bb>*Pecah*</color>",
  ui_story_5033_50330601_121_dialog_content = "<size=45>Apa yang baru saja kamu katakan?! Katakan lagi!</size>",
  ui_story_5033_50330601_122_dialog_content = "Harap tenang, Anda menakut-nakuti anak-anak.",
  ui_story_5033_50330601_123_dialog_content = "...",
  ui_story_5033_50330601_124_dialog_content = "I-Tidak apa-apa semuanya, jangan takut... Casta hanya sedikit kesal, itu saja.",
  ui_story_5033_50330601_125_dialog_content = "Maaf, anak-anak. Kami baru saja menerima berita yang sangat mengejutkan.",
  ui_story_5033_50330601_126_dialog_content = "Kami orang dewasa akan keluar untuk melanjutkan percakapan kami. Temui kami jika Anda butuh sesuatu, dan pastikan untuk memakan semua makanan Anda, oke?",
  ui_story_5033_50330601_127_dialog_content = "Baiklah…",
  ui_story_5033_50330601_128_dialog_content = "Anak-anak masih terlihat sedikit terguncang. Aku akan tinggal dan menemani mereka.",
  ui_story_5033_50330601_129_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5033_50330601_130_dialog_content = "Ayo pergi. Kami masih memiliki <size=45>banyak yang harus didiskusikan</size>.",
  ui_story_5033_50330701_1_dialog_content = "Mengunyah, mengunyah, mengunyah ...",
  ui_story_5033_50330701_2_dialog_content = "...",
  ui_story_5033_50330701_3_dialog_content = "Kenapa kamu tidak makan, Latan?",
  ui_story_5033_50330701_4_dialog_content = "Kamu terus menatap ke luar. Apakah Anda khawatir tentang mereka?",
  ui_story_5033_50330701_5_dialog_content = "Ya... Kami hampir tidak pernah melihat Casta semarah itu.",
  ui_story_5033_50330701_6_dialog_content = "Atau Pollux... Meskipun dia terlihat jauh lebih tenang daripada Casta, aku tahu dia sangat marah.",
  ui_story_5033_50330701_7_dialog_content = "Sesuatu yang sangat, sangat buruk pasti telah terjadi.",
  ui_story_5033_50330701_8_dialog_content = "Anda memikirkan semua itu sendiri, ya?",
  ui_story_5033_50330701_9_dialog_content = "(Betapa anak kecil yang perseptif dia.)",
  ui_story_5033_50330701_10_dialog_content = "Ya saya telah melakukannya.",
  ui_story_5033_50330701_11_dialog_content = "Biasanya, apa pun yang terjadi atau berita macam apa yang dibawakan Nekoyashiki kepada mereka,",
  ui_story_5033_50330701_12_dialog_content = "mereka tidak pernah menunjukkan tanda-tanda kesal. Tidak di depan kita, setidaknya.",
  ui_story_5033_50330701_13_dialog_content = "Itu adalah pertama kalinya kami melihat mereka begitu marah, atau mendengar mereka berteriak seperti itu.",
  ui_story_5033_50330701_14_dialog_content = "Jangan terlalu khawatir tentang itu, oke? Setelah kita mengetahui semuanya, saya yakin mereka tidak akan marah lagi.",
  ui_story_5033_50330701_15_dialog_content = "Apakah itu... Ada hubungannya dengan Suster <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330701_16_dialog_content = "Anda mendengar itu juga?",
  ui_story_5033_50330701_17_dialog_content = "Uh-huh, aku mendengarkan kalian selama ini.",
  ui_story_5033_50330701_18_dialog_content = "Yah, saya dapat memberitahu Anda bahwa ya, itu ada hubungannya dengan Sister Matilda.",
  ui_story_5033_50330701_19_dialog_content = "Adapun rincian lainnya, kami masih memiliki banyak penyelidikan yang harus dilakukan.",
  ui_story_5033_50330701_20_dialog_content = "Tapi begitu kami menyelesaikan pekerjaan kami, saya yakin Pollux dan Casta akan membagikan sisanya kepada Anda.",
  ui_story_5033_50330701_21_dialog_content = "Oh… Baiklah.",
  ui_story_5033_50330701_22_dialog_content = "Hmm?",
  ui_story_5033_50330701_23_dialog_content = "Apa ada masalah?",
  ui_story_5033_50330701_24_dialog_content = "Saya pikir saya melihat seseorang di luar sekarang ... Di belakang Anda, di sana.",
  ui_story_5033_50330701_25_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_5033_50330701_26_dialog_content = "Saya tidak melihat siapa pun.",
  ui_story_5033_50330701_27_dialog_content = "Aneh... mungkin aku membayangkannya? Aku berani bersumpah aku melihat seseorang lewat...",
  ui_story_5033_50330701_28_dialog_content = "Mungkin mereka bersembunyi? Aku akan mencoba merasakan kehadiran mereka...",
  ui_story_5033_50330701_29_dialog_content = "Maksudmu?",
  ui_story_5033_50330701_30_dialog_content = "Er... Sederhananya, saya memiliki kekuatan khusus yang memungkinkan saya menemukan orang tanpa melihat mereka. Ini semacam hal saya.",
  ui_story_5033_50330701_31_dialog_content = "Saya sangat sensitif terhadap Lumina, serta Darkflow.",
  ui_story_5033_50330701_32_dialog_content = "Itu terdengar sangat keren!",
  ui_story_5033_50330701_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330701_34_dialog_content = "Saya bisa merasakan tiga orang yang sangat kuat di koridor di luar itu. Itu seharusnya Corax, Casta, dan Pollux.",
  ui_story_5033_50330701_35_dialog_content = "Ada juga beberapa Eclipsites yang berkeliaran di area tersebut, tetapi jaraknya masih cukup jauh dari gereja.",
  ui_story_5033_50330701_36_dialog_content = "Dan di luar itu... yang kurasakan hanyalah orang biasa.",
  ui_story_5033_50330701_37_dialog_content = "Oh... Mungkin aku hanya melihat sesuatu.",
  ui_story_5033_50330701_38_dialog_content = "Tidak, saya pikir Anda hanya sedikit cemas. Ayo kembali ke dalam gereja dan tunggu Pollux dan yang lainnya, oke?",
  ui_story_5033_50330701_39_dialog_content = "Kami tidak ingin Eclipsites itu melihat kami di sini.",
  ui_story_5033_50330701_40_dialog_content = "Oke.",
  ui_story_5033_50330701_41_dialog_content = "Gadis baik, lanjutkan dan selesaikan makan.",
  ui_story_5033_50330701_42_dialog_content = "Saya harap semuanya berjalan baik di akhir Corax ...",
  ui_story_5033_50330701_43_dialog_content = "Saya ditugaskan untuk kasus ini kira-kira satu bulan yang lalu.",
  ui_story_5033_50330701_44_dialog_content = "Shadowlord membutuhkan seseorang untuk memeriksa mayat-mayat itu, dan saat itulah aku menemukan tanda-tanda metode pembunuhan yang disukai si pembunuh.",
  ui_story_5033_50330701_45_dialog_content = "<color=#e8d9bb>Satu bulan yang lalu...</color>",
  ui_story_5033_50330701_46_dialog_content = "Jadi maksudmu kau melihat luka seperti ini pada pasien yang meninggal beberapa hari yang lalu?",
  ui_story_5033_50330701_47_dialog_content = "Memang, dan pasien yang aneh, pada saat itu. Kondisinya jauh dari kritis, namun dia tetap mati.",
  ui_story_5033_50330701_48_dialog_content = "Aku mulai berpikir dia tidak mati karena penyakitnya...",
  ui_story_5033_50330701_49_dialog_content = "Saya percaya seorang pembunuh berantai berada di balik kematian ini.",
  ui_story_5033_50330701_50_dialog_content = "Apakah ada laporan baru-baru ini tentang kematian aneh seperti ini?",
  ui_story_5033_50330701_51_dialog_content = "Ya, tapi tubuh mereka sudah dibaringkan... Kecuali jika Anda membutuhkan saya untuk menggali mereka?",
  ui_story_5033_50330701_52_dialog_content = "Saya bersedia. Kita perlu mengevaluasi kembali penyebab kematian mereka.",
  ui_story_5033_50330701_53_dialog_content = "Semua temuan kami harus dilaporkan ke Shadowlord juga.",
  ui_story_5033_50330701_54_dialog_content = "Baiklah, tapi aku tidak suka ini...",
  ui_story_5033_50330701_55_dialog_content = "Dan bagaimana dengan pria ini? Apakah saya menguburnya?",
  ui_story_5033_50330701_56_dialog_content = "J-Jangan terburu-buru. Dia masih bernafas... Aku mungkin bisa menyelamatkannya.",
  ui_story_5033_50330701_57_dialog_content = "Ah, sesuaikan dirimu.",
  ui_story_5033_50330701_58_dialog_content = "Ada bekas luka aneh di tubuh para korban.",
  ui_story_5033_50330701_59_dialog_content = "Terlebih lagi, pelakunya telah mengulangi kejahatannya berkali-kali.",
  ui_story_5033_50330701_60_dialog_content = "Jika bukan karena peningkatan baru-baru ini dalam pembunuhan yang hampir identik ini, kita mungkin tidak akan pernah menemukan bahwa ini adalah pekerjaan seorang pembunuh berantai.",
  ui_story_5033_50330701_61_dialog_content = "Meskipun kami telah memastikan MO, kami belum menemukan petunjuk berguna lainnya.",
  ui_story_5033_50330701_62_dialog_content = "Selama penyelidikan saya, saya menemukan bahwa tubuh seseorang yang meninggal bertahun-tahun yang lalu dalam sebuah kecelakaan yang diduga memiliki bekas luka yang sama dengan korban pembunuhan berantai.",
  ui_story_5033_50330701_63_dialog_content = "Salah satu tips yang kami terima adalah dari gereja lokal. Mereka memberi kami arsip kecelakaan Suster Matilda.",
  ui_story_5033_50330701_64_dialog_content = "Bagaimana Anda menghubungkan si pembunuh dengan Euphoria? Dimana bajingan itu?!",
  ui_story_5033_50330701_65_dialog_content = "Kami masih belum tahu identitas pembunuhnya. Adapun bagaimana mereka terhubung ke Euphoria... Itu hanya spekulasi di pihak kita.",
  ui_story_5033_50330701_66_dialog_content = "Rumor mengatakan bahwa Euphoria dihantui oleh Grim Reaper.",
  ui_story_5033_50330701_67_dialog_content = "Seorang Grim Reaper yang konon hanya muncul di hadapan mereka yang berani mengganggu kedamaian di Euphoria atau melanggar aturannya.",
  ui_story_5033_50330701_68_dialog_content = "Dia muncul tanpa suara, mengambil nyawa korbannya tanpa meninggalkan jejak kehadirannya.",
  ui_story_5033_50330701_69_dialog_content = "Apa sebenarnya yang Anda lakukan?",
  ui_story_5033_50330701_70_dialog_content = "Pembunuhnya menggunakan seni pembunuhan tingkat tinggi.",
  ui_story_5033_50330701_71_dialog_content = "Yang dikabarkan tidak meninggalkan jejak, bahkan setetes darah pun.",
  ui_story_5033_50330701_72_dialog_content = "Tidak. Itu pasti meninggalkan sesuatu.",
  ui_story_5033_50330701_73_dialog_content = "Bekas luka. Memang, mereka hanya terlihat seperti bekas goresan biasa.",
  ui_story_5033_50330701_74_dialog_content = "Pollux, Anda tahu teknik ini?",
  ui_story_5033_50330701_75_dialog_content = "Tentu saja... karena <color=#FFB400>Saya juga bisa menggunakannya</color>.",
  ui_story_5033_50330701_76_dialog_content = "Apa?!",
  ui_story_5033_50330702_1_dialog_content = "Kami menghabiskan roti kami sejak lama... Mengapa Casta tidak kembali untuk menyuruh kami tidur?",
  ui_story_5033_50330702_2_dialog_content = "Saya mendengar Casta mengatakan bahwa dia perlu menemui dokter setelah dia selesai makan.",
  ui_story_5033_50330702_3_dialog_content = "Jadi orang itu seorang dokter?",
  ui_story_5033_50330702_4_dialog_content = "Yup, si tan adalah seorang dokter.",
  ui_story_5033_50330702_5_dialog_content = "Jadi kapan mereka akan kembali?",
  ui_story_5033_50330702_6_dialog_content = "Mari kita pergi tidur untuk saat ini.",
  ui_story_5033_50330702_7_dialog_content = "Aku yakin mereka akan kembali setelah kita bangun.",
  ui_story_5033_50330702_8_dialog_content = "Latan benar, semuanya. Saatnya tidur siang, jadi istirahatlah dan semuanya akan beres pada saat Anda bangun.",
  ui_story_5033_50330702_9_dialog_content = "Hmph... Kedengarannya kau hanya mengatakan itu.",
  ui_story_5033_50330702_10_dialog_content = "Anda pikir kami sekelompok anak berusia tiga tahun?",
  ui_story_5033_50330702_11_dialog_content = "Ah! K-Kau anak dari sebelumnya! Orang yang mencoba memberikan kecoak itu kepada Nekoyashiki...",
  ui_story_5033_50330702_12_dialog_content = "Hehe, benar.",
  ui_story_5033_50330702_13_dialog_content = "Anda hanya mencoba menipu kami untuk tidur siang, bukan? Yah, kami tidak akan membelinya!",
  ui_story_5033_50330702_14_dialog_content = "Beritahu kami apa yang kalian lakukan di sini, dan jangan berani berbohong!",
  ui_story_5033_50330702_15_dialog_content = "(Astaga... Merawat anak-anak bisa sangat menyebalkan!)",
  ui_story_5033_50330702_16_dialog_content = "Kami datang mencari Raven's Blood... Yah, lebih tepatnya, merekalah yang menjangkau kami.",
  ui_story_5033_50330702_17_dialog_content = "Kami sedang menyelidiki kejahatan yang sangat serius bersama-sama.",
  ui_story_5033_50330702_18_dialog_content = "Kejahatan macam apa?",
  ui_story_5033_50330702_19_dialog_content = "Anu…",
  ui_story_5033_50330702_20_dialog_content = "(Saya harus memikirkan cara untuk menakut-nakuti mereka, sehingga mereka tidak terus menanyakannya!)",
  ui_story_5033_50330702_21_dialog_content = "<anim type=Shake><size=45>Kasus pembunuhan yang sangat menakutkan!!!</size></anim>",
  ui_story_5033_50330702_22_dialog_content = "...",
  ui_story_5033_50330702_23_dialog_content = "D-Bukankah itu terdengar menakutkan bagi kalian?",
  ui_story_5033_50330702_24_dialog_content = "Kami dari Euphoria... Anda benar-benar berpikir itu membuat kami takut?",
  ui_story_5033_50330702_25_dialog_content = "Apa? Maksudku, seharusnya... Maaf, sebentar aku lupa.",
  ui_story_5033_50330702_26_dialog_content = "Ha ha ha! Orang ini mengira kita hanya sekelompok anak laki-laki dan perempuan normal! Apa yang aneh!",
  ui_story_5033_50330702_27_dialog_content = "Ya! B-Selain itu... Semua orang membenci anak kecil Euphoria.",
  ui_story_5033_50330702_28_dialog_content = "Tidak ada yang aneh tentang itu!",
  ui_story_5033_50330702_29_dialog_content = "Saya tidak peduli siapa Anda atau dari mana Anda berasal. Di mata saya, Anda hanya sekelompok anak-anak normal.",
  ui_story_5033_50330702_30_dialog_content = "Yang harus kalian pikirkan hanyalah makan, tidur, dan bersenang-senang! Jangan khawatir tentang hal-hal yang menakutkan atau berbahaya ini.",
  ui_story_5033_50330702_31_dialog_content = "Pollux dan yang lainnya akan menyelesaikannya.",
  ui_story_5033_50330702_32_dialog_content = "PlayerName ada benarnya... plus Pollux dan Casta juga memberi tahu kami hal yang sama.",
  ui_story_5033_50330702_33_dialog_content = "Oke, baiklah...",
  ui_story_5033_50330702_34_dialog_content = "Huh... Kurasa kau benar-benar pria yang baik.",
  ui_story_5033_50330702_35_dialog_content = "Kami tidak akan bertanya lagi. Tidur siang bersama kami!",
  ui_story_5033_50330702_36_dialog_content = "Ya! Ayo tidur siang bersama kami, Tn. Navigator!",
  ui_story_5033_50330702_37_dialog_content = "Tuan Navigator, saya ingin lebih banyak permen!",
  ui_story_5033_50330702_38_dialog_content = "H-Hei, tidak sekaligus, guys! Aku akan jatuh!",
  ui_story_5033_50330702_39_dialog_content = "Anda punya permen? Kami juga ingin beberapa...",
  ui_story_5033_50330702_40_dialog_content = "Saya lakukan, saya lakukan, itu di sini. Nekoyashiki memasukkan banyak ke dalam sakuku.",
  ui_story_5033_50330702_41_dialog_content = "Satu per satu, teman-teman. Tidak perlu terburu-buru.",
  ui_story_5033_50330702_42_dialog_content = "Nekoyashiki bajingan itu, pasti tahu apa yang terjadi.",
  ui_story_5033_50330702_43_dialog_content = "Saya tidak berpikir seorang anak kecil harus berbicara tentang orang dewasa seperti itu ...",
  ui_story_5033_50330702_44_dialog_content = "Bagaimanapun, Nekoyashiki adalah seniormu. Anda harus menunjukkan sedikit lebih banyak rasa hormat padanya.",
  ui_story_5033_50330702_45_dialog_content = "Hei, apa yang memberi?! Berhentilah berkhotbah dan berikan permen saya!",
  ui_story_5033_50330702_46_dialog_content = "Nekoyashiki meninggalkan permen ini bersamaku, kau tahu? Jika Anda tidak menghormatinya, mengapa saya harus berbagi dengan Anda?",
  ui_story_5033_50330702_47_dialog_content = "Apa yang kau bicarakan? Saya bergaul baik dengan Nekoyashiki, dan dia tidak akan pernah menyuruh saya untuk \"menghormati\" dia!",
  ui_story_5033_50330702_48_dialog_content = "Ingin mengetahui sesuatu? Ketika Nekoyashiki pertama kali datang ke Euphoria, dia memiliki sikap yang sangat busuk.",
  ui_story_5033_50330702_49_dialog_content = "Tapi kemudian sekelompok gangster menghajarnya habis-habisan!",
  ui_story_5033_50330702_50_dialog_content = "Dia muncul di sini, semua berdarah dan memar. Hanya berkat Pollux dan Casta dia selamat.",
  ui_story_5033_50330702_51_dialog_content = "Mengapa Anda menceritakan kisah ini seolah-olah Anda melihatnya sendiri? Apakah Anda ada di sana saat itu terjadi?",
  ui_story_5033_50330702_52_dialog_content = "Tunggu... jangan bilang kau sebenarnya lebih tua darinya?!",
  ui_story_5033_50330702_53_dialog_content = "Kau gila? Ya, saya ada di sana, tapi saya baru berusia lima tahun.",
  ui_story_5033_50330702_54_dialog_content = "Jadi apa gunanya menceritakan kisah itu?",
  ui_story_5033_50330702_55_dialog_content = "Untuk menunjukkan seberapa dekat aku dan Nekoyashiki! Duh!",
  ui_story_5033_50330702_56_dialog_content = "Kami adalah saudara sampai akhir yang pahit! Mengapa kita harus kaku dan formal satu sama lain?",
  ui_story_5033_50330702_57_dialog_content = "T-Tentu... Aku tidak menyangka Nekoyashiki mengalami hal seperti itu. Kurasa itu menjelaskan mengapa dia tampaknya berhubungan baik dengan Raven's Blood.",
  ui_story_5033_50330702_58_dialog_content = "Di satu sisi, Nekoyashiki sangat mirip dengan kalian: anak lain diambil dan dilindungi oleh Raven's Blood.",
  ui_story_5033_50330702_59_dialog_content = "Hehehe.. tepat. Saya mendengar Nekoyashiki sendiri hanyalah seorang anak kecil ketika dia pertama kali datang ke gereja.",
  ui_story_5033_50330702_60_dialog_content = "Pollux mengatakan bahwa meskipun wajahnya bengkak dan berdarah pada saat itu, matanya penuh kebanggaan.",
  ui_story_5033_50330702_61_dialog_content = "Setelah luka Nekoyashiki sembuh, dia pergi tanpa sepatah kata pun.",
  ui_story_5033_50330702_62_dialog_content = "Sekarang, setiap kali dia datang, dia selalu membawakan kami banyak makanan dan kebutuhan lainnya.",
  ui_story_5033_50330702_63_dialog_content = "Heh, dan dia adalah penjual permen kami yang bisa diandalkan!",
  ui_story_5033_50330702_64_dialog_content = "Tidak peduli apa yang terjadi, dia selalu memastikan untuk membawakan kita banyak permen!",
  ui_story_5033_50330702_65_dialog_content = "Baiklah nak, aku mengerti... Kamu hanya ingin permenmu, bukan? Ini, ambil.",
  ui_story_5033_50330702_66_dialog_content = "Manis!",
  ui_story_5033_50330702_67_dialog_content = "Hei tunggu... Anda dapat memiliki permen Anda, tapi Anda harus memberitahu saya lebih banyak tentang Casta dan Pollux?",
  ui_story_5033_50330702_68_dialog_content = "Karena kita akan bekerja sama, saya ingin tahu lebih banyak tentang mereka.",
  ui_story_5033_50330702_69_dialog_content = "Tentu tidak masalah! Latan dapat memberi tahu Anda apa pun yang ingin Anda ketahui!",
  ui_story_5033_50330702_70_dialog_content = "Hmm, saya rasa saya akan mulai dengan legenda misterius tentang Pollux...",
  ui_story_5033_50330702_71_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5033_50330702_72_dialog_content = "Apakah itu pistol barusan?! Itu datang dari luar...",
  ui_story_5033_50330702_73_dialog_content = "Jika Anda tidak dapat memberi saya bukti yang cukup untuk membuktikan bahwa Anda tidak bersalah... Maka saya tidak punya pilihan selain menyebut Anda tersangka utama.",
  ui_story_5033_50330702_74_dialog_content = "Letakkan pisaunya, atau aku akan membuatmu memakan peluru!",
  ui_story_5033_50330702_75_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5033_50330702_76_dialog_content = "Kenapa kau menyuruhku menjatuhkan senjataku padahal kau sudah menembakku?!",
  ui_story_5033_50330702_77_dialog_content = "Itu adalah tembakan peringatan! Biarkan saya ulangi: jatuhkan senjata Anda.",
  ui_story_5033_50330702_78_dialog_content = "Bagaimana Anda bisa menuduh Pollux sebagai pembunuhnya?!",
  ui_story_5033_50330702_79_dialog_content = "Sister Matilda sangat berarti bagi kami. Beraninya kau bahkan menyiratkan bahwa kita bisa membunuhnya!",
  ui_story_5033_50330702_80_dialog_content = "Saya hanya mengatakan bahwa itu adalah kemungkinan. Bagaimanapun, semua yang saya dengar sejauh ini adalah akun Anda sendiri. Saya tidak punya cara untuk mengetahui kebenaran di balik hubungan Anda dengan Suster Matilda.",
  ui_story_5033_50330702_81_dialog_content = "Permintaan maaf. Mungkin sulit untuk diterima, tetapi dari sudut pandang rasional, saya tidak punya pilihan selain memperlakukan Anda sebagai tersangka untuk saat ini.",
  ui_story_5033_50330702_82_dialog_content = "Satu-satunya cara untuk membersihkan nama Anda adalah memberi saya bukti yang cukup bahwa Anda tidak bersalah.",
  ui_story_5033_50330702_83_dialog_content = "Apa yang terjadi di sini?! Kenapa kalian berkelahi?!",
  ui_story_5033_50330702_84_dialog_content = "PlayerName, Pollux baru saja mengaku bisa menggunakan teknik pembunuhan yang sama dengan yang digunakan oleh pembunuh berantai.",
  ui_story_5033_50330702_85_dialog_content = "Apa?!",
  ui_story_5033_50330702_86_dialog_content = "Tidak... Tidak mungkin! Pollux tidak akan pernah membunuh siapa pun!",
  ui_story_5033_50330702_87_dialog_content = "Cukup, kalian semua!",
  ui_story_5033_50330702_88_dialog_content = "Tak satu pun dari Anda harus menggambar senjata Anda di depan anak-anak.",
  ui_story_5033_50330702_89_dialog_content = "Pollux... Apakah mereka akan membawamu pergi?",
  ui_story_5033_50330702_90_dialog_content = "Aku tidak akan membiarkan mereka membawamu! Aku akan melindungimu!",
  ui_story_5033_50330801_1_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_5033_50330801_2_dialog_content = "<color=#e8d9bb>Di bilah Euforia...</color>",
  ui_story_5033_50330801_3_dialog_content = "Apakah kamu mendengar? Raven's Blood mendapatkan semua sobat sobat dengan beberapa brengsek Umbraton.",
  ui_story_5033_50330801_4_dialog_content = "Penasaran apa yang mereka lakukan?",
  ui_story_5033_50330801_5_dialog_content = "Tidak ada yang bagus, saya yakin. Kudengar Umbraton mencoba menenggelamkan cakar baunya di Euphoria selanjutnya.",
  ui_story_5033_50330801_6_dialog_content = "Umbraton sudah menggunakan Euphoria sebagai tempat pembuangan pribadinya sendiri. Mereka membuang semua sampah mereka di sini.",
  ui_story_5033_50330801_7_dialog_content = "Apakah itu tidak cukup bagi mereka?",
  ui_story_5033_50330801_8_dialog_content = "Sekarang mereka ingin mengambil tanah dari bawah kaki kita...",
  ui_story_5033_50330801_9_dialog_content = "Sarang judi dan pabrik senjata yang terlalu takut untuk berbisnis di Umbraton malah datang ke sini.",
  ui_story_5033_50330801_10_dialog_content = "Bukankah itu akan lebih sama, kalau begitu?",
  ui_story_5033_50330801_11_dialog_content = "Seperti neraka. Setidaknya sebelumnya, bisnis-bisnis itu milik Euphoria.",
  ui_story_5033_50330801_12_dialog_content = "Sekarang, Umbraton ingin kontrol penuh atas segalanya.",
  ui_story_5033_50330801_13_dialog_content = "Yah... Aku bilang mereka milik Euphoria, tapi sebenarnya, mereka milik \"Boss.\"",
  ui_story_5033_50330801_14_dialog_content = "Pembebasan kami tidak mudah diperoleh di Euphoria, dan aku menolak untuk hidup di bawah kendali siapa pun lagi seperti dulu...",
  ui_story_5033_50330801_15_dialog_content = "Kita mungkin bangkrut, tapi setidaknya kita tidak hidup dalam ketakutan untuk hidup kita lagi.",
  ui_story_5033_50330801_16_dialog_content = "Betul sekali! Euforia milik setiap geng di sini! Itulah aturannya.",
  ui_story_5033_50330801_17_dialog_content = "Beri jalan untuk kepala kita!",
  ui_story_5033_50330801_18_dialog_content = "Ah, punggungku...",
  ui_story_5033_50330801_19_dialog_content = "Aku mendengar Raven's Blood mengalahkan kalian semua. Itu benar?",
  ui_story_5033_50330801_20_dialog_content = "Pertanyaan bodoh macam apa itu?! Lihat saja kami!!",
  ui_story_5033_50330801_21_dialog_content = "Mereka pergi sejauh berkelahi dengan kami untuk orang-orang Umbraton yang merinding. Kenapa ya?",
  ui_story_5033_50330801_22_dialog_content = "Siapa yang tahu skema macam apa yang mereka rencanakan dengan dua orang luar itu...",
  ui_story_5033_50330801_23_dialog_content = "Saya bisa menjawab itu. Anak laki-laki saya baru saja membawakan saya beberapa info menarik.",
  ui_story_5033_50330801_24_dialog_content = "Umbraton mengirim keduanya ke sini untuk penyelidikan pembunuhan. Rupanya, pembunuhnya berasal dari Euphoria, jadi untuk itulah mereka ada di sini.",
  ui_story_5033_50330801_25_dialog_content = "Dugaan saya adalah bahwa Raven's Blood hanya menggunakan ini sebagai kesempatan untuk menyedot tuan kita yang berpotensi baru.",
  ui_story_5033_50330801_26_dialog_content = "Mengapa ada orang yang meminta Raven's Blood untuk membantu penyelidikan kriminal?",
  ui_story_5033_50330801_27_dialog_content = "Selain itu, seluruh \"penyelidikan pembunuhan\" ini hanya bisa menjadi alasan buruk bagi mereka untuk muncul dan membuat masalah.",
  ui_story_5033_50330801_28_dialog_content = "Katakan sesuatu, maukah Anda Gustav? Anda tahu hampir semua hal yang terjadi di Euforia!",
  ui_story_5033_50330801_29_dialog_content = "Apa yang Anda ingin dengar saya katakan?",
  ui_story_5033_50330801_30_dialog_content = "Apa sebenarnya yang harus kita lakukan tentang semua ini?",
  ui_story_5033_50330801_31_dialog_content = "Mengucapkan kata \"tepat\" tidak serta merta membuat pertanyaan Anda kurang kabur.",
  ui_story_5033_50330801_32_dialog_content = "Apakah Anda bertanya apa yang harus dilakukan geng Anda? Atau semua Euforia?",
  ui_story_5033_50330801_33_dialog_content = "Keduanya, jelas!!!",
  ui_story_5033_50330801_34_dialog_content = "Tentu saja geng saya adalah prioritas utama saya, tetapi saya juga seorang Euforia.",
  ui_story_5033_50330801_35_dialog_content = "Dalam Euphoria, satu-satunya hal yang penting adalah kekuatan geng.",
  ui_story_5033_50330801_36_dialog_content = "Jika Raven's Blood bisa mengalahkan semua orangmu hanya dengan dua orang, aku khawatir yang lain sudah...",
  ui_story_5033_50330801_37_dialog_content = "Aku harus sampai ke dasar ini!",
  ui_story_5033_50330801_38_dialog_content = "Kami tidak dikelompokkan bersama pada saat itu, dan tidak ada dari kami yang memiliki senjata kami... Belum lagi ada banyak Eclipsites yang ditambahkan ke dalam campuran! Itulah satu-satunya cara mereka bisa menang.",
  ui_story_5033_50330801_39_dialog_content = "Kami akan melanjutkan sesuai dengan aturan Euphoria.",
  ui_story_5033_50330801_40_dialog_content = "Jika Anda dan geng Anda ingin mendapatkan reputasi Anda kembali, Anda perlu menantang mereka untuk bertarung geng formal dan menang.",
  ui_story_5033_50330801_41_dialog_content = "Tapi jika kamu terlalu takut...",
  ui_story_5033_50330801_42_dialog_content = "Aku tidak takut untuk bertarung... Tunggu saja sampai lukaku sembuh, dan aku akan menjatuhkan burung gagak itu dari pohonnya!",
  ui_story_5033_50330801_43_dialog_content = "Tidak, Bos. Kita tidak harus melakukan apapun sendiri.",
  ui_story_5033_50330801_44_dialog_content = "Bagaimanapun, Darah Raven adalah orang-orang yang membawa orang luar Umbraton itu ke Euphoria terlebih dahulu dan menyebabkan masalah. Merekalah yang melanggar aturan.",
  ui_story_5033_50330801_45_dialog_content = "Itu benar, aku selalu tahu gadis-gadis Raven's Blood itu tidak baik.",
  ui_story_5033_50330801_46_dialog_content = "Mereka bahkan mengacaukan bisnis geng kita beberapa waktu lalu.",
  ui_story_5033_50330801_47_dialog_content = "Mereka selalu bersembunyi di sekitar gereja mereka yang berharga siang dan malam, tidak membiarkan siapa pun mendekatinya.",
  ui_story_5033_50330801_48_dialog_content = "Yah, duh, itu wilayah mereka. Tentu saja, mereka tidak akan membiarkan Anda masuk begitu saja.",
  ui_story_5033_50330801_49_dialog_content = "A-Ngomong-ngomong... mereka hanya menggosokku dengan cara yang salah!",
  ui_story_5033_50330801_50_dialog_content = "Benar sekali!",
  ui_story_5033_50330801_51_dialog_content = "Gustav, pergi dan beri tahu geng lain di Euphoria bahwa akhirnya tiba saatnya untuk bersatu dan mengalahkan Raven's Blood, sekali dan untuk selamanya!",
  ui_story_5033_50330801_52_dialog_content = "Baiklah, sekarang tenang saja, kalian semua.",
  ui_story_5033_50330801_53_dialog_content = "Saya tahu Anda semua yakin bahwa satu-satunya cara untuk menyelamatkan Euphoria adalah dengan menyingkirkan Darah Raven.",
  ui_story_5033_50330801_54_dialog_content = "Tetapi Anda tidak boleh hanya menagih secara sembarangan.",
  ui_story_5033_50330801_55_dialog_content = "Atau apakah Anda sudah lupa bahwa Raven's Blood telah membuat beberapa teman baru? Menyerang mereka sekarang mungkin memprovokasi Umbraton untuk membalas.",
  ui_story_5033_50330801_56_dialog_content = "Terus?! Euforia tidak takut Umbraton!!",
  ui_story_5033_50330801_57_dialog_content = "Ini bukan tentang apakah Anda takut atau tidak.",
  ui_story_5033_50330801_58_dialog_content = "Faktanya, kita masih belum tahu persis apa yang Umbraton rencanakan. Kubilang kita cari tahu apa yang mereka lakukan sebelum bergerak.",
  ui_story_5033_50331001_1_dialog_content = "Tidak perlu khawatir, anak-anak. Kami hanya memiliki sedikit kesalahpahaman, itu saja.",
  ui_story_5033_50331001_2_dialog_content = "Letakkan senjatamu, Casta. Jangan pernah menembakkannya di depan anak-anak lagi.",
  ui_story_5033_50331001_3_dialog_content = "Maaf, Pollux... Aku tidak berpikir jernih. Saya tidak berpikir anak-anak akan berlari keluar.",
  ui_story_5033_50331001_4_dialog_content = "Corax, saya tidak berpikir pembunuh berantai bisa menjadi seseorang yang dicintai dan dipercaya oleh anak-anak ini seperti mereka.",
  ui_story_5033_50331001_5_dialog_content = "Saya sudah menyimpan pisau saya ... Saya akan membiarkan Anda berbicara. Aku minta maaf karena melompat pistol.",
  ui_story_5033_50331001_6_dialog_content = "A-Apakah semuanya baik-baik saja sekarang?",
  ui_story_5033_50331001_7_dialog_content = "Ya, semuanya baik-baik saja sekarang. Sekarang semua orang kembali ke gereja sebelum Anda masuk angin.",
  ui_story_5033_50331001_8_dialog_content = "Itu benar, sepertinya akan segera hujan... Kenapa kamu tidak masuk dulu, anak-anak?",
  ui_story_5033_50331001_9_dialog_content = "Latan, bawa mereka semua kembali ke dalam.",
  ui_story_5033_50331001_10_dialog_content = "Baiklah…",
  ui_story_5033_50331001_11_dialog_content = "Yah, aku semua telinga. Anda bisa mulai dengan menjelaskan mengapa Anda mampu menggunakan teknik pembunuhan tingkat tinggi yang sama dengan si pembunuh.",
  ui_story_5033_50331001_12_dialog_content = "Memang benar bahwa saya mampu menggunakan teknik itu, tetapi tidak sejauh yang Anda gambarkan.",
  ui_story_5033_50331001_13_dialog_content = "Selain itu, teknik ini membutuhkan penggunaan jenis belati yang sangat khusus.",
  ui_story_5033_50331001_14_dialog_content = "Saya sudah bersumpah 14 tahun yang lalu untuk tidak pernah menggunakannya lagi.",
  ui_story_5033_50331001_15_dialog_content = "Nekoyashiki dan aku bisa membuktikannya.",
  ui_story_5033_50331001_16_dialog_content = "Maaf, tapi kesaksian Anda tidak membawa beban.",
  ui_story_5033_50331001_17_dialog_content = "Aku butuh lebih jika kau ingin aku mempercayaimu, Pollux.",
  ui_story_5033_50331001_18_dialog_content = "Saya hanya bisa menawarkan semua yang saya tahu ... Apakah Anda percaya atau tidak adalah keputusan Anda.",
  ui_story_5033_50331001_19_dialog_content = "Kalau begitu beri tahu saya, bagaimana Anda bisa mempelajari teknik pembunuhan semacam ini?",
  ui_story_5033_50331001_20_dialog_content = "Saya mempelajarinya dari mantan pemilik Euphoria. Semua orang memanggilnya <color=#FFB400>Boss</color>.",
  ui_story_5033_50331001_21_dialog_content = "<color=#FFB400>Organisasi</color> miliknya pernah memegang kendali atas semua penduduk dan bisnis di Euphoria.",
  ui_story_5033_50331001_22_dialog_content = "Saat itu, semua orang hidup dalam ketakutan akan Grim Reaper organisasi.",
  ui_story_5033_50331001_23_dialog_content = "Aku tergabung dalam organisasi itu sejak lama, di mana aku dipaksa untuk mempelajari teknik membunuh Grim Reaper juga.",
  ui_story_5033_50331001_24_dialog_content = "Siapa sebenarnya karakter \"Bos\" ini?",
  ui_story_5033_50331001_25_dialog_content = "Setiap kali kami berada di hadapannya, dia selalu duduk di kursi berwarna merah darah dengan punggung menghadap ke arah kami.",
  ui_story_5033_50331001_26_dialog_content = "Tidak ada yang tahu namanya atau bahkan seperti apa tampangnya.",
  ui_story_5033_50331001_27_dialog_content = "Mengapa Anda bergabung dengan organisasi seperti itu?",
  ui_story_5033_50331001_28_dialog_content = "Ketika seseorang berjuang untuk bertahan hidup, mereka tidak selalu memikirkan konsekuensi dari keputusan mereka.",
  ui_story_5033_50331001_29_dialog_content = "Jadi, ketika seseorang memberi tahu saya bahwa saya dapat memiliki tempat tidur sendiri dan tidak perlu khawatir tentang makanan atau pakaian lagi...",
  ui_story_5033_50331001_30_dialog_content = "Saya secara alami menerima tawaran itu.",
  ui_story_5033_50331001_31_dialog_content = "Tidak sampai kemudian saya mengetahui bahwa dia adalah \"Bos\" yang dibicarakan semua orang.",
  ui_story_5033_50331001_32_dialog_content = "Maka aman untuk berasumsi bahwa pembunuh berantai adalah bagian dari organisasi ini, sama seperti Anda, kan?",
  ui_story_5033_50331001_33_dialog_content = "Tetapi organisasi itu benar-benar musnah sepuluh tahun yang lalu.",
  ui_story_5033_50331001_34_dialog_content = "Saya pikir saya adalah satu-satunya yang selamat.",
  ui_story_5033_50331001_35_dialog_content = "Mungkin saja ada lebih banyak orang yang selamat, kecuali Anda tidak menyadarinya.",
  ui_story_5033_50331001_36_dialog_content = "Sekarang setelah Anda melihat-lihat laporan otopsi ini, apakah ada orang tertentu yang muncul di benak Anda?",
  ui_story_5033_50331001_37_dialog_content = "Ada satu orang...",
  ui_story_5033_50331001_38_dialog_content = "Dia akan menjadi satu-satunya yang cukup terampil untuk melakukan pembunuhan ini. Tapi orang itu sudah mati.",
  ui_story_5033_50331001_39_dialog_content = "Bagaimana Anda begitu yakin?",
  ui_story_5033_50331001_40_dialog_content = "Karena akulah yang membunuhnya... Sahabatku.",
  ui_story_5033_50331001_41_dialog_content = "<color=#e8d9bb>14 tahun yang lalu...</color>",
  ui_story_5033_50331001_42_dialog_content = "Apakah ini... Tempat tidurku sendiri?",
  ui_story_5033_50331001_43_dialog_content = "Anu…",
  ui_story_5033_50331001_44_dialog_content = "Ah! S-Siapa kamu?! Apa yang kamu lakukan, bersembunyi di sana?!",
  ui_story_5033_50331001_45_dialog_content = "T-Tolong jangan salah paham! Saya tidak bermaksud menakut-nakuti Anda dengan menjadi begitu tenang!",
  ui_story_5033_50331001_46_dialog_content = "Hanya saja... Kau baru saja membelai bantalmu, dan itu terlalu manis untuk diganggu...",
  ui_story_5033_50331001_47_dialog_content = "Apa kau... mengolok-olokku?!",
  ui_story_5033_50331001_48_dialog_content = "... Sudahlah. Tertawalah jika Anda mau, saya tidak peduli.",
  ui_story_5033_50331001_49_dialog_content = "Saya hanya pernah melihat bantal di jendela toko sebelumnya. Mereka begitu lembut untuk disentuh...",
  ui_story_5033_50331001_50_dialog_content = "Sepertinya kau teman sekamar baruku.",
  ui_story_5033_50331001_51_dialog_content = "Punggungku agak sakit karena berdiri terlalu lama. Keberatan jika kita duduk di tempat tidurmu dan mengobrol?",
  ui_story_5033_50331001_52_dialog_content = "Y-Ya, tentu saja! Di sini, buat dirimu nyaman!",
  ui_story_5033_50331001_53_dialog_content = "Nama saya Antares. Apa milikmu?",
  ui_story_5033_50331001_54_dialog_content = "Aku... Tidak benar-benar punya namaku sendiri. Saya telah menggunakan nama yang diberikan seorang biarawati ketika dia menemukan saya berkeliaran di sekitar Euphoria.",
  ui_story_5033_50331001_55_dialog_content = "Apa yang akan kamu lakukan di tempat seperti ini? Anda tahu di mana kita berada, bukan?",
  ui_story_5033_50331001_56_dialog_content = "Y-Yah, seseorang memberi tahu saya bahwa saya mungkin terpilih jika saya mendaftar untuk ini.",
  ui_story_5033_50331001_57_dialog_content = "Dan jika saya terpilih, saya tidak perlu khawatir tentang makanan atau pakaian lagi. Saya bahkan akan memiliki tempat tidur saya sendiri!",
  ui_story_5033_50331001_58_dialog_content = "Jadi saya mendaftar, terpilih, dan kemudian saya bertemu Anda!",
  ui_story_5033_50331001_59_dialog_content = "Jadi kau benar-benar tidak tahu apa yang mereka lakukan di sekitar sini, huh...",
  ui_story_5033_50331001_60_dialog_content = "Kurasa tidak... Ada apa, Antares? Tanganmu sangat dingin.",
  ui_story_5033_50331001_61_dialog_content = "Aku akan pergi menutup jendela!",
  ui_story_5033_50331001_62_dialog_content = "aku baik-baik saja...",
  ui_story_5033_50331001_63_dialog_content = "Oke, tapi jika Anda merasa kedinginan, beri tahu saya.",
  ui_story_5033_50331001_64_dialog_content = "Jadi kamu sudah lama di sini? Tempat macam apa ini, sih?",
  ui_story_5033_50331001_65_dialog_content = "Ya, aku sudah tinggal di ruangan ini selama yang bisa kuingat. Tempat ini...",
  ui_story_5033_50331001_66_dialog_content = "Adalah fasilitas pelatihan bawah tanah pribadi untuk tentara bayaran Euforia.",
  ui_story_5033_50331001_67_dialog_content = "Pollux... Kurasa kita perlu bicara serius sekarang.",
  ui_story_5033_50331001_68_dialog_content = "Uh... Aku tahu apa yang ingin kau katakan, Antares! Aku berjanji akan lebih memperhatikan lain kali, oke?",
  ui_story_5033_50331001_69_dialog_content = "Kamu mengatakan itu setiap saat... Kapan kamu benar-benar akan menepati janjimu?!",
  ui_story_5033_50331001_70_dialog_content = "Setiap kali saya kembali dari misi, Anda memiliki banyak luka baru di tubuh Anda sebelum luka lama Anda selesai sembuh...",
  ui_story_5033_50331001_71_dialog_content = "Apa kau tahu betapa sakitnya melihatmu seperti ini? Untuk membalutmu, hanya untuk menemukan luka baru keesokan harinya?!",
  ui_story_5033_50331001_72_dialog_content = "Perasaanku seharusnya tidak penting bagimu, sama sekali...",
  ui_story_5033_50331001_73_dialog_content = "Maaf, Antares... Aku hanya tidak tahu apa yang salah denganku.",
  ui_story_5033_50331001_74_dialog_content = "Ketika saya pertama kali tiba di sini, Anda sudah pergi misi. Pada saat itu, saya tahu ada kesenjangan besar dalam kekuatan kami ...",
  ui_story_5033_50331001_75_dialog_content = "Jadi aku belajar sekeras yang aku bisa, siang dan malam... Aku bahkan memaksakan diriku untuk berdebat dengan tentara bayaran yang jauh lebih kuat dan berperingkat lebih tinggi dariku.",
  ui_story_5033_50331001_76_dialog_content = "Tapi bagi mereka, aku sama sekali tidak sebaik kalian... Bahkan rekrutan yang datang satu atau dua tahun setelahku menunjukkan lebih banyak janji!",
  ui_story_5033_50331001_77_dialog_content = "Aku ingin sepertimu, Antares... Aku juga ingin menjadi tentara bayaran yang kuat!",
  ui_story_5033_50331001_78_dialog_content = "Bukan seperti itu, Pollux. Mendengarkan...",
  ui_story_5033_50331001_79_dialog_content = "Semua orang tahu seberapa bagus nilaimu, kan? Mereka bahkan menyebut kami Gemini karena seberapa dekat kami!",
  ui_story_5033_50331001_80_dialog_content = "Kamu sudah luar biasa, Pollux. Tidak perlu terlalu memaksakan diri...",
  ui_story_5033_50331001_81_dialog_content = "Lalu mengapa saya masih terjebak di sini, sementara Anda dan yang lainnya pergi misi?",
  ui_story_5033_50331001_82_dialog_content = "Maaf... Antares... Aku tahu aku keras kepala dan kamu hanya memperhatikanku...",
  ui_story_5033_50331001_83_dialog_content = "Anda tidak perlu meminta maaf kepada saya, Pollux. Bukan aku yang kau sakiti... Kau.",
  ui_story_5033_50331001_84_dialog_content = "Jika saya bisa melakukan semuanya lagi, saya akan memilih hidup saya sendiri.",
  ui_story_5033_50331001_85_dialog_content = "Hidup tanpa rasa bersalah terus-menerus... Atau mimpi buruk yang membangunkanku setiap malam.",
  ui_story_5033_50331001_86_dialog_content = "Sebuah kehidupan... Tanpa \"misi\".",
  ui_story_5033_50331001_87_dialog_content = "Hah? Tapi aku benar-benar ingin pergi misi, Antares...",
  ui_story_5033_50331001_88_dialog_content = "Aku ingin berjuang di sisimu, jadi kita bisa saling mendukung sepanjang waktu.",
  ui_story_5033_50331001_89_dialog_content = "Setelah saya diberitahu, saya akhirnya bisa pergi misi ...",
  ui_story_5033_50331001_90_dialog_content = "Apa yang kamu lakukan di sana, Pollux? Apakah itu rahasia?",
  ui_story_5033_50331001_91_dialog_content = "H-Hei! Tutup matamu! Tidak mengintip, kau dengar?!",
  ui_story_5033_50331001_92_dialog_content = "Ugh, baiklah... Lihat? Mereka tutup.",
  ui_story_5033_50331001_93_dialog_content = "Dan... Selesai! Anda dapat membuka mata Anda sekarang!",
  ui_story_5033_50331001_94_dialog_content = "Apakah ini <color=#FFB400>bros</color>... Untuk saya?",
  ui_story_5033_50331001_94X1_dialog_content = "Ya, tokonya bilang itu hydrangea, dan menurutku itu sangat cocok untukmu.",
  ui_story_5033_50331001_95_dialog_content = "Ya! Saya hanya mendapat sedikit gaji sekarang, jadi hanya ini yang saya mampu.",
  ui_story_5033_50331001_96_dialog_content = "Tapi begitu aku menyelesaikan misiku dan mengumpulkan gajiku, aku akan memberimu sesuatu yang lebih bagus! Sesuatu yang saya yakin Anda akan menyukainya!",
  ui_story_5033_50331001_97_dialog_content = "M-Misi...?",
  ui_story_5033_50331001_98_dialog_content = "Ya! Saya bertemu dengan Bos beberapa hari yang lalu, dan dia memberi tahu saya bahwa dia akan memiliki misi untuk saya segera!",
  ui_story_5033_50331001_99_dialog_content = "Jadi saya mendapatkan ini untuk Anda merayakan keinginan saya menjadi kenyataan, dan terima kasih karena selalu ada untuk saya.",
  ui_story_5033_50331001_100_dialog_content = "Sekarang, apa yang harus saya dapatkan selanjutnya...?",
  ui_story_5033_50331001_101_dialog_content = "...",
  ui_story_5033_50331001_102_dialog_content = "Ada apa, Antares? Apakah kamu tidak menyukainya?",
  ui_story_5033_50331001_103_dialog_content = "Tidak, bukan itu. Saya suka betapa cantiknya bunga ungu itu.",
  ui_story_5033_50331001_104_dialog_content = "Pollux...",
  ui_story_5033_50331001_105_dialog_content = "Ya?",
  ui_story_5033_50331001_106_dialog_content = "Terima kasih... Karena telah menjadi temanku. Waktu yang kita habiskan bersama adalah saat paling bahagia dalam hidupku.",
  ui_story_5033_50331001_107_dialog_content = "Anda tidak akan menjadi Antares jika Anda tidak keluar dengan sesuatu yang murahan.",
  ui_story_5033_50331001_108_dialog_content = "Saya melakukannya juga.",
  ui_story_5033_50331001_109_dialog_content = "Terima kasih telah menjadi temanku, Antares.",
  ui_story_5033_50331001_110_dialog_content = "Saya tidak pernah bisa mengharapkan pencarian itu menjadi seperti itu.",
  ui_story_5033_50331001_111_dialog_content = "Aku, di sebuah arena, menghadap sahabatku...",
  ui_story_5033_50331001_112_dialog_content = "M-Mengapa...",
  ui_story_5033_50331001_113_dialog_content = "Mengapa ANDA lawan saya ...?",
  ui_story_5033_50331001_114_dialog_content = "Salah satunya adalah droid tempur, yang dibesarkan di pertarungan yang sebenarnya.",
  ui_story_5033_50331001_115_dialog_content = "Yang lainnya adalah pendatang baru yang menjanjikan dan bakat yang diasah dengan hati-hati di kamp pelatihan.",
  ui_story_5033_50331001_116_dialog_content = "Duo dinamit ini dikenal sebagai Gemini! Tapi hari ini, hanya satu dari mereka yang akan keluar dari ring.",
  ui_story_5033_50331001_117_dialog_content = "Apakah Euphoria pernah menyaksikan—atau akan pernah menyaksikan—pertandingan yang menggigit kuku dan seru seperti ini?",
  ui_story_5033_50331001_118_dialog_content = "Antares, kamu...",
  ui_story_5033_50331001_119_dialog_content = "Angkat belatimu, dan datang padaku.",
  ui_story_5033_50331001_120_dialog_content = "Bukankah itu pencarian yang Anda nantikan?",
  ui_story_5033_50331001_121_dialog_content = "Aku tahu kau sudah berlatih keras untuk ini.",
  ui_story_5033_50331001_122_dialog_content = "Tapi, aku…",
  ui_story_5033_50331001_123_dialog_content = "Apa lagi yang kautunggu?",
  ui_story_5033_50331001_124_dialog_content = "Jika ini benar-benar pertarungan, Anda akan mati belasan kali sekarang.",
  ui_story_5033_50331001_125_dialog_content = "Aku hanya tidak bisa mengangkat tanganku melawanmu...",
  ui_story_5033_50331001_126_dialog_content = "Bagaimana jika saya katakan bahwa satu-satunya alasan Anda di sini, sekarang, adalah karena saya?",
  ui_story_5033_50331001_127_dialog_content = "Tidak... Tidak, itu tidak mungkin benar!",
  ui_story_5033_50331001_128_dialog_content = "Mengapa membuat kita saling bertarung? Tidakkah menurutmu itu sedikit aneh?",
  ui_story_5033_50331001_129_dialog_content = "Aneh? Tidak ada yang aneh di Euphoria, dan itu menyimpan banyak rahasia yang bahkan tidak bisa Anda tebak.",
  ui_story_5033_50331001_130_dialog_content = "Aku sudah jelas... membujukmu berkali-kali di masa lalu.",
  ui_story_5033_50331001_131_dialog_content = "Tidak mungkin aku bisa membuat tunjangan untukmu.",
  ui_story_5033_50331001_132_dialog_content = "Anda benar-benar akan mengangkat tangan melawan saya ...?",
  ui_story_5033_50331001_133_dialog_content = "Benar. Saya dilahirkan dalam pertempuran, dan hal pertama yang saya pelajari adalah—",
  ui_story_5033_50331001_134_dialog_content = "Tidak menunjukkan belas kasihan kepada siapa pun.",
  ui_story_5033_50331001_135_dialog_content = "Tidak... <size=45>Aku tidak ingin melawanmu, Antares!</size>",
  ui_story_5033_50331001_136_dialog_content = "<size=45>Pertahankan dirimu, atau MATI!!</size>",
  ui_story_5033_50331001_137_dialog_content = "Ketika saya datang ke...",
  ui_story_5033_50331001_138_dialog_content = "Sudah terlambat.",
  ui_story_5033_50331001_139_dialog_content = "Argh...!",
  ui_story_5033_50331001_140_dialog_content = "Aku... Aku... Apa yang telah kulakukan?",
  ui_story_5033_50331001_141_dialog_content = "Antares... Kenapa kamu tidak lari?",
  ui_story_5033_50331001_142_dialog_content = "<anim type=Shake>Terima kasih... Terima kasih... Pollux...</anim>",
  ui_story_5033_50331001_143_dialog_content = "Antar! TIDAK! Jangan tinggalkan aku... Maaf... Maafkan aku...",
  ui_story_5033_50331001_144_dialog_content = "Kenapa... Kenapa kau tidak kabur saja?",
  ui_story_5033_50331001_145_dialog_content = "<anim type=Shake>Dengan cara ini aku... bisa bebas...</anim>",
  ui_story_5033_50331001_146_dialog_content = "<anim type=Shake>Akhirnya gratis...</anim>",
  ui_story_5033_50331001_147_dialog_content = "Saya melakukannya. Kematian Antares ada padaku... Aku membunuh satu-satunya temanku di seluruh dunia dengan tanganku sendiri.",
  ui_story_5033_50331001_148_dialog_content = "Saya tidak mengerti sampai belati di tangan saya sudah menembus dada Antares.",
  ui_story_5033_50331001_149_dialog_content = "Betapa mengerikannya hal yang pernah saya dambakan.",
  ui_story_5033_50331001_150_dialog_content = "Inilah mengapa Anda tidak lagi menggunakan belati ...",
  ui_story_5033_50331001_151_dialog_content = "Ya. Kejadian hari itu terus berputar di kepalaku, begitu nyata seolah aku benar-benar kembali ke arena.",
  ui_story_5033_50331001_152_dialog_content = "Saya kehilangan kesadaran setelah pertarungan dan mengalami demam tinggi selama lebih dari seminggu.",
  ui_story_5033_50331001_153_dialog_content = "Ketika saya akhirnya bangun, saya sendirian di kamar.",
  ui_story_5033_50331001_154_dialog_content = "Pakaian Antares, buku catatan... Semua jejaknya telah hilang sama sekali dari dalam empat dinding persegi itu.",
  ui_story_5033_50331001_155_dialog_content = "Itu sangat bersih, sangat steril... Seolah-olah dia bahkan tidak pernah ada di dunia ini.",
  ui_story_5033_50331001_156_dialog_content = "Aku segera meninggalkan ruangan itu juga. Dalam waktu kurang dari sebulan, kedua penghuninya hilang.",
  ui_story_5033_50331001_157_dialog_content = "Apakah Anda meninggalkan organisasi itu?",
  ui_story_5033_50331001_158_dialog_content = "Yah, itu bukan kapal yang melompat melainkan didorong.",
  ui_story_5033_50331001_159_dialog_content = "Setelah pertarungan itu, saya mulai takut dan merasa sulit bahkan untuk memegang belati.",
  ui_story_5033_50331001_160_dialog_content = "Untuk tentara bayaran, kehilangan kemampuan tempur berarti kehilangan semua nilai.",
  ui_story_5033_50331001_161_dialog_content = "Jadi wajar saja aku dikeluarkan dari tim, dan ditawan di ruang bawah tanah.",
  ui_story_5033_50331001_162_dialog_content = "Tepat sampai Eclipsites datang dan meratakan tempat itu dengan tanah.",
  ui_story_5033_50331001_163_dialog_content = "Apakah Anda memiliki intel lain?",
  ui_story_5033_50331001_164_dialog_content = "Tidak, aku minta maaf. Itu semua yang aku tahu...",
  ui_story_5033_50331001_165_dialog_content = "Namun, saya akan berjanji kepada Anda—saya akan membantu Anda menyelesaikannya.",
  ui_story_5033_50331001_166_dialog_content = "<color=#e8d9bb>Dadada...</color>",
  ui_story_5033_50331001_167_dialog_content = "Tahan! Saya merasakan banyak orang menuju ke sini!",
  ui_story_5033_50331001_168_dialog_content = "Siapa itu?",
  ui_story_5033_50331001_169_dialog_content = "Saya tidak tahu, tapi saya pikir mereka ingin... mengelilingi gereja?!",
  ui_story_5033_50331101_1_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5033_50331101_2_dialog_content = "Ayo bergerak! Ayo cepat!",
  ui_story_5033_50331101_3_dialog_content = "Senjata siap, bersiap untuk terlibat. Raven's Blood bukanlah hal yang mudah!",
  ui_story_5033_50331101_4_dialog_content = "Siap!",
  ui_story_5033_50331101_5_dialog_content = "Di bawah-rendah sampai kita berada di posisi. Saya akan memberikan sinyal api, Anda mengerti?",
  ui_story_5033_50331101_6_dialog_content = "Baik!",
  ui_story_5033_50331101_7_dialog_content = "Apakah orang-orang kita semua hadir dan benar?",
  ui_story_5033_50331101_8_dialog_content = "Semua orang ada di sini, bos! Darah Raven selesai untuk kali ini!",
  ui_story_5033_50331101_9_dialog_content = "Haha, luar biasa! Aku sudah menunggu lama untuk hari ini.",
  ui_story_5033_50331101_10_dialog_content = "Hei, tunggu sebentar... Bukankah Gustav menyuruh kita untuk tidak terburu-buru?",
  ui_story_5033_50331101_11_dialog_content = "<size=45>Apa yang kamu ketahui?!</size>",
  ui_story_5033_50331101_12_dialog_content = "Ini adalah kesempatan sempurna untuk menemukan bukti kolusi antara Raven's Blood dan Umbraton.",
  ui_story_5033_50331101_13_dialog_content = "Apa yang akan kita lakukan jika kita membiarkan mereka pergi, hmm?",
  ui_story_5033_50331101_14_dialog_content = "Negatif. Saya harus melapor kembali ke Gustav.",
  ui_story_5033_50331101_15_dialog_content = "Kapan Anda menjadi boneka Gustav?",
  ui_story_5033_50331101_16_dialog_content = "Baiklah kalau begitu, pergi dari sini. Aku bilang PERGI! Jangan ganggu aku!",
  ui_story_5033_50331101_17_dialog_content = "Siapa pun mereka, mereka pasti menuju ke sini.",
  ui_story_5033_50331101_18_dialog_content = "Siapa yang berani mencari masalah dengan Raven's Blood?",
  ui_story_5033_50331101_19_dialog_content = "Saya khawatir kali ini tidak sesederhana itu.",
  ui_story_5033_50331101_20_dialog_content = "Tidak ada yang akan begitu terburu-buru mendekati gereja sebelumnya.",
  ui_story_5033_50331101_21_dialog_content = "Ini adalah kelompok besar kali ini. Saya khawatir mereka bersatu untuk melancarkan serangan.",
  ui_story_5033_50331101_22_dialog_content = "Kenapa harus sekarang, sih?",
  ui_story_5033_50331101_23_dialog_content = "Sepertinya mereka benar-benar menentang orang-orang Umbraton yang memasuki Euphoria.",
  ui_story_5033_50331101_24_dialog_content = "Itu karena kami datang ke sini?",
  ui_story_5033_50331101_25_dialog_content = "Maaf, Corax.",
  ui_story_5033_50331101_26_dialog_content = "Mungkin cara kami melakukan sesuatu membuat geng-geng lokal kesal.",
  ui_story_5033_50331101_27_dialog_content = "Saya khawatir kita harus mengurus pertengkaran geng lokal ini terlebih dahulu.",
  ui_story_5033_50331101_28_dialog_content = "Mereka hanya pengecut, menggertak yang lemah tapi takut yang kuat. Apakah mereka benar-benar berpikir mereka bisa mengalahkan Raven's Blood kita, bahkan dengan bersatu?",
  ui_story_5033_50331101_29_dialog_content = "Saya katakan bawa mereka, tidak peduli berapa banyak!",
  ui_story_5033_50331101_30_dialog_content = "Kendalikan dalam sedikit. Tidak ada manfaat bagi kita dalam memperburuk keadaan.",
  ui_story_5033_50331101_31_dialog_content = "Casta, Corax—bawa anak-anak ke Nekoyashiki untuk berlindung.",
  ui_story_5033_50331101_32_dialog_content = "Mereka mengincar Raven's Blood dan gereja. Saya akan mencoba untuk menghentikan mereka di sini.",
  ui_story_5033_50331101_33_dialog_content = "Oke. Aku akan menjaga anak-anak tetap aman, aku janji.",
  ui_story_5033_50331101_34_dialog_content = "Bagaimana denganmu? Tidak ada yang bisa menangani sebanyak itu sendirian, bahkan Anda sendiri.",
  ui_story_5033_50331101_35_dialog_content = "Saya akan melakukan yang terbaik untuk memberi Anda waktu. Sekarang pergi, bawa anak-anak dan pergi dari sini.",
  ui_story_5033_50331101_36_dialog_content = "... Dipahami. Sebaiknya kau bertahan sampai aku kembali!",
  ui_story_5033_50331101_37_dialog_content = "Aku akan membantu. Beberapa dari anak-anak terluka, jadi kita perlu menjaga mereka dalam bergerak.",
  ui_story_5033_50331101_38_dialog_content = "PlayerName.",
  ui_story_5033_50331101_39_dialog_content = "Hah? Di Sini!",
  ui_story_5033_50331101_40_dialog_content = "Meskipun saya mungkin tidak tahu banyak tentang Anda, saya rasa Anda dapat menemukan rute yang aman untuk mengeluarkan semua orang dari sini.",
  ui_story_5033_50331101_41_dialog_content = "Bisakah saya menyerahkannya kepada Anda untuk memimpin?",
  ui_story_5033_50331101_42_dialog_content = "Bukan masalah!",
  ui_story_5033_50331101_43_dialog_content = "Nekoyashiki biasanya ada di kabinnya. Apakah Anda ingat di mana itu?",
  ui_story_5033_50331101_44_option_content = "Ya.",
  ui_story_5033_50331101_45_dialog_content = "Nekoyashiki tinggal di sebuah kabin dengan grafiti berbentuk bekas luka.",
  ui_story_5033_50331101_46_dialog_content = "Seberangi gang selatan gereja, pergi beberapa blok lagi, dan kemudian menyusuri jalan sempit.",
  ui_story_5033_50331101_47_dialog_content = "Seharusnya ada sekitar lima atau enam putaran ...",
  ui_story_5033_50331101_48_dialog_content = "Anda harus melakukan enam putaran.",
  ui_story_5033_50331101_49_dialog_content = "Baiklah, aku mengerti. Biarkan aku memikirkan cara terbaik untuk pergi.",
  ui_story_5033_50331101_50_dialog_content = "Oke. Tanyakan Casta jika Anda memiliki pertanyaan lebih lanjut. Saya khawatir dia dan Corax harus menangani pertempuran apa pun.",
  ui_story_5033_50331101_51_dialog_content = "Jika perlu, Anda juga bisa bertanya pada Latan. Dia mungkin masih muda, tapi dia bisa diandalkan.",
  ui_story_5033_50331101_52_option_content = "Tidak.",
  ui_story_5033_50331101_53_dialog_content = "Ini adalah kabin kecil yang pernah Anda kunjungi sebelumnya. Yang dengan grafiti berbentuk bekas luka di luar.",
  ui_story_5033_50331101_54_dialog_content = "Ketika Anda pergi, pertama menyeberangi gang selatan gereja, lalu pergi beberapa blok lagi.",
  ui_story_5033_50331101_55_dialog_content = "Jika ada orang di jalanan, pergilah sedikit lebih jauh dan cari gang dengan stiker beruang di dinding.",
  ui_story_5033_50331101_56_dialog_content = "Itu adalah karya anak-anak. Mereka akan mengenali mereka, juga Casta.",
  ui_story_5033_50331101_57_dialog_content = "Saya khawatir Casta dan Corax perlu menangani pertempuran apa pun. Terserah Anda untuk terus berjalan bersama anak-anak.",
  ui_story_5033_50331101_58_dialog_content = "Ketika Anda sampai di sana, beri tahu Nekoyashiki semuanya. Dia akan bisa membawamu ke tempat yang aman. Apakah Anda punya semua itu?",
  ui_story_5033_50331101_59_dialog_content = "Aku paham.",
  ui_story_5033_50331101_60_dialog_content = "Bagus sekali. Kamu anak yang baik.",
  ui_story_5033_50331101_61_option_content = "Aku bukan anak kecil.",
  ui_story_5033_50331101_62_dialog_content = "Anda telah memberi saya tugas untuk membawa kita ke sana, dan saya akan melakukannya tanpa hambatan.",
  ui_story_5033_50331101_63_dialog_content = "Aku juga bisa membantu Casta dan Corax untuk bertarung, jadi anak-anak tidak akan terluka. Anda bisa bersantai.",
  ui_story_5033_50331101_64_dialog_content = "Indah sekali. Saya melihat kepercayaan saya pada Anda tidak salah tempat ...",
  ui_story_5033_50331101_65_dialog_content = "Kamu jauh lebih dewasa dari yang aku kira. Ketika debu mereda dari semua ini, saya ingin mendengar cerita Anda.",
  ui_story_5033_50331101_66_dialog_content = "Baiklah, itu kesepakatan.",
  ui_story_5033_50331101_67_option_content = "Aku akan menjadi anak yang baik.",
  ui_story_5033_50331101_68_dialog_content = "Mereka juga anak-anak yang baik. Saya yakin mereka akan bekerja sama.",
  ui_story_5033_50331101_69_dialog_content = "Tidak perlu khawatir. Kami akan langsung kembali, setelah kami mendapatkan mereka di tempat yang aman.",
  ui_story_5033_50331101_70_dialog_content = "Baik. Mendengar itu membuatku lebih tenang.",
  ui_story_5033_50331101_71_dialog_content = "Sebaiknya tunggu sampai kami kembali untuk membantu, Pollux!",
  ui_story_5033_50331101_72_dialog_content = "Saya tahu. Aku akan melakukan yang terbaik. Terima kasih.",
  ui_story_5033_50331101_73_dialog_content = "Casta dan anak-anak akan datang. Anda harus pergi.",
  ui_story_5033_50331101_74_dialog_content = "Pollux, Casta bilang kita harus pergi ke tempat yang aman. Bagaimana denganmu? Anda tidak ikut dengan kami?",
  ui_story_5033_50331101_75_dialog_content = "Pollux...! Pollux... Ikut dengan kami!",
  ui_story_5033_50331101_76_dialog_content = "Sekarang, semuanya, jangan ganggu Pollux lagi. Bukankah kita baru saja setuju untuk mendengarkan rencananya?",
  ui_story_5033_50331101_77_dialog_content = "Namun…",
  ui_story_5033_50331101_78_dialog_content = "Jangan khawatirkan aku, anak-anak.",
  ui_story_5033_50331101_79_dialog_content = "Saya harus tinggal di sini sebentar, karena ada sesuatu yang harus saya urus.",
  ui_story_5033_50331101_80_dialog_content = "Kalian harus pergi ke tempat yang aman sekarang. Cobalah untuk menjauh dari sini.",
  ui_story_5033_50331101_81_dialog_content = "Uh... Tapi ada banyak Eclipsites di luar gereja. Jika kau tidak ikut dengan kami...",
  ui_story_5033_50331101_82_dialog_content = "Casta dan Dr. Corax akan menjagamu, jangan khawatir.",
  ui_story_5033_50331101_83_dialog_content = "PlayerName dan Nekoyashiki akan berada di sana juga.",
  ui_story_5033_50331101_84_dialog_content = "Kapan kita bisa kembali ke gereja?",
  ui_story_5033_50331101_85_dialog_content = "Tidak apa-apa bahkan jika kita tidak bisa kembali ke gereja. Kita akan menemukan tempat perlindungan lain.",
  ui_story_5033_50331101_86_dialog_content = "Yang paling penting adalah semua orang aman dan bahagia bersama.",
  ui_story_5033_50331101_87_dialog_content = "Tapi, tapi kamu... Kamu akan tetap bersama kami, kan?",
  ui_story_5033_50331101_88_dialog_content = "Ya, tentu saja!",
  ui_story_5033_50331101_89_dialog_content = "Aku akan datang untuk mencarimu, segera setelah aku mengurus ini.",
  ui_story_5033_50331101_90_dialog_content = "Pergilah sekarang, anak-anak.",
  ui_story_5033_50331202_1_dialog_content = "Keluar dari sini, Darah Raven!",
  ui_story_5033_50331202_2_dialog_content = "Keluar dari sini dan mati!",
  ui_story_5033_50331202_3_dialog_content = "Jangan berpikir Anda bisa berjalan di seluruh Euphoria. Keluar dari sini SEKARANG!",
  ui_story_5033_50331202_4_dialog_content = "Anda sebaiknya mendengarkan, Anda banyak di gereja, tetapi terutama mereka berdua dari Umbraton!",
  ui_story_5033_50331202_5_dialog_content = "Saya tidak peduli mengapa Anda di sini, tetapi di Euphoria, Anda bermain sesuai aturan Euphoria.",
  ui_story_5033_50331202_6_dialog_content = "Jika Anda berani berkolusi dengan Raven's Blood, maka Anda semua adalah musuh Euphoria.",
  ui_story_5033_50331202_7_dialog_content = "Jika ada sesuatu yang ingin Anda diskusikan, maka Anda bisa datang ke gereja.",
  ui_story_5033_50331202_8_dialog_content = "Kami akan menyambut semua orang, dan saya yakin Anda akan puas dengan sambutan Anda, baik itu dengan pistol atau pisau.",
  ui_story_5033_50331202_9_dialog_content = "Hei bos, itu suara Pollux!",
  ui_story_5033_50331202_10_dialog_content = "Apa yang mereka lakukan di sana?!",
  ui_story_5033_50331202_11_dialog_content = "E-entahlah…",
  ui_story_5033_50331202_12_dialog_content = "Kita harus bagaimana?",
  ui_story_5033_50331202_13_dialog_content = "Bagaimana kalau... Bos, kamu masuk dulu?",
  ui_story_5033_50331202_14_dialog_content = "Apakah kamu bodoh, bodoh?!",
  ui_story_5033_50331202_15_dialog_content = "Saya pasti tidak bisa masuk ke sana sendirian! Itu pasti jebakan.",
  ui_story_5033_50331202_16_dialog_content = "Bos benar! Jika kita akan masuk, kita semua harus bergegas masuk bersama.",
  ui_story_5033_50331202_17_dialog_content = "Terburu-buru ke dalam apa, numbskull?! Panggil seseorang untuk membawa bahan peledak!",
  ui_story_5033_50331202_18_dialog_content = "Uh-oh... Ya, tentu saja.",
  ui_story_5033_50331202_19_dialog_content = "Yang lain semua hanya menunggu di sini. Suruh mereka mengelilingi tempat itu, dan pastikan tidak ada yang lolos.",
  ui_story_5033_50331202_20_dialog_content = "Ide yang bagus!",
  ui_story_5033_50331202_21_dialog_content = "Kok masih belum ada kabar dari Gustav? Ia semakin putus asa...",
  ui_story_5033_50331202_22_dialog_content = "Meong...",
  ui_story_5033_50331202_23_dialog_content = "Itu sinyalnya! Akhirnya...",
  ui_story_5033_50331202_24_dialog_content = "Um ... Apakah Anda mendapatkannya?",
  ui_story_5033_50331202_25_dialog_content = "Oh sayang, apakah Anda menunggu kertas kecil ini?",
  ui_story_5033_50331202_26_dialog_content = "Siapa... Siapa kamu? Berapa lama Anda berada di belakang saya ?!",
  ui_story_5033_50331202_27_dialog_content = "Sejak Anda tiba di sini.",
  ui_story_5033_50331202_28_dialog_content = "Biarawati?! aku sudah selesai untuk...",
  ui_story_5033_50331202_29_dialog_content = "Betul sekali. Anda bisa memanggil saya Sister Anne, atau <color=#FFB400>Antares</color>.",
  ui_story_5033_50331202_30_dialog_content = "Tapi sekali lagi... Anda tidak akan memiliki kesempatan untuk memberitahu siapa pun.",
  ui_story_5033_50331202_31_dialog_content = "Tidak! Tolong jangan bunuh aku... Aku... Aku hanya menjalankan tugas... Aku tidak tahu apa-apa.",
  ui_story_5033_50331202_32_dialog_content = "Mungkin aku tidak akan membunuhmu, tapi sekali lagi, mungkin kau bisa memberitahuku siapa Gustav itu?",
  ui_story_5033_50331202_33_dialog_content = "Saya menduga... Bahwa dia memberi Anda selembar kertas ini, kan?",
  ui_story_5033_50331202_34_dialog_content = "Aku tidak percaya ini semudah ini.",
  ui_story_5033_50331202_35_dialog_content = "Katakan padaku, apakah ini semacam jebakan untuk memikatku?",
  ui_story_5033_50331202_36_dialog_content = "Apa yang kau bicarakan...? Aku bahkan tidak mengerti apa yang kamu katakan!",
  ui_story_5033_50331202_37_dialog_content = "Oh tidak ... Mungkin situasinya sangat tidak stabil sehingga dia tidak punya waktu untuk menutupi jejaknya ...",
  ui_story_5033_50331202_38_dialog_content = "Apa yang kamu coba katakan? Ini gila...",
  ui_story_5033_50331202_39_dialog_content = "Jangan bermain bodoh denganku! Saya tahu Anda mengenali saya pada detik pertama Anda melihat saya.",
  ui_story_5033_50331202_40_dialog_content = "Terlebih lagi Anda tahu apa yang harus saya lakukan di sini, atau lebih tepatnya... apa yang mungkin saya lakukan di sini.",
  ui_story_5033_50331202_41_dialog_content = "Orang tidak berbohong, ketika menatap kematian di wajah.",
  ui_story_5033_50331202_42_dialog_content = "Argh…",
  ui_story_5033_50331202_43_dialog_content = "Antares... Aku tidak akan memberitahumu apa-apa.",
  ui_story_5033_50331202_44_dialog_content = "Aku bahkan tidak membutuhkannya lagi.",
  ui_story_5033_50331202_45_dialog_content = "<color=#e8d9bb>Aduh—!</color>",
  ui_story_5033_50331202_46_dialog_content = "Ugh... Kamu...",
  ui_story_5033_50331202_47_dialog_content = "Jadi... Begini rasanya... dibunuh oleh Grim Reaper...",
  ui_story_5033_50331202_48_dialog_content = "Sebagai ucapan terima kasih kepada Anda karena telah memberi saya petunjuk ini, saya akan melakukan yang terbaik untuk membuat Anda tidak terlalu menderita.",
  ui_story_5033_50331202_49_dialog_content = "Anda memiliki terima kasih saya.",
  ui_story_5033_50331202_50_dialog_content = "Dan sekarang... Akhirnya, aku bisa pergi mencari Pollux.",
  ui_story_5033_50331202_51_dialog_content = "Bos! Hei, bos! Kami mendapatkan bahan peledaknya!",
  ui_story_5033_50331202_52_dialog_content = "Ini mungkin tidak banyak, tapi cukup pasti untuk meledakkan gereja itu setinggi langit.",
  ui_story_5033_50331202_53_dialog_content = "Besar! Bagus sekali.",
  ui_story_5033_50331202_54_dialog_content = "Letakkan mereka dalam lingkaran di sekitar gereja.",
  ui_story_5033_50331202_55_dialog_content = "Berhati-hatilah saat menempatkannya, terutama tentang mereka yang menembak dari dalam gereja.",
  ui_story_5033_50331202_56_dialog_content = "Bukan masalah!",
  ui_story_5033_50331202_57_dialog_content = "Permisi, maafkan saya, saya harus ke depan.",
  ui_story_5033_50331202_58_dialog_content = "Dari mana biarawati itu berasal? Menyingkirlah, kecuali jika Anda berada di pasar untuk peti mati ...",
  ui_story_5033_50331202_59_dialog_content = "<color=#e8d9bb>Aduh—!</color>",
  ui_story_5033_50331202_60_dialog_content = "<ukuran=45>ARGH!! Pembunuhan!!</size>",
  ui_story_5033_50331202_61_dialog_content = "Apa?! Apa yang terjadi di belakang sana?",
  ui_story_5033_50331202_62_dialog_content = "Jangan khawatir, tidak ada yang terjadi... Bagaimanapun juga, orang mati dalam perang geng.",
  ui_story_5033_50331202_63_dialog_content = "Darimana asalmu?!",
  ui_story_5033_50331202_64_dialog_content = "<color=#e8d9bb>Aduh—!</color>",
  ui_story_5033_50331202_65_dialog_content = "Argh—! Tanganku... Tanganku!",
  ui_story_5033_50331202_66_dialog_content = "Bos! Biarawati ini, dia punya pisau...!",
  ui_story_5033_50331202_67_dialog_content = "AKU TAHU! Dia yang memotongku! Kejar dia dan bawa dia turun!!",
  ui_story_5033_50331202_68_dialog_content = "Saya menyarankan Anda untuk tidak menggunakan bahan peledak untuk mencoba dan menghancurkan gereja, atau Anda akan menghadapi murka surga.",
  ui_story_5033_50331202_69_dialog_content = "<color=#e8d9bb>Aduh—!</color>",
  ui_story_5033_50331202_70_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5033_50331202_71_dialog_content = "Ledakan? Cepat, menyebar!",
  ui_story_5033_50331202_72_dialog_content = "Biarawati itu membelah selongsong bahan peledak. Dia gila!",
  ui_story_5033_50331202_73_dialog_content = "Lihat itu! Biarawati itu masih hidup... Bagaimana dia bisa melakukannya?",
  ui_story_5033_50331202_74_dialog_content = "Jika semua orang bisa diam sebentar, tolong. Saya di sini karena saya memiliki sesuatu untuk dilakukan di gereja. Setelah saya selesai, saya akan meninggalkan semua orang sendirian.",
  ui_story_5033_50331202_75_dialog_content = "Saya akan menyarankan agar tidak melakukan tindakan gegabah sebelum itu.",
  ui_story_5033_50331202_76_dialog_content = "Kecuali jika Anda ingin bertemu dengan <color=#FFB400>Grim Reaper</color>...",
  ui_story_5033_50331301_1_dialog_content = "A-Apa sekarang... Haruskah kita mendengarkan biarawati itu?",
  ui_story_5033_50331301_2_dialog_content = "Beberapa orang sudah mati, bukan?",
  ui_story_5033_50331301_3_dialog_content = "Jika Anda ingin naik ke sana, silakan... Saya tidak terburu-buru.",
  ui_story_5033_50331301_4_dialog_content = "Apa dia... baru saja menyebut Reaper? Apakah itu berarti bahwa legenda itu benar-benar benar?",
  ui_story_5033_50331301_5_dialog_content = "Ssst... Nah, kalau memang benar, itu satu nama yang tidak boleh kita sebut.",
  ui_story_5033_50331301_6_dialog_content = "Terima kasih atas kerja sama anda.",
  ui_story_5033_50331301_7_dialog_content = "<color=#e8d9bb>Di dalam gereja</color>",
  ui_story_5033_50331301_8_dialog_content = "... Apa sebenarnya yang terjadi di luar sana?",
  ui_story_5033_50331301_9_dialog_content = "<color=#e8d9bb>Da, da...</color>",
  ui_story_5033_50331301_10_dialog_content = "Halo...",
  ui_story_5033_50331301_11_dialog_content = "Perimeter dijaga ketat... Bagaimana Anda bisa masuk ke sini?",
  ui_story_5033_50331301_12_dialog_content = "Saya berbicara dengan orang-orang di luar, dan mereka setuju untuk membiarkan saya lewat.",
  ui_story_5033_50331301_13_dialog_content = "Saya tidak peduli siapa Anda, atau mengapa Anda ada di sini.",
  ui_story_5033_50331301_14_dialog_content = "Tapi tolong, pergi... Tidak ada dewa cahaya di sini, Suster.",
  ui_story_5033_50331301_15_dialog_content = "... Apakah Anda tidak mengenali saya? Pollux.",
  ui_story_5033_50331301_16_dialog_content = "<size=45>Kamu...!</size>",
  ui_story_5033_50331301_17_dialog_content = "Sudah lama.",
  ui_story_5033_50331301_18_dialog_content = "<color=#FFB400>Antares</color>, kamu... Tidak... Bagaimana mungkin?",
  ui_story_5033_50331301_19_dialog_content = "Maaf, Pollux. Ini adalah satu-satunya cara agar aku bisa bertemu denganmu lagi.",
  ui_story_5033_50331301_20_dialog_content = "Sejujurnya, saya pikir Anda akan melupakan saya.",
  ui_story_5033_50331301_21_dialog_content = "Bagaimana mungkin aku bisa lupa?! Saya adalah orang yang bertanggung jawab saat itu ...",
  ui_story_5033_50331301_22_dialog_content = "Jangan beri aku tatapan bersalah itu, Pollux. Saya mohon padamu.",
  ui_story_5033_50331301_23_dialog_content = "Saya terus memikirkannya di kepala saya: apa yang harus saya katakan kepada Anda jika kita bertemu lagi, bagaimana saya harus menghadapi Anda.",
  ui_story_5033_50331301_24_dialog_content = "Tapi sekarang kau di sini, berdiri di depanku, aku bahkan tidak bisa mengingat satu kata pun.",
  ui_story_5033_50331301_25_dialog_content = "Apa yang kamu coba katakan...?",
  ui_story_5033_50331301_26_dialog_content = "Matamu masih sama seperti bertahun-tahun yang lalu. Mereka tidak berubah.",
  ui_story_5033_50331301_27_dialog_content = "Secerah bintang-bintang.",
  ui_story_5033_50331301_28_dialog_content = "Anne... Kau di balik semuanya? Tapi kenapa?",
  ui_story_5033_50331301_29_dialog_content = "Tapi bagaimana ini bisa terjadi? Bagaimana Anda bertahan?",
  ui_story_5033_50331301_30_dialog_content = "Dan kenapa kau... berpakaian seperti biarawati?",
  ui_story_5033_50331301_31_dialog_content = "Jangan khawatir, Pollux, saya akan memberitahu Anda. Aku akan memberitahumu segalanya.",
  ui_story_5033_50331301_32_dialog_content = "Saya akan memberikan versi pendek sekarang ... Kami tidak punya banyak waktu.",
  ui_story_5033_50331301_33_dialog_content = "<color=#e8d9bb>14 tahun yang lalu...</color>",
  ui_story_5033_50331301_34_dialog_content = "Ya, hanya di sini. Sekarang buang ke sungai.",
  ui_story_5033_50331301_35_dialog_content = "Sangat disesalkan! Sebagai salah satu Gemini, dia mati begitu saja.",
  ui_story_5033_50331301_36_dialog_content = "Bos juga tidak berpikir bahwa dia akan membuat pilihan itu ...",
  ui_story_5033_50331301_37_dialog_content = "<color=#e8d9bb>Percikan—</color>",
  ui_story_5033_50331301_38_dialog_content = "Oh, surga! Lihat! Di Sungai...",
  ui_story_5033_50331301_39_dialog_content = "Tolong aku... Ada anak di sini!",
  ui_story_5033_50331301_40_dialog_content = "Nyalakan apinya, cepat! Dia masih hidup! Seseorang memanggil dokter!",
  ui_story_5033_50331301_41_dialog_content = "Aduh... Sakit...",
  ui_story_5033_50331301_42_dialog_content = "Aku masih hidup?",
  ui_story_5033_50331301_43_dialog_content = "Siapa itu di luar pintu?",
  ui_story_5033_50331301_44_dialog_content = "Ini sangat mengerikan. Siapa yang mungkin melakukan ini pada seorang anak?",
  ui_story_5033_50331301_45_dialog_content = "Dia yakin tangguh untuk bertahan bahkan cedera seperti itu.",
  ui_story_5033_50331301_46_dialog_content = "Ada lebih dari ini. Bawa dia ke biara di Umbraton. Saya lebih suka tidak mendapat masalah lagi ...",
  ui_story_5033_50331301_47_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_5033_50331301_48_dialog_content = "Ini koran hari ini, Anne.",
  ui_story_5033_50331301_49_dialog_content = "Ada sepucuk surat juga... Meskipun tidak ada yang bernama <color=#FFB400>Antares</color> di sini, kan?",
  ui_story_5033_50331301_50_dialog_content = "Apa?",
  ui_story_5033_50331301_51_dialog_content = "... Tidak. Tidak ada seorang pun di sini dengan nama itu.",
  ui_story_5033_50331301_52_dialog_content = "Mungkin itu salah nama. Bisakah Anda mencari tahu untuk siapa itu?",
  ui_story_5033_50331301_53_dialog_content = "Ke Antares.",
  ui_story_5033_50331301_54_dialog_content = "Saya adalah murid dewa cahaya yang taat. Saya ingin bertobat atas nama seseorang yang melakukan dosa yang tak terampuni.",
  ui_story_5033_50331301_55_dialog_content = "Dia memalsukan kematiannya sendiri dan menipu keluarganya, semua demi mendapatkan kebebasan palsu.",
  ui_story_5033_50331301_56_dialog_content = "Dia mengambil keuntungan dari persahabatan, membiarkan mereka yang mencintainya menanggung beban hidup atas namanya dan tenggelam ke dalam lautan kesengsaraan.",
  ui_story_5033_50331301_57_dialog_content = "Dia harus bertobat sampai surat pengakuan berikutnya tiba.",
  ui_story_5033_50331301_58_dialog_content = "Siapa yang mengirim ini...?",
  ui_story_5033_50331301_59_dialog_content = "Anda baik-baik saja, Anne? Anda sudah pucat.",
  ui_story_5033_50331301_60_dialog_content = "Biarkan saya menyimpan surat ini di sini untuk saat ini.",
  ui_story_5033_50331301_61_dialog_content = "Mungkin seseorang bernama Antares akan... datang untuk mengklaimnya.",
  ui_story_5033_50331301_62_dialog_content = "Jadi selama bertahun-tahun, Anda hidup sebagai biarawati?",
  ui_story_5033_50331301_63_dialog_content = "Benar.",
  ui_story_5033_50331301_64_dialog_content = "Saya tidak tahu bagaimana siapa pun yang mengirim surat itu tahu identitas asli saya ...",
  ui_story_5033_50331301_65_dialog_content = "Tapi terlepas dari itu, \"dia\" memiliki saya dengan kuat di bawah kendalinya. Saya tidak berani melanggar perintah apa pun.",
  ui_story_5033_50331301_66_dialog_content = "Tapi kamu bahkan tidak takut mati! Bagaimana orang bisa mengendalikanmu? Lalu apakah hantu memiliki kelemahan?",
  ui_story_5033_50331301_67_dialog_content = "Ya... Satu-satunya kelemahanku adalah satu-satunya temanku.",
  ui_story_5033_50331301_68_dialog_content = "Anda mengatakan itu karena saya?",
  ui_story_5033_50331301_69_dialog_content = "Ya. Dia mengatakan bahwa insiden itu hampir menghancurkanmu, tetapi Gemini harus melanjutkan ...",
  ui_story_5033_50331301_70_dialog_content = "\"Pollux tidak ada gunanya jika dia tidak bisa lagi menggunakan pisau.\"",
  ui_story_5033_50331301_71_dialog_content = "Jika saya tidak memenuhi pesanan saya, Anda akan...",
  ui_story_5033_50331301_72_dialog_content = "Saya selalu berpikir bahwa organisasi tidak mengejar kegagalan saya karena Eclipsites menyerbu, dan mereka tidak punya waktu luang ...",
  ui_story_5033_50331301_73_dialog_content = "Tapi organisasi tidak akan membiarkan kita pergi begitu saja.",
  ui_story_5033_50331301_74_dialog_content = "Bahkan jika semua Euphoria dihancurkan, masih akan ada orang-orang di organisasi yang akan terus memanipulasi kita.",
  ui_story_5033_50331301_75_dialog_content = "Jadi kau benar-benar melakukan semua itu, Anne?",
  ui_story_5033_50331301_76_dialog_content = "Aku tidak punya pilihan, Pollux.",
  ui_story_5033_50331301_77_dialog_content = "Anda tidak hanya selamat dari pertarungan itu, tetapi Anda bahkan berhasil melarikan diri dari tempat itu.",
  ui_story_5033_50331301_78_dialog_content = "Saya ingin melindungi kebebasan Anda.",
  ui_story_5033_50331301_79_dialog_content = "Meskipun Anda belum meninggalkan Euphoria, Anda memiliki seseorang untuk dilindungi, untuk diandalkan, bukan?",
  ui_story_5033_50331301_80_dialog_content = "Apakah Anda berbicara tentang anak-anak?",
  ui_story_5033_50331301_81_dialog_content = "Dan wanita muda dengan pistol itu. Dia tampaknya cukup bisa diandalkan.",
  ui_story_5033_50331301_82_dialog_content = "Dengan orang-orang seperti itu di pihak Anda, Anda tidak perlu takut.",
  ui_story_5033_50331301_83_dialog_content = "Sedangkan aku hanyalah undead yang telah lama pergi... keji.",
  ui_story_5033_50331301_84_dialog_content = "Apakah Anda membunuh Suster Matilda juga?!",
  ui_story_5033_50331301_85_dialog_content = "...",
  ui_story_5033_50331301_86_dialog_content = "Jawab aku, Anne!",
  ui_story_5033_50331301_87_dialog_content = "Ya.",
  ui_story_5033_50331301_88_dialog_content = "Kenapa?",
  ui_story_5033_50331301_89_dialog_content = "Membunuhnya hanyalah salah satu dari banyak perintah. Aku bahkan tidak tahu mengapa organisasi menargetkannya.",
  ui_story_5033_50331301_90_dialog_content = "Maaf, Pollux.",
  ui_story_5033_50331301_91_dialog_content = "Kau tahu betapa pentingnya dia bagiku.",
  ui_story_5033_50331301_92_dialog_content = "Saya tidak punya pilihan...",
  ui_story_5033_50331301_93_dialog_content = "Anda datang tanpa senjata.",
  ui_story_5033_50331301_94_dialog_content = "Apa?",
  ui_story_5033_50331301_95_dialog_content = "Senjatamu, Antares. Anda datang sebelum saya, ceritakan semua ini, namun Anda tidak bersenjata ...",
  ui_story_5033_50331301_96_dialog_content = "Apakah Anda berjudi Saya tidak akan mengangkat tangan saya melawan Anda?",
  ui_story_5033_50331301_97_dialog_content = "Rasanya seperti kita pernah ke sini sebelumnya... Meskipun, Pollux, aku bersenjata.",
  ui_story_5033_50331301_98_dialog_content = "Karena misi terakhirku... adalah <color=#FFB400>membunuhmu</color>.",
  ui_story_5033_50331301_99_dialog_content = "Kalau begitu, apa lagi yang kau tunggu?",
  ui_story_5033_50331301_100_dialog_content = "Anda tahu saya, Pollux. Anda tahu saya tidak akan pernah bisa melakukan itu.",
  ui_story_5033_50331301_101_dialog_content = "Saya tidak datang ke sini hanya untuk menceritakan kisah-kisah lama ini...",
  ui_story_5033_50331301_102_dialog_content = "Saya akan mengurus sampah yang telah menggunakan saya selama bertahun-tahun, dan menghilangkan ancaman paling berbahaya bagi Anda dalam prosesnya.",
  ui_story_5033_50331301_103_dialog_content = "Apakah Anda mengharapkan saya untuk bersyukur?",
  ui_story_5033_50331301_104_dialog_content = "Tidak sedikit pun. Aku datang hanya untuk melihatmu untuk terakhir kalinya, sebelum kita mengucapkan selamat tinggal sekali lagi.",
  ui_story_5033_50331301_105_dialog_content = "Pollux tersayang... Kuharap saat semua ini berakhir, kau tahu apa yang harus dilakukan.",
  ui_story_5033_50331301_106_dialog_content = "Eh...",
  ui_story_5033_50331301_107_dialog_content = "Anda benar-benar egois.",
  ui_story_5033_50331301_108_dialog_content = "Cacing jalan ke dalam persahabatan saya dan pisau saya ke tubuh Anda ... Bahkan \"mati\", Anda masih entah bagaimana berhasil mengendalikan nasib saya ...",
  ui_story_5033_50331301_109_dialog_content = "Dan sekarang kau berdiri di hadapanku begitu muluk, kata-katamu sombong.",
  ui_story_5033_50331301_110_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5033_50331301_111_dialog_content = "Sepertinya waktu sudah habis.",
  ui_story_5033_50331301_112_dialog_content = "Orang-orang... Tidak, Eclipsites, masuk dari belakang.",
  ui_story_5033_50331301_113_dialog_content = "Kamu tajam sekarang, Pollux, sangat tajam. Hampir seperti orang yang sama sekali berbeda dengan saat itu.",
  ui_story_5033_50331301_114_dialog_content = "Rambut panjang juga cocok untukmu. Tapi apa yang terjadi dengan matamu?",
  ui_story_5033_50331301_115_dialog_content = "... Saya tidak punya apa-apa yang ingin saya bagikan dengan Anda.",
  ui_story_5033_50331301_116_dialog_content = "Tapi saya lakukan...",
  ui_story_5033_50331301_117_dialog_content = "Dan saya akan membagikannya kepada Anda, segera setelah saya selesai dengan bagian pertama dari penebusan dosa saya.",
  ui_story_5033_50331302_1_dialog_content = "Latan, Schewe...",
  ui_story_5033_50331302_2_dialog_content = "Bagus, kita punya semua orang.",
  ui_story_5033_50331302_3_dialog_content = "Semua orang harus tetap di sini, dan tidak kabur. Dipahami?",
  ui_story_5033_50331302_4_dialog_content = "Saya dapat membantu! Pollux mengajari saya cara bertarung!",
  ui_story_5033_50331302_5_dialog_content = "Iya, aku juga!",
  ui_story_5033_50331302_6_dialog_content = "Menyelesaikan. Ini bukan...",
  ui_story_5033_50331302_7_dialog_content = "Seperti yang terjadi, saya membutuhkan beberapa penjaga terlatih di sini. Surga tahu jika geng preman itu akan muncul.",
  ui_story_5033_50331302_8_dialog_content = "Kalau saja kalian bisa tinggal di sini dan mengawasi pintu masuk dan keluar, itu akan sangat membantu.",
  ui_story_5033_50331302_9_dialog_content = "Luar biasa! Aku akan segera membentuk satuan tugas khusus!!",
  ui_story_5033_50331302_10_dialog_content = "Beberapa papan lagi untuk dipaku di atas jendela juga akan sangat bagus.",
  ui_story_5033_50331302_11_dialog_content = "Roger. Ayo pergi, Latan!",
  ui_story_5033_50331302_12_dialog_content = "Siap, laksanakan!",
  ui_story_5033_50331302_13_dialog_content = "Anda yakin tidak apa-apa bagi anak-anak untuk tinggal di sini?",
  ui_story_5033_50331302_14_dialog_content = "Terlalu berbahaya untuk mengirim mereka ke tempat lain sekarang.",
  ui_story_5033_50331302_15_dialog_content = "Saya belum pernah memiliki orang sebanyak ini di sini sekaligus, dan saya tidak tahu berapa lama persediaan kami akan bertahan.",
  ui_story_5033_50331302_16_dialog_content = "Jangan khawatir. Masalah ini seharusnya tidak memakan waktu lama.",
  ui_story_5033_50331302_17_dialog_content = "Gustav. Anda disini.",
  ui_story_5033_50331302_18_dialog_content = "Pikirkan sesuatu, cepat, sebelum semuanya dimulai di gereja. Anda tahu segalanya tentang Euphoria, bukan?",
  ui_story_5033_50331302_19_dialog_content = "Dari apa yang saya dengar, situasinya kritis.",
  ui_story_5033_50331302_20_dialog_content = "Banyak dari mereka yang berada di sekitar gereja berasal dari satu geng atau lainnya. Yang perlu saya lakukan adalah menghubungi para pemimpin mereka, dan saya harus bisa menyelesaikan ini.",
  ui_story_5033_50331302_21_dialog_content = "Tetapi pertanyaan kuncinya adalah apa yang harus dilakukan terhadap warga sipil biasa.",
  ui_story_5033_50331302_22_dialog_content = "Semua orang sekarang tahu bahwa Pollux melindungi orang-orang Umbraton di gereja. Saya khawatir itu akan membutuhkan lebih dari beberapa kata bagus untuk dipilah.",
  ui_story_5033_50331302_23_dialog_content = "...",
  ui_story_5033_50331302_24_dialog_content = "Anda pasti anak Umbraton itu, kan?",
  ui_story_5033_50331302_25_dialog_content = "Saya kira Taki tidak pernah menyebutkan kami kepada Anda?",
  ui_story_5033_50331302_26_dialog_content = "Dia mengatakan kepada saya bahwa Anda akan datang, tetapi tidak pernah menyebutkan sakit kepala hebat yang akan Anda bawa.",
  ui_story_5033_50331302_27_dialog_content = "Sekarang semua Euphoria berpikir bahwa Shadowlord mengirimmu ke sini untuk menghancurkan tempat itu.",
  ui_story_5033_50331302_28_dialog_content = "Tapi kami belum melakukan apa-apa!",
  ui_story_5033_50331302_29_dialog_content = "Hmph! Agak terlambat bagimu untuk mengatakan itu sekarang.",
  ui_story_5033_50331302_30_dialog_content = "Menyelidiki adalah menyelidiki, tetapi apakah Anda benar-benar harus memprovokasi penduduk setempat dan terlibat dengan Darah Raven?",
  ui_story_5033_50331302_31_dialog_content = "Apakah Anda tahu seberapa antagonis Raven's Blood biasanya?",
  ui_story_5033_50331302_32_dialog_content = "Status geng selalu ditentukan oleh kekuatan dalam Euforia. Kami tidak melakukan apa pun yang bertentangan dengan norma.",
  ui_story_5033_50331302_33_dialog_content = "Saya telah memperingatkan Anda sejak lama untuk tidak menyinggung terlalu banyak orang, atau Anda akan mendapatkan musuh yang menyimpan dendam. Tapi apakah Anda mendengarkan?",
  ui_story_5033_50331302_34_dialog_content = "Dan lihat apa yang terjadi! Sekarang semua geng telah bersatu untuk memusnahkan kalian, dan aku tidak bisa menghentikan mereka.",
  ui_story_5033_50331302_35_dialog_content = "Pollux cukup pintar, entah bagaimana banyak menyelinap keluar dari sana. Omong-omong, di mana dia?",
  ui_story_5033_50331302_36_dialog_content = "Dia tinggal di gereja untuk memberi kami waktu. Bahkan, kita harus kembali untuknya sekarang!",
  ui_story_5033_50331302_37_dialog_content = "Ayo pergi! Mereka bahkan mungkin sudah bertarung!",
  ui_story_5033_50331302_38_dialog_content = "Tenangkan dirimu, Casta. Ada yang harus aku katakan padamu dulu...",
  ui_story_5033_50331302_39_dialog_content = "Seorang individu yang sangat berbahaya ada di sini di Euphoria.",
  ui_story_5033_50331302_40_dialog_content = "Saya menduga dia yang kalian berdua datang ke sini untuk mencari.",
  ui_story_5033_50331302_41_dialog_content = "Maksudmu kasus-kasus itu...?",
  ui_story_5033_50331302_42_dialog_content = "Apakah ada seorang biarawati, di antara teman-temanmu?",
  ui_story_5033_50331302_43_dialog_content = "Ya, tapi dia mengambil cuti beberapa waktu lalu.",
  ui_story_5033_50331302_44_dialog_content = "Jangan bilang…",
  ui_story_5033_50331302_45_dialog_content = "Dia membunuh salah satu pengintaiku, di gereja. Dia ada di sana sekarang.",
  ui_story_5033_50331302_46_dialog_content = "Apa?!",
  ui_story_5033_50331302_47_dialog_content = "Apakah Anda memberi tahu saya bahwa bajingan itu, orang yang membunuh Matilda, ada di gereja sekarang?!",
  ui_story_5033_50331302_48_dialog_content = "Ya. Semuanya memiliki ciri yang sama dengan kasus Umbraton. Itu harus dia.",
  ui_story_5033_50331302_49_dialog_content = "Tunggu sebentar, bagaimana Anda tahu semua ini?",
  ui_story_5033_50331302_50_dialog_content = "Kecerdasan adalah roti dan mentega saya, Nak.",
  ui_story_5033_50331302_51_dialog_content = "Bukan itu saja yang saya tahu. Saya juga tahu sedikit rahasia yang saya yakin Pollux akan sangat tertarik ...",
  ui_story_5033_50331302_52_dialog_content = "\"Biarawati\" itu bukan pelayan dewa cahaya.",
  ui_story_5033_50331302_53_dialog_content = "Dia dan Pollux biasa dipanggil Gemini sebagai anggota organisasi, dan namanya <color=#FFB400>Antares</color>.",
  ui_story_5033_50331302_54_dialog_content = "Apa kaubilang?!",
  ui_story_5033_50331302_55_dialog_content = "Tunggu! Bukankah orang yang kamu bicarakan sudah mati?",
  ui_story_5033_50331302_56_dialog_content = "Betul sekali! Ini tidak mungkin. Pollux jelas...",
  ui_story_5033_50331302_57_dialog_content = "Saya hanya skeptis seperti Anda ketika informasi ini pertama kali sampai ke telinga saya. Tapi saya jamin, itu benar.",
  ui_story_5033_50331302_58_dialog_content = "Dia tidak hanya bertahan, tetapi dia telah mengumpulkan kekuatannya selama bertahun-tahun. Dan sekarang, dia memutuskan untuk membalas dendam pada Euphoria.",
  ui_story_5033_50331302_59_dialog_content = "Apa yang kita tunggu? Pollux pasti akan dalam masalah!",
  ui_story_5033_50331302_60_dialog_content = "Ya... Jika dia bisa membunuh orang tanpa berkedip, aku tidak bisa berpikir apa lagi yang bisa dia lakukan...",
  ui_story_5033_50331302_61_dialog_content = "Kita tidak bisa membiarkan dia terus membuat masalah.",
  ui_story_5033_50331302_62_dialog_content = "Apakah Anda yakin akan hal ini, Gustav?",
  ui_story_5033_50331302_63_dialog_content = "Dengar, Nak, aku sudah memberitahumu di mana menemukan orang yang kau cari. Apakah Anda dapat menangkapnya atau tidak, itu terserah Anda.",
  ui_story_5033_50331302_64_dialog_content = "Itu terkutuk...",
  ui_story_5033_50331302_65_dialog_content = "Mengapa Anda tidak pergi dengan mereka, Gustav? Anda mungkin perlu memahami situasinya karena sulit bagi mereka untuk bertarung dengan Antares...",
  ui_story_5033_50331302_66_dialog_content = "Hahaha, kamu tidak perlu khawatir tentang aku yang menguasai situasi. Serahkan padaku.",
  ui_story_5033_50331302_67_dialog_content = "Anda hanya fokus untuk menemukan si pembunuh dan mengungkapkan kebenaran kepada semua orang",
  ui_story_5033_50331302_68_dialog_content = "Saya akan mencoba membantu meredakan kemarahan yang dirasakan Euphoria terhadap Anda ...",
  ui_story_5033_50331401_1_dialog_content = "<color=#e8d9bb>*Rumbles...*</color>",
  ui_story_5033_50331401_2_dialog_content = "Apakah itu ledakan? Atau guntur?",
  ui_story_5033_50331401_3_dialog_content = "Percepat langkahnya, Caelestite. Bagaimana Anda lebih lambat dari tulang-tulang tua ini?",
  ui_story_5033_50331401_4_dialog_content = "Aku turut sedih...",
  ui_story_5033_50331401_5_dialog_content = "Aku perlu bicara denganmu, Casta.",
  ui_story_5033_50331401_6_dialog_content = "Aku tahu apa yang ingin kamu katakan.",
  ui_story_5033_50331401_7_dialog_content = "Dia harus mati.",
  ui_story_5033_50331401_8_dialog_content = "Kamu...",
  ui_story_5033_50331401_9_dialog_content = "Casta, saya tahu bahwa Anda dan Pollux sangat marah tentang Matilda.",
  ui_story_5033_50331401_10_dialog_content = "Tapi saya tidak berpikir ini adalah situasi yang sederhana. Pernahkah Anda berpikir mengapa dia melakukan semua ini?",
  ui_story_5033_50331401_11_dialog_content = "Karena dia ingin membalas dendam pada Pollux, dan semua Euforia untuk \"kematiannya\".",
  ui_story_5033_50331401_12_dialog_content = "Itu mungkin. Tapi kenapa sekarang, setelah bertahun-tahun?",
  ui_story_5033_50331401_13_dialog_content = "Saya tidak bisa mengatakannya.",
  ui_story_5033_50331401_14_dialog_content = "Mengapa melakukan begitu banyak kejahatan tingkat tinggi dan baru kemudian pergi mencari Pollux?",
  ui_story_5033_50331401_15_dialog_content = "Aku tidak tahu.",
  ui_story_5033_50331401_16_dialog_content = "Dan mengapa...",
  ui_story_5033_50331401_17_dialog_content = "<size=45>Saya tidak tahu, dan saya tidak ingin tahu!</size>",
  ui_story_5033_50331401_18_dialog_content = "Pollux telah membunuhnya sekali, jadi dia membunuh Sister Matilda, yang telah menyelamatkan Pollux.",
  ui_story_5033_50331401_19_dialog_content = "Membawa semua kecurigaan ke Pollux dan kemudian kembali ke Euphoria saat Anda mengikuti petunjuk.",
  ui_story_5033_50331401_20_dialog_content = "Apakah sulit untuk memahami bahwa ini semua untuk membalas dendam pada Pollux?",
  ui_story_5033_50331401_21_dialog_content = "Tenang dulu, dan pikirkan apa yang akan dilakukan Pollux!",
  ui_story_5033_50331401_22_dialog_content = "Pollux tidak akan mencakup Antares!",
  ui_story_5033_50331401_23_dialog_content = "Dia akan melakukan persis seperti yang saya lakukan—memotongnya berkeping-keping!",
  ui_story_5033_50331401_24_dialog_content = "Casta!",
  ui_story_5033_50331401_25_dialog_content = "Hei, jangan makan itu! Muntahkan...",
  ui_story_5033_50331401_26_dialog_content = "<color=#e8d9bb>Ding-dong, Ding-dong—</color>",
  ui_story_5033_50331401_27_dialog_content = "Dengar, kau tidak boleh makan ini, mengerti? Sekarang berlari dan bermain di tempat lain.",
  ui_story_5033_50331401_28_dialog_content = "Fiuh... Akhirnya anak-anak kecil itu menetap.",
  ui_story_5033_50331401_29_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_5033_50331401_30_dialog_content = "Siapa itu?",
  ui_story_5033_50331401_31_dialog_content = "Buka pintunya, cepat! Saya Eho, agen khusus Serikat Kurir Umbraton!",
  ui_story_5033_50331401_32_dialog_content = "Kau membuatku takut setengah mati! Apa yang kamu lakukan di sini? Apakah Anda mendapatkan paket saya?",
  ui_story_5033_50331401_33_dialog_content = "Um, pengiriman super cepat dari Umbraton!",
  ui_story_5033_50331401_34_dialog_content = "Pertahankan, ya?! Berikan di sini.",
  ui_story_5033_50331401_35_dialog_content = "<color=#e8d9bb>*Kertas dibuka*</color>",
  ui_story_5033_50331401_36_dialog_content = "\"Ini Taki. Aku tidak bisa menghubungi Corax, jadi aku mencoba peruntungan denganmu.\"",
  ui_story_5033_50331401_37_dialog_content = "\"Seorang korban selamat dari pembunuh berantai, dan dia sudah bangun. Kamu harus segera memberi tahu Corax...\"",
  ui_story_5033_50331401_38_dialog_content = "\"Tersangka adalah seorang biarawati, dengan rambut dan mata beruban. Gambar ada di bawah...\"",
  ui_story_5033_50331401_39_dialog_content = "\"Tapi dia bukan dalangnya! Masih ada seseorang di belakangnya yang menarik tali!\"",
  ui_story_5033_50331401_40_dialog_content = "Apa?",
  ui_story_5033_50331401_41_dialog_content = "<size=42>\"Ini <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_42_dialog_content = "<size=42>\"Di balik layar, semuanya <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_43_dialog_content = "Penebusan dosa? Membagikan? Apa sebenarnya yang kamu lakukan di sini...?",
  ui_story_5033_50331401_44_dialog_content = "Saya di sini hanya karena saya ingin memberi tahu Anda bahwa saya menemukan siapa yang menarik tali di balik semua ini.",
  ui_story_5033_50331401_45_dialog_content = "Tunggu aku untuk menyelesaikannya dan aku bisa mengembalikan hidupmu.",
  ui_story_5033_50331401_46_dialog_content = "Aku berhutang ini padamu.",
  ui_story_5033_50331401_47_dialog_content = "Saya tidak membutuhkannya! Aku akan menyerahkanmu ke Umbraton.",
  ui_story_5033_50331401_48_dialog_content = "Saya khawatir itu tidak akan berhasil... Saya tidak ingin mati di tangan siapa pun selain tangan Anda.",
  ui_story_5033_50331401_49_dialog_content = "Kau gila?!",
  ui_story_5033_50331401_50_dialog_content = "Kenapa iya! Aku sudah gila untuk waktu yang lama.",
  ui_story_5033_50331401_51_dialog_content = "Sejak aku lahir sebagai anak Euphoria... Sejak aku bergabung dengan organisasi itu...",
  ui_story_5033_50331401_52_dialog_content = "Sejauh yang saya ketahui, membunuh sama alaminya dengan bernafas.",
  ui_story_5033_50331401_53_dialog_content = "Saya tidak pernah benar-benar terjaga.",
  ui_story_5033_50331401_54_dialog_content = "Sampai aku menemukan teman pertamaku... Kamu seperti bintang penuntunku, menunjukkan jalan...",
  ui_story_5033_50331401_55_dialog_content = "Tutup! Saat kau membunuh Sister Matilda, kami kehilangan kesempatan untuk berteman.",
  ui_story_5033_50331401_56_dialog_content = "Tidak... Saat aku mengangkat pisauku padamu, kau bukan temanku.",
  ui_story_5033_50331401_57_dialog_content = "Tidak, Pollux, itu kesalahan organisasi! Gustav harus disalahkan untuk semuanya...",
  ui_story_5033_50331401_58_dialog_content = "Semuanya akan berakhir, selama mereka pergi.",
  ui_story_5033_50331401_59_dialog_content = "<size=45>Gustav?!</size>",
  ui_story_5033_50331401_60_dialog_content = "Ya. Seperti yang saya katakan, saya akhirnya menemukan siapa yang menarik tali di belakang layar.",
  ui_story_5033_50331401_61_dialog_content = "Gustav... Dia adalah bagian dari organisasi dan pernah menjadi tangan kanan Bos.",
  ui_story_5033_50331401_62_dialog_content = "Dia benar-benar anggota?",
  ui_story_5033_50331401_63_dialog_content = "Apakah Anda punya bukti?",
  ui_story_5033_50331401_64_dialog_content = "Saya menyesal untuk mengatakan bahwa saya tidak.",
  ui_story_5033_50331401_65_dialog_content = "Itu semua kesaksian yang terdengar dari mulut orang-orang yang sekarat.",
  ui_story_5033_50331401_66_dialog_content = "<color=#e8d9bb>Kecelakaan—</color>",
  ui_story_5033_50331401_67_dialog_content = "<size=45>Kamu benar-benar di sini, Antares!!</size>",
  ui_story_5033_50331401_68_dialog_content = "Anu…",
  ui_story_5033_50331401_69_dialog_content = "Pollux, apa kamu baik-baik saja?!",
  ui_story_5033_50331401_70_dialog_content = "Saya baik-baik saja. Bagaimana dengan anak-anak? Apakah Anda membuat mereka aman?",
  ui_story_5033_50331401_71_dialog_content = "Wanita ini bukan biarawati! Dia membunuh Suster Matilda!",
  ui_story_5033_50331401_72_dialog_content = "Jika Anda tidak membalaskan dendamnya, saya akan melakukannya!",
  ui_story_5033_50331401_73_dialog_content = "*Batuk-batuk*",
  ui_story_5033_50331401_74_dialog_content = "<size=45>Kamu membunuh Matilda...!!</size>",
  ui_story_5033_50331401_75_dialog_content = "Casta, kamu...",
  ui_story_5033_50331401_76_dialog_content = "Tidak apa-apa, Pollux. Dia benar-benar anak yang sangat menjanjikan...",
  ui_story_5033_50331401_77_dialog_content = "<size=45>Di mana senjatamu?! Gambar sekarang!</size>",
  ui_story_5033_50331401_78_dialog_content = "<size=45>Aku akan membuatmu membayar... untuk Matilda!</size>",
  ui_story_5033_50331401_79_dialog_content = "Apakah Anda ... apakah Anda melihat itu? Itu sangat cepat, itu hanya menabrak dinding!",
  ui_story_5033_50331401_80_dialog_content = "Lihat! Gustav di sini!",
  ui_story_5033_50331401_81_dialog_content = "Maaf saya terlambat, semuanya.",
  ui_story_5033_50331401_82_dialog_content = "Gustav, Pak! Tolong beri tahu kami apa yang harus dilakukan! Pollux punya sampah Umbraton...",
  ui_story_5033_50331401_83_dialog_content = "Semuanya, tenang saja. Saya akan menjelaskan semuanya kepada Anda sebentar lagi.",
  ui_story_5033_50331401_84_dialog_content = "Tapi sebelum itu, biarkan orang-orang ini lewat.",
  ui_story_5033_50331401_85_dialog_content = "...",
  ui_story_5033_50331401_86_dialog_content = "Hah? HAH?!",
  ui_story_5033_50331401_87_dialog_content = "Apa yang kamu lakukan di sini? Kapan Anda muncul?",
  ui_story_5033_50331401_88_dialog_content = "Kita harus pergi ke gereja, PlayerName! Casta kehilangan kendali!",
  ui_story_5033_50331401_89_dialog_content = "<color=#e8d9bb>Bang, Bang!</color>",
  ui_story_5033_50331401_90_dialog_content = "Casta... Itu namamu, kan?",
  ui_story_5033_50331401_91_dialog_content = "<size=45>Melawan! Siapa yang Anda pikir Anda sedang memandang rendah?! Serangan balik!</size>",
  ui_story_5033_50331401_92_dialog_content = "Saya masih perlu waktu untuk menyelesaikan semuanya, jadi saya khawatir saya tidak bisa binasa di sini. Tapi aku tidak akan pernah mengangkat tanganku melawanmu...",
  ui_story_5033_50331401_93_dialog_content = "Mengingat Anda penting bagi Pollux...",
  ui_story_5033_50331401_94_dialog_content = "...",
  ui_story_5033_50331401_95_dialog_content = "Anda TIDAK bisa mengucapkan nama itu, pembunuh!",
  ui_story_5033_50331401_96_dialog_content = "BERHENTI, Casta!",
  ui_story_5033_50331401_97_dialog_content = "<size=45>Keluar dari sini!</size>",
  ui_story_5033_50331401_98_dialog_content = "Aku tidak akan membiarkanmu menyabotase misiku... Ini adalah Keputusan Tertinggi Shadowlord!",
  ui_story_5033_50331401_99_dialog_content = "Dia harus dibawa kembali hidup-hidup!",
  ui_story_5033_50331401_100_dialog_content = "<size=45>Aku bilang KELUAR DARI SINI!!</size>",
  ui_story_5033_50331401_101_dialog_content = "Bantu aku mengendalikannya, PlayerName!",
  ui_story_5033_50331402_1_dialog_content = "<color=#e8d9bb>Wah! Buk!</color>",
  ui_story_5033_50331402_2_dialog_content = "Kamu... Sampah...",
  ui_story_5033_50331402_3_dialog_content = "Saya minta maaf. Aku harus berjuang dengan serius untuk menghentikanmu.",
  ui_story_5033_50331402_4_dialog_content = "Pembunuh! Disini! Pembunuhnya ada di sini!",
  ui_story_5033_50331402_5_dialog_content = "Cukup, Casta.",
  ui_story_5033_50331402_6_dialog_content = "Tenang?",
  ui_story_5033_50331402_7_dialog_content = "Pollux, dia membunuh Matilda...",
  ui_story_5033_50331402_8_dialog_content = "Aku tahu.",
  ui_story_5033_50331402_9_dialog_content = "Dia membunuh Matilda...",
  ui_story_5033_50331402_10_dialog_content = "Dan aku akan membalaskan dendamnya, hanya saja tidak hari ini.",
  ui_story_5033_50331402_11_dialog_content = "Ya, saya akan menebus... Setelah semua ini selesai.",
  ui_story_5033_50331402_12_dialog_content = "Jika ada yang akan mengambil nyawa Anne, itu adalah aku. Apakah kamu mengerti?",
  ui_story_5033_50331402_13_dialog_content = "Kami memiliki pemahaman, dia dan aku.",
  ui_story_5033_50331402_14_dialog_content = "Pollux...",
  ui_story_5033_50331402_15_dialog_content = "Anne, tidak, Antares.",
  ui_story_5033_50331402_16_dialog_content = "Kita bertemu lagi, PlayerName, Corax.",
  ui_story_5033_50331402_17_dialog_content = "Semua hal itu yang kau lakukan, Antares?",
  ui_story_5033_50331402_18_dialog_content = "Anda bertanggung jawab atas kematian Suster Matilda?",
  ui_story_5033_50331402_19_dialog_content = "Sepertinya Anda sudah mengetahui semuanya.",
  ui_story_5033_50331402_20_dialog_content = "Itu benar, akulah yang kamu cari.",
  ui_story_5033_50331402_21_dialog_content = "Aku benci mengungkapkannya padamu, tapi aku juga bukan biarawati. Saya minta maaf karena telah menipu Anda.",
  ui_story_5033_50331402_22_dialog_content = "Kenapa... Kenapa kau membunuh orang-orang itu? Dan mengapa Anda datang ke sini?",
  ui_story_5033_50331402_23_dialog_content = "<ukuran=42>Apa?! Benarkah?</size>",
  ui_story_5033_50331402_24_dialog_content = "Mengapa orang-orang itu membuat keributan lagi? Bukankah Gustav dimaksudkan untuk memegang kendali?",
  ui_story_5033_50331402_25_dialog_content = "Tunggu, apakah Anda melihatnya?",
  ui_story_5033_50331402_26_dialog_content = "Ya, dia datang bersama kami.",
  ui_story_5033_50331402_27_dialog_content = "Jadi di mana dia sekarang?",
  ui_story_5033_50331402_28_dialog_content = "Aku tidak tahu. Dia tidak ikut dengan kami.",
  ui_story_5033_50331402_29_dialog_content = "Dia berbahaya! Dia dalang di balik semua ini!",
  ui_story_5033_50331402_30_dialog_content = "Apa? Dalang?",
  ui_story_5033_50331402_31_dialog_content = "Aku bisa menjelaskannya, Pollux.",
  ui_story_5033_50331402_32_dialog_content = "Apa yang Anda katakan adalah nyata, Gustav?",
  ui_story_5033_50331402_33_dialog_content = "Betul sekali. Dia teman terdekat Pollux... Antares.",
  ui_story_5033_50331402_34_dialog_content = "Pasti mengerikan, bergaul dengan orang seperti itu... Kenapa dia melakukan ini?",
  ui_story_5033_50331402_35_dialog_content = "Mengapa dengan sengaja membuat masalah dengan Umbraton?!",
  ui_story_5033_50331402_36_dialog_content = "Dia pasti menggunakannya sebagai dalih untuk mengambil alih rantai keuntungan Euphoria dan Umbraton.",
  ui_story_5033_50331402_37_dialog_content = "Termasuk para penyelidik Umbraton itu, mereka mungkin hanya memamerkannya.",
  ui_story_5033_50331402_38_dialog_content = "Saya tidak akan terkejut jika semua yang ada di Euphoria sudah dihargai dan siap untuk diperebutkan.",
  ui_story_5033_50331402_39_dialog_content = "Tapi kenapa mereka berkelahi di sini? Apakah ini semacam perselisihan internal?",
  ui_story_5033_50331402_40_dialog_content = "Permisi, semuanya. Maaf tapi saya harus bicara dengan Tuan Gustav.",
  ui_story_5033_50331402_41_dialog_content = "Jadi?",
  ui_story_5033_50331402_42_dialog_content = "Baik Pollux maupun Casta tidak mampu merawat Antares.",
  ui_story_5033_50331402_43_dialog_content = "Apakah mereka tidak mampu? Atau hanya tertunda?",
  ui_story_5033_50331402_44_dialog_content = "Maaf, saya tidak bisa mengatakan dengan pasti.",
  ui_story_5033_50331402_45_dialog_content = "Mustahil... Tingkat kebencian dan permusuhan itu... Bagaimana bisa seperti... Apakah Anda yakin akan hal ini?",
  ui_story_5033_50331402_46_dialog_content = "Paling tidak, Antares masih hidup, dan...",
  ui_story_5033_50331402_47_dialog_content = "Majulah.",
  ui_story_5033_50331402_48_dialog_content = "Dia sepertinya telah menceritakan semuanya kepada mereka.",
  ui_story_5033_50331402_49_dialog_content = "Sepertinya hal-hal tidak bisa menjadi jauh lebih buruk ...",
  ui_story_5033_50331402_50_dialog_content = "Jadi apa langkah kita selanjutnya?",
  ui_story_5033_50331402_51_dialog_content = "Langkah selanjutnya...",
  ui_story_5033_50331402_52_dialog_content = "<color=#e8d9bb>*Rumble—*</color>",
  ui_story_5033_50331402_53_dialog_content = "Aku hanya tahu apa langkah terakhir kita.",
  ui_story_5033_50331402_54_dialog_content = "Beritahu semua orang sudah waktunya untuk melakukan ini.",
  ui_story_5033_50331402_55_dialog_content = "Jika kita tidak berurusan dengan Raven's Blood di sini, sekarang, maka Euphoria tidak akan pernah melihat hari damai.",
  ui_story_5033_50331501_1_dialog_content = "Pollux! Keluar di sini! Anda pengkhianat Euforia!",
  ui_story_5033_50331501_2_dialog_content = "Pollux! POLUKS!",
  ui_story_5033_50331501_3_dialog_content = "po...",
  ui_story_5033_50331501_4_dialog_content = "Wow! Dia... Dia benar-benar keluar...",
  ui_story_5033_50331501_5_dialog_content = "Siapa yang memanggilku?",
  ui_story_5033_50331501_6_dialog_content = "...",
  ui_story_5033_50331501_7_dialog_content = "Apa, kamu akhirnya berani menunjukkan wajahmu?",
  ui_story_5033_50331501_8_dialog_content = "Kamu terlihat sehat, Gustav. Saya kira gin dan tonik harian Anda harus berterima kasih.",
  ui_story_5033_50331501_9_dialog_content = "Tidak terlalu. Mereka hanya membuatku mati rasa, karena Euforia ini sudah menawarkan banyak kekecewaan, bukan?",
  ui_story_5033_50331501_10_dialog_content = "Anda tidak lari. Saya lebih mengagumi itu.",
  ui_story_5033_50331501_11_dialog_content = "Dan mengapa saya harus lari? Aku di sini untuk mengurus semuanya. Bagaimanapun, Euphoria membutuhkan seseorang yang dapat mengambil alih.",
  ui_story_5033_50331501_12_dialog_content = "<color=#e8d9bb>Da, da—</color>",
  ui_story_5033_50331501_13_dialog_content = "Hei, itu biarawati?!",
  ui_story_5033_50331501_14_dialog_content = "P-Kembalilah, Gustav bilang dia maniak...",
  ui_story_5033_50331501_15_dialog_content = "Semuanya, izinkan saya untuk memperkenalkan Anda kepada seseorang.",
  ui_story_5033_50331501_16_dialog_content = "Pembunuh berantai Umbraton, pendosa Euphoria, dan mantan anggota organisasi, Gemini—Antares.",
  ui_story_5033_50331501_17_dialog_content = "...",
  ui_story_5033_50331501_18_dialog_content = "A-Apa? Siap mengaku?",
  ui_story_5033_50331501_19_dialog_content = "Itu Pollux untukmu, berperilaku mengagumkan bahkan dalam situasi tanpa harapan seperti itu.",
  ui_story_5033_50331501_20_dialog_content = "Bagaimana denganmu? Sebagai dalang di balik semua ini, akan lebih mudah jika Anda mengakuinya juga.",
  ui_story_5033_50331501_21_dialog_content = "Sepertinya Anda memiliki semua cerita yang ditulis, Gustav.",
  ui_story_5033_50331501_22_dialog_content = "Sayang sekali bahwa tahanan saya di sini memiliki pengakuan yang berbeda. Apakah Anda ingin mendengar?",
  ui_story_5033_50331501_23_dialog_content = "Orang-orang Euphoria yang terhormat! Apakah Anda ingin mengetahui kebenarannya?",
  ui_story_5033_50331501_24_dialog_content = "Pria di hadapanmu ini, Gustav, bukan hanya tahu semua tentang Euforia...",
  ui_story_5033_50331501_25_dialog_content = "Dia juga mantan pejabat tinggi di organisasi tersebut.",
  ui_story_5033_50331501_26_dialog_content = "Organisasi? Apakah itu berarti... organisasi yang Boss kelola lebih dari satu dekade lalu?",
  ui_story_5033_50331501_27_dialog_content = "Bukankah itu kelompok untuk membesarkan pembunuh? Gustav hanya agen intelijen biasa, kan?",
  ui_story_5033_50331501_28_dialog_content = "Organisasi itu runtuh dua belas tahun yang lalu, berkat invasi Eclipsite. Tapi bagi Gustav di sini, ini adalah kesempatan emas.",
  ui_story_5033_50331501_29_dialog_content = "Dengan menggunakan identitas Rumah Intelijennya, ia mulai mencari dan memenangkan geng-geng, dan membangun kembali ketertiban, dalam upaya untuk secara bertahap mengambil alih Euphoria.",
  ui_story_5033_50331501_30_dialog_content = "Tapi yang lebih penting, dia juga memiliki senjata mematikan...",
  ui_story_5033_50331501_31_dialog_content = "<color=#FFB400>Antares</color>.",
  ui_story_5033_50331501_32_dialog_content = "Apa? Biarawati itu bekerja untuk Gustav?",
  ui_story_5033_50331501_33_dialog_content = "Selama beberapa tahun terakhir, Antares telah menjalankan perintahnya, mengeluarkan siapa saja yang masih memiliki kendali atas rantai keuntungan Euphoria.",
  ui_story_5033_50331501_34_dialog_content = "Kemarahan Umbraton membutuhkan kambing hitam, jadi perintah terakhirnya adalah meminta Anne kembali ke sini, untuk membunuhku...",
  ui_story_5033_50331501_35_dialog_content = "Atau lebih tepatnya, minta kita saling membunuh.",
  ui_story_5033_50331501_36_dialog_content = "Hmm... Aku agak bisa melihat bagaimana itu masuk akal.",
  ui_story_5033_50331501_37_dialog_content = "Tidak tidak! Kami hanya memiliki kata-katanya untuk itu!",
  ui_story_5033_50331501_38_dialog_content = "Tapi Gustav sama, bukan? Kita juga tidak boleh begitu saja mempercayainya, hanya karena dia menjalankan Rumah Intelijen...",
  ui_story_5033_50331501_39_dialog_content = "Sial... Apakah kita benar-benar semua telah dipermainkan?",
  ui_story_5033_50331501_40_dialog_content = "<size=45>Pollux! Cukup!</size>",
  ui_story_5033_50331501_41_dialog_content = "Orang-orang baik ini tidak bodoh! Mereka tidak akan tertipu oleh kebohongan Anda.",
  ui_story_5033_50331501_42_dialog_content = "Anda hanya ingin melemparkan saya ke bawah bus, dan membuat saya disalahkan karena mendalangi semua ini.",
  ui_story_5033_50331501_43_dialog_content = "Anda tahu sepenuhnya apa yang telah Anda lakukan, dan Anda akan membayarnya, bahkan tanpa bukti yang kuat!",
  ui_story_5033_50331501_44_dialog_content = "Dengarkan apa yang Anda katakan, Suster. Saya merasa malu untuk Anda.",
  ui_story_5033_50331501_45_dialog_content = "Jika punggungmu bersandar ke dinding dan pada akhirnya kau bermaksud membunuhku, seorang lelaki tua, maka datanglah padaku!",
  ui_story_5033_50331501_46_dialog_content = "Tapi saya tidak akan lari jika Anda bisa menghasilkan sedikit pun bukti.",
  ui_story_5033_50331501_47_dialog_content = "<size=45>Saya punya bukti!</size>",
  ui_story_5033_50331501_48_dialog_content = "Saya punya bukti! Disini!",
  ui_story_5033_50331501_49_dialog_content = "Nekoyashiki?!",
  ui_story_5033_50331501_50_dialog_content = "…?!",
  ui_story_5033_50331501_51_dialog_content = "Minggir! Kalian semua, minggir!",
  ui_story_5033_50331501_52_dialog_content = "Anda ingin bukti, Gustav? Saya punya bukti Anda di sini!",
  ui_story_5033_50331501_53_dialog_content = "Ini baru dari Umbraton, kesaksian orang yang selamat!",
  ui_story_5033_50331501_54_dialog_content = "A... Selamat?!",
  ui_story_5033_50331501_55_dialog_content = "...",
  ui_story_5033_50331501_56_dialog_content = "Pembunuhnya adalah seorang biarawati—dia! Dan orang yang mengatur semuanya, merencanakan semuanya—",
  ui_story_5033_50331501_57_dialog_content = "<size=45>Tidak lain adalah kamu, Gustav!</size>",
  ui_story_5033_50331501_58_dialog_content = "Tidak mungkin... Tidak mungkin... Tidak mungkin ada orang yang bisa selamat dari itu!",
  ui_story_5033_50331501_59_dialog_content = "Ini bukti palsu!",
  ui_story_5033_50331501_60_dialog_content = "Ini adalah informasi palsu! Kalian semua berkomplot untuk memukuli saya, bukan?!",
  ui_story_5033_50331501_61_dialog_content = "\"Jimmy Odenkirk, 47 tahun, terbangun dari koma ...\"",
  ui_story_5033_50331501_62_dialog_content = "\"... Menurut keterangannya, tersangka berpakaian seperti biarawati, dengan rambut beruban...\"",
  ui_story_5033_50331501_63_dialog_content = "Cukup...",
  ui_story_5033_50331501_64_dialog_content = "\"Saya diundang ke sana hari itu oleh Gustav dari Euphoria... Kami masuk ke dalam jebakan, dan tidak ada anak buah saya yang berhasil keluar...\"",
  ui_story_5033_50331501_65_dialog_content = "CUKUP!! Aku tidak perlu mendengarkan omong kosong yang memfitnah ini!!",
  ui_story_5033_50331501_66_dialog_content = "Jika Anda masih tidak mengakuinya, maka mari kita bawa kasus kita ke Shadowlord!",
  ui_story_5033_50331501_67_dialog_content = "Mari kita lihat alasan apa yang kalian buat oleh sepasang penjahat itu!",
  ui_story_5033_50331501_68_dialog_content = "Saya tidak punya waktu untuk memanjakan omong kosong Anda! Jangan hanya berdiri di sana, tangkap Nekoyashiki dan pengkhianat lainnya!",
  ui_story_5033_50331501_69_dialog_content = "Uhh...",
  ui_story_5033_50331501_70_dialog_content = "Apakah Anda mendengar apa yang saya katakan ?!",
  ui_story_5033_50331501_71_dialog_content = "Apa yang kamu katakan itu nyata, Nekoyashiki?",
  ui_story_5033_50331501_72_dialog_content = "Mungkin lebih baik menunggu dan melihat, tidak terlalu cepat mengambil kesimpulan... Segalanya terlalu cair...",
  ui_story_5033_50331501_73_dialog_content = "Cepat, lihat ekspresi mengerikan Gustav...",
  ui_story_5033_50331501_74_dialog_content = "Apa artinya ini...",
  ui_story_5033_50331501_75_dialog_content = "Anda sekelompok tidak berguna yang tidak berguna! Apa kau lupa siapa bosmu?!",
  ui_story_5033_50331501_76_dialog_content = "Lupa kerusakan yang ditimbulkan Umbraton di tempat ini?!",
  ui_story_5033_50331501_77_dialog_content = "Apa yang orang ini katakan? Tidak mungkin dia bos kita!",
  ui_story_5033_50331501_78_dialog_content = "Oi, Gustav! Anda sebaiknya memberi kami penjelasan yang bagus! Apa yang sedang terjadi?",
  ui_story_5033_50331501_79_dialog_content = "Dan semua antek kecil Anda juga, apakah Anda semua bersama-sama?",
  ui_story_5033_50331501_80_dialog_content = "Tidak tidak! Bukan urusanku... Aku tidak ada hubungannya dengan dia!",
  ui_story_5033_50331501_81_dialog_content = "Hehe.. Hahahaha!",
  ui_story_5033_50331501_82_dialog_content = "Sangat baik. Anda telah membawa ini pada diri Anda sendiri.",
  ui_story_5033_50331501_83_dialog_content = "Anda telah memaksa saya untuk melakukan ini!",
  ui_story_5033_50331501_84_dialog_content = "<color=#e8d9bb>Dentang... Denting...</color>",
  ui_story_5033_50331501_85_dialog_content = "Hah? Apakah itu Aliran Gelap...?",
  ui_story_5033_50331501_86_dialog_content = "<anim type=Goyang><size=45>Graaagh!</size></anim>",
  ui_story_5033_50331501_87_dialog_content = "Oh tidak! gerhana!",
  ui_story_5033_50331501_88_dialog_content = "Pergi! Lari sesukamu... Panggil temanmu dan buat kerusakan!",
  ui_story_5033_50331501_89_dialog_content = "<anim type=Goyang><size=45>Graaagh—!</size></anim>",
  ui_story_5033_50331501_90_dialog_content = "gerhana! Eclipsites di mana-mana!",
  ui_story_5033_50331501_91_dialog_content = "Kutukan! Bagaimana mereka bisa mengepung kita? Tidak ada jalan keluar!",
  ui_story_5033_50331501_92_dialog_content = "Anda ... Hama! Anda membiarkan Eclipsites keluar? Mereka hanya akan menarik lebih banyak!",
  ui_story_5033_50331501_93_dialog_content = "J-Jangan mendekat! Uraaaagh!!",
  ui_story_5033_50331501_94_dialog_content = "Gustav! Selamatkan kami!",
  ui_story_5033_50331501_95_dialog_content = "Aku benar-benar minta maaf, semuanya. Biarkan saja Euforia...",
  ui_story_5033_50331501_96_dialog_content = "Disucikan.",
  ui_story_5033_50331502_1_dialog_content = "Argh! Membantu! Selamatkan aku!!",
  ui_story_5033_50331502_2_dialog_content = "Kakiku! Aku tidak bisa bergerak!",
  ui_story_5033_50331502_3_dialog_content = "Berhenti berteriak. Itu hanya luka daging.",
  ui_story_5033_50331502_4_dialog_content = "Tidak ada Eclipsites di sini. Pergi saja cari pendampingmu.",
  ui_story_5033_50331502_5_dialog_content = "Oke, oke... Terima kasih...",
  ui_story_5033_50331502_6_dialog_content = "Jika Anda ingin berterima kasih kepada siapa pun, ucapkan terima kasih kepada Pollux. Anda hampir membakar gereja, namun dia masih mau bersusah payah menyelamatkan Anda.",
  ui_story_5033_50331502_7_dialog_content = "Koraks! Di sebelah kirimu!",
  ui_story_5033_50331502_8_dialog_content = "Berengsek! Bagaimana mereka terus datang?!",
  ui_story_5033_50331502_9_dialog_content = "Aku tidak tahu. Mungkin beberapa Eclipsites lokal juga tertarik?",
  ui_story_5033_50331502_10_dialog_content = "Bagaimana dengan Antares? Apakah Anda melihatnya?",
  ui_story_5033_50331502_11_dialog_content = "Biarkan aku mencarinya dengan kemampuan psikisku! Ini benar-benar kekacauan di sekitar sini!",
  ui_story_5033_50331502_12_dialog_content = "Hai! Pernahkah Anda melihat Pollux?",
  ui_story_5033_50331502_13_dialog_content = "Tidak... Kami juga sedang mencari...",
  ui_story_5033_50331502_14_dialog_content = "Saya baru saja melihatnya di sisi lain gereja! Di sana!",
  ui_story_5033_50331502_15_dialog_content = "Bagaimana dengan Gustav? Dia tidak mungkin melarikan diri, bukan?",
  ui_story_5033_50331502_16_dialog_content = "Hei, Gustav! Tunggu!",
  ui_story_5033_50331502_17_dialog_content = "Bergerak! Minggir...",
  ui_story_5033_50331502_18_dialog_content = "<anim type=Goyang><size=45>Graaaugh...!</size></anim>",
  ui_story_5033_50331502_19_dialog_content = "Argh!",
  ui_story_5033_50331502_20_dialog_content = "Antares.",
  ui_story_5033_50331502_21_dialog_content = "Apakah Anda membiarkan Eclipsites ini keluar, Gustav?",
  ui_story_5033_50331502_22_dialog_content = "Anda ingin semua orang mati bersama Anda?",
  ui_story_5033_50331502_23_dialog_content = "Apa, maksudmu kau mengasihani orang-orang ini?",
  ui_story_5033_50331502_24_dialog_content = "Kasihan? Maaf, tapi aku tidak peduli dengan kehidupan mereka.",
  ui_story_5033_50331502_25_dialog_content = "Anda benar-benar tanpa ampun, Antares. Dan benar-benar layak menjadi salah satu Gemini...",
  ui_story_5033_50331502_26_dialog_content = "Tapi aku sangat bingung dengan tindakanmu barusan.",
  ui_story_5033_50331502_27_dialog_content = "Apakah Anda benar-benar masih memiliki harapan untuk penebusan?",
  ui_story_5033_50331502_28_dialog_content = "Anda tidak mungkin berpikir Anda dapat dimaafkan karena secara terbuka menyebut saya dan mengkhotbahkan apa pun yang Anda sebut keadilan?",
  ui_story_5033_50331502_29_dialog_content = "... Oh tidak. Tentu saja tidak.",
  ui_story_5033_50331502_30_dialog_content = "Anda akan membayar untuk ini! Dan kamu sendirian!",
  ui_story_5033_50331502_31_dialog_content = "SEMUA yang saya lakukan adalah untuk Euphoria... Anda tidak mengerti, tidak bisa mengerti!",
  ui_story_5033_50331502_32_dialog_content = "Yang Anda miliki hanyalah persahabatan dan ikatan yang membosankan dan sepele itu! Anda tidak dapat melihat apa yang saya lihat!",
  ui_story_5033_50331502_33_dialog_content = "Euforia telah menjadi kekacauan total selama dua belas tahun, Antares!",
  ui_story_5033_50331502_34_dialog_content = "Orang-orang Umbraton itu tidak peduli jika kita hidup atau mati, sementara penduduk setempat bahkan tidak memiliki keberanian atau kekuatan untuk membangun kembali!",
  ui_story_5033_50331502_35_dialog_content = "Hanya ada aku! Anda tahu, saya satu-satunya yang bisa melangkah!",
  ui_story_5033_50331502_36_dialog_content = "Untuk memulihkan anggota tubuh yang sakit, seseorang harus mengeluarkan daging yang busuk dan mengeluarkan belatungnya...",
  ui_story_5033_50331502_37_dialog_content = "Dan Anda, Antares, adalah pisau bedah saya. Alat yang sangat baik untuk memotong...",
  ui_story_5033_50331502_38_dialog_content = "Setelah hari ini, Euphoria juga bisa terlahir kembali.",
  ui_story_5033_50331502_39_dialog_content = "Hanya saja kita berdua tidak bisa melihatnya.",
  ui_story_5033_50331502_40_dialog_content = "...",
  ui_story_5033_50331502_41_dialog_content = "<color=#e8d9bb>Clink—</color>",
  ui_story_5033_50331502_42_dialog_content = "Letakkan senjatamu, Gustav. Bagaimana keadaannya, Anda tidak punya kesempatan.",
  ui_story_5033_50331502_43_dialog_content = "Di sinilah Anda akhirnya, Pollux. Ini benar-benar... perkembangan yang beruntung.",
  ui_story_5033_50331502_44_dialog_content = "Sudah waktunya Anda keluar dari gereja kecil Anda yang nyaman, ke jalan-jalan yang dipenuhi mayat.",
  ui_story_5033_50331502_45_dialog_content = "Apa maksudmu?",
  ui_story_5033_50331502_46_dialog_content = "Hahahah...",
  ui_story_5033_50331502_47_dialog_content = "Jangan jual tempat ini, Pollux, jangan jual.",
  ui_story_5033_50331502_48_dialog_content = "Jika Anda benar-benar ingin ...",
  ui_story_5033_50331502_49_dialog_content = "Setidaknya dapatkan harga yang bagus untuk itu.",
  ui_story_5033_50331502_50_dialog_content = "Apa yang kamu rencanakan, Gustav?!",
  ui_story_5033_50331502_51_dialog_content = "Aku tidak ingin mengganggumu... Aku bisa mengakhiri ini sendiri!",
  ui_story_5033_50331502_52_dialog_content = "Aku tidak akan mati dalam kehinaan seperti Boss... Tidak akan pernah...",
  ui_story_5033_50331502_53_dialog_content = "Argh!",
  ui_story_5033_50331502_54_dialog_content = "Dia membunuh dirinya sendiri.",
  ui_story_5033_50331502_55_dialog_content = "Aku punya rencana lain untuknya. Dia turun dengan ringan.",
  ui_story_5033_50331502_56_dialog_content = "Simpan rencana itu di saku Anda untuk saat ini. Simpan untuk <color=#FFB400>lainnya</color>.",
  ui_story_5033_50331502_57_dialog_content = "Seseorang?",
  ui_story_5033_50331502_58_dialog_content = "Pollux, Anda melihat orang-orang di bawah sana, memegang obor dan membawa molotov?",
  ui_story_5033_50331502_59_dialog_content = "Aku tidak bisa melihat wajah mereka dengan jelas. Bagi saya, mereka semua terlihat sama: mengerikan, bodoh, dan putus asa.",
  ui_story_5033_50331502_60_dialog_content = "Anne, ini sudah berakhir. Selesai. Anda hanya perlu kembali ke Umbraton dan menghadapi nasib Anda, lalu...",
  ui_story_5033_50331502_61_dialog_content = "Satu hal yang dikatakan Gustav masuk akal.",
  ui_story_5033_50331502_62_dialog_content = "Kita semua adalah bagian dari Euforia, luka kotor yang tidak akan pernah sembuh sepenuhnya.",
  ui_story_5033_50331502_63_dialog_content = "Hanya dengan menghilangkan bagian-bagian busuk ini, ia dapat benar-benar terlahir kembali.",
  ui_story_5033_50331502_64_dialog_content = "Apa yang ingin kau lakukan?",
  ui_story_5033_50331502_65_dialog_content = "Penuhi misiku sebagai Grim Reaper.",
  ui_story_5033_50331502_66_dialog_content = "Oh tidak, kalau begitu kita... Selamatkan kami! Lari!",
  ui_story_5033_50331502_67_dialog_content = "Antar!",
  ui_story_5033_50331502_68_dialog_content = "Hatimu selembut biasanya, Pollux. Itu sebabnya saya katakan Anda tidak berubah, bahkan setelah bertahun-tahun.",
  ui_story_5033_50331502_69_dialog_content = "Tetapi penyakit yang parah membutuhkan obat yang manjur.",
  ui_story_5033_50331502_70_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5033_50331502_71_dialog_content = "Apa itu terbang tepat untuk kita?! Berlindung-!",
  ui_story_5033_50331502_72_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5033_50331502_73_dialog_content = "Wanita gila... Bagaimana Anda bisa melibatkan warga sipil yang tidak bersalah?!",
  ui_story_5033_50331502_74_dialog_content = "Casta! Membantu! Hentikan biarawati ini, cepat!",
  ui_story_5033_50331502_75_dialog_content = "Pollux! Lakukan sesuatu!",
  ui_story_5033_50331502_76_dialog_content = "Aku…",
  ui_story_5033_50331502_77_dialog_content = "Anne, aku tahu apa yang kamu lakukan. Tapi tidak ini... Tidak perlu untuk ini.",
  ui_story_5033_50331502_78_dialog_content = "Kami memiliki kesepakatan.",
  ui_story_5033_50331502_79_dialog_content = "Anda juga mendengar bukti kuat yang baru saja diproduksi oleh pria di depan umum ...",
  ui_story_5033_50331502_80_dialog_content = "Bahkan jika saya tidak tertarik untuk membersihkan Euphoria, saya masih tidak bisa membiarkan saksi-saksi ini hidup.",
  ui_story_5033_50331502_81_dialog_content = "Diam, Anne... Berhenti...",
  ui_story_5033_50331502_82_dialog_content = "Dan saya akan mulai dengan orang yang paling dekat dengan saya.",
  ui_story_5033_50331502_83_dialog_content = "Argh! Kembali! Kembali!",
  ui_story_5033_50331502_84_dialog_content = "Kau juga satu-satunya yang bisa menghentikanku.",
  ui_story_5033_50331502_85_dialog_content = "Kau siap?",
  ui_story_5033_50331502_86_dialog_content = "Apakah Anda benar-benar harus melakukan ini ?!",
  ui_story_5033_50331502_87_dialog_content = "<size=30>Aku tidak akan membiarkanmu membawaku pergi, Pollux. Saya ingin tinggal di Euphoria, meskipun dengan cara saya sendiri.</size>",
  ui_story_5033_50331502_88_dialog_content = "<size=30>Satu-satunya cara yang tersisa bagiku, untuk menebus dosa-dosaku.</size>",
  ui_story_5033_50331502_89_dialog_content = "...",
  ui_story_5033_50331502_90_dialog_content = "Cukup sudah.",
  ui_story_5033_50331502_91_dialog_content = "Aku tidak punya cita-cita besar, Anne.",
  ui_story_5033_50331502_92_dialog_content = "Ini hanya untuk Matilda.",
  ui_story_5033_50331502_93_dialog_content = "Tentu saja, ini juga untuk Matilda.",
  ui_story_5033_50331502_94_dialog_content = "Kalahkan dia, Pollux! Untuk Euforia!",
  ui_story_5033_50331502_95_dialog_content = "Untuk Euforia! Euforia!",
  ui_story_5033_50331502_96_dialog_content = "Mari kita mulai. Saya harap Anda masih memilikinya.",
  ui_story_5033_50331502_97_dialog_content = "Jangan khawatir, saya ingat hal-hal penting. Mereka yang tidak akan pernah saya lupakan...",
  ui_story_5033_50331502_98_dialog_content = "Aku masih punya satu pertanyaan terakhir, Anne.",
  ui_story_5033_50331502_99_dialog_content = "Heh. Bertanya.",
  ui_story_5033_50331502_100_dialog_content = "Jika Anda memiliki kesempatan kedua, apakah Anda masih akan melakukannya?",
  ui_story_5033_50331502_101_dialog_content = "Apakah maksud Anda dengan Gustav...",
  ui_story_5033_50331502_102_dialog_content = "Tidak, maksudku waktu itu, 14 tahun yang lalu...",
  ui_story_5033_50331502_103_dialog_content = "Apakah Anda masih akan ditikam oleh saya?",
  ui_story_5033_50331502_104_dialog_content = "Ya. Jika saya memiliki kesempatan kedua, saya akan berlari pada Anda sama saja.",
  ui_story_5033_50331502_105_dialog_content = "Dan kemudian aku akan memelukmu erat-erat, dan mengucapkan selamat tinggal padamu.",
  ui_story_5033_50331502_106_dialog_content = "Sama seperti saat ini...",
  ui_story_5033_50331502_107_dialog_content = "<color=#e8d9bb>*Tusuk—*</color>",
  ui_story_5033_50331502_108_dialog_content = "...",
  ui_story_5033_50331502_109_dialog_content = "Matamu jauh lebih tegas daripada saat itu.",
  ui_story_5033_50331502_110_dialog_content = "Anda telah berubah, Pollux. Ini bagus untuk dilihat.",
  ui_story_5033_50331502_111_dialog_content = "Dan... Kau benar-benar menyimpan... belati itu...",
  ui_story_5033_50331502_112_dialog_content = "Tidak lagi. Aku akan menguburnya setelah hari ini.",
  ui_story_5033_50331502_113_dialog_content = "Selamat tinggal, Pollux-ku.",
  ui_story_5033_50331502_114_dialog_content = "Selamat tinggal... Antares, penuh dosa.",
  ui_story_5033_50331502_115_dialog_content = "Sekarang, akhirnya, saya sama seperti Anda.",
  ui_story_5033_50331502_116_dialog_content = "Po—",
  ui_story_5033_50331502_117_dialog_content = "?!",
  ui_story_5033_50331502_118_dialog_content = "Ini... Antares, dan Gustav?!",
  ui_story_5033_50331502_119_dialog_content = "...",
  ui_story_5033_50331502_120_dialog_content = "Pollux! Apa kamu baik baik saja?",
  ui_story_5033_50331502_121_dialog_content = "...",
  ui_story_5033_50331502_122_dialog_content = "Corax, dapatkah Anda membantu saya memeriksanya?",
  ui_story_5033_50331502_123_dialog_content = "Gustav sudah mati. Biarkan aku memeriksa Anne...",
  ui_story_5033_50331502_124_dialog_content = "Tak perlu.",
  ui_story_5033_50331502_125_dialog_content = "Apa?",
  ui_story_5033_50331502_126_dialog_content = "Tidak perlu, dokter.",
  ui_story_5033_50331502_127_dialog_content = "Misi Anda... <color=#FFB400>gagal</color>.",
  ui_story_5033_50331502_128_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_5033_50331601_1_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian</color>",
  ui_story_5033_50331601_2_dialog_content = "... Jadi, itu benar-benar Gustav yang menarik.",
  ui_story_5033_50331601_3_dialog_content = "Saya telah mengatakan selama berabad-abad bahwa dia menggunakan semua orang, tetapi tidak ada yang mendengarkan. Hmph.",
  ui_story_5033_50331601_4_dialog_content = "Tampaknya biarawati pembunuh itu sudah mati. Diambil oleh Pollux sendiri.",
  ui_story_5033_50331601_5_dialog_content = "Saya mengharapkan tidak kurang dari Pollux ... Kami beruntung memilikinya ...",
  ui_story_5033_50331601_6_dialog_content = "Kudengar mereka tumbuh bersama. Saya kira itu adalah sesuatu yang tidak bisa dia abaikan?",
  ui_story_5033_50331601_7_dialog_content = "Tidak ada gosip di belakang punggung orang.",
  ui_story_5033_50331601_8_dialog_content = "Jika Anda benar-benar tidak memiliki hal lain untuk dilakukan, maka Anda dapat membantu saya memperbaiki dinding dan jendela gereja. Anak-anak masih membutuhkan tempat tinggal.",
  ui_story_5033_50331601_9_dialog_content = "Anda cukup tua untuk mengambil beberapa tanggung jawab.",
  ui_story_5033_50331601_10_dialog_content = "Ya, ya...",
  ui_story_5033_50331601_11_dialog_content = "Nekoyashiki, untuk saat ini, semua orang telah kembali ke gereja.",
  ui_story_5033_50331601_12_dialog_content = "Bagus, Latan.",
  ui_story_5033_50331601_13_dialog_content = "Jadi, bagaimana dengan Pollux? Kami semua sangat khawatir...",
  ui_story_5033_50331601_14_dialog_content = "Dia ... Dia mengikat beberapa ujung longgar dengan Casta.",
  ui_story_5033_50331601_15_dialog_content = "Mereka ada di bukit di belakang kita, dan akan segera kembali. Masuklah ke dalam, masih hujan.",
  ui_story_5033_50331601_16_dialog_content = "Hujan berhenti berabad-abad yang lalu, Nekoyashiki.",
  ui_story_5033_50331601_17_dialog_content = "\"... Jalannya yang sulit telah berakhir, namun perjalanan baru menunggu.\"",
  ui_story_5033_50331601_18_dialog_content = "\"Dia akan kembali ke daratan, dan menyatu dengan danau...\"",
  ui_story_5033_50331601_19_dialog_content = "\"Dan akhirnya, kembali ke stardust.\"",
  ui_story_5033_50331601_20_dialog_content = "...",
  ui_story_5033_50331601_21_dialog_content = "Langit cerah, Pollux.",
  ui_story_5033_50331601_22_dialog_content = "Ah, itu sangat cerah. Apakah matahari selalu menyilaukan ini...?",
  ui_story_5033_50331601_23_dialog_content = "Apakah Anda melihat bahwa kabut juga hilang? Jadi seperti inilah Euphoria sebenarnya.",
  ui_story_5033_50331601_24_dialog_content = "Terima kasih, PlayerName, karena menawarkan untuk membaca pidato Anne.",
  ui_story_5033_50331601_25_dialog_content = "Saya malu untuk mengakui bahwa saya bahkan tidak dapat melakukan ini, meskipun telah tinggal di gereja selama bertahun-tahun.",
  ui_story_5033_50331601_26_dialog_content = "Oh, mungkin Anda tidak dapat menemukan cara untuk mengekspresikan diri.",
  ui_story_5033_50331601_27_dialog_content = "Mungkin pidato biasa, yang diberikan kepada begitu banyak orang setiap hari, tidak cocok untuk Antares.",
  ui_story_5033_50331601_28_dialog_content = "Bagaimanapun, aku turut berduka atas kehilanganmu.",
  ui_story_5033_50331601_29_dialog_content = "Aku tidak berduka. Sebaliknya, saya cukup lega.",
  ui_story_5033_50331601_30_dialog_content = "Ini seperti bangun dari mimpi kacau, melihat orang yang tidak akan pernah Anda lihat lagi.",
  ui_story_5033_50331601_31_dialog_content = "Tapi sekarang saya telah terbangun dari mimpi, langit cerah, dan saya harus terus berjalan di jalan saya sendiri.",
  ui_story_5033_50331601_32_dialog_content = "Jadi apa selanjutnya?",
  ui_story_5033_50331601_33_dialog_content = "Saya pikir saya akan tinggal di sini untuk sementara waktu.",
  ui_story_5033_50331601_34_dialog_content = "Bukan hanya karena anak-anak di gereja, tetapi juga karena Euphoria jarang terlihat dengan jelas.",
  ui_story_5033_50331601_35_dialog_content = "Ini mungkin yang Antares ingin lihat juga.",
  ui_story_5033_50331601_36_dialog_content = "Mungkin. Atau mungkin dia ingin menebus dosanya dengan tanganku.",
  ui_story_5033_50331601_37_dialog_content = "Dia adalah salah satu yang benar-benar rumit.",
  ui_story_5033_50331601_38_dialog_content = "Jika dia benar-benar mati empat belas tahun yang lalu, dan tidak digunakan oleh siapa pun ...",
  ui_story_5033_50331601_39_dialog_content = "Atau jika kita tidak dibuat untuk saling membunuh, dan Gemini melanjutkan...",
  ui_story_5033_50331601_40_dialog_content = "Atau bagaimana jika kita bahkan tidak pernah saling mengenal?",
  ui_story_5033_50331601_41_dialog_content = "Antares dan Pollux, hanya dua orang asing, menjalani hidup mereka.",
  ui_story_5033_50331601_42_dialog_content = "Apakah ceritanya akan berbeda?",
  ui_story_5033_50331601_43_dialog_content = "Apa yang akan menjadi takdir baru Euphoria?",
  ui_story_5033_50331601_44_dialog_content = "Ayo, Pollux. Ini tidak seperti Anda untuk menjadi begitu nostalgia.",
  ui_story_5033_50331601_45_dialog_content = "Kamu benar. Saya siap untuk mengucapkan selamat tinggal pada masa lalu.",
  ui_story_5033_50331601_46_dialog_content = "Pisau itu, dan bros hydrangea...",
  ui_story_5033_50331601_47_dialog_content = "Biarkan mereka beristirahat dengan tenang bersama Antares.",
  ui_story_5033_50331601_48_dialog_content = "Itu mengingatkan saya, kami belum memberi hormat kepada Matilda tahun ini.",
  ui_story_5033_50331601_49_dialog_content = "Oh itu benar. Biarkan aku mengurus semuanya di sekitar sini, lalu kita harus mencari waktu untuk mengunjungi Umbraton.",
  ui_story_5033_50331601_50_dialog_content = "Baiklah, aku tidak akan mengganggumu lebih jauh. Selamat tinggal, Pollux, Casta.",
  ui_story_5033_50331601_51_dialog_content = "Apakah Anda pergi ke hub pesawat ulang-alik sendiri?",
  ui_story_5033_50331601_52_dialog_content = "Dengan semua orang berlarian seperti ayam tanpa kepala, jalannya mungkin lebih kasar.",
  ui_story_5033_50331601_53_dialog_content = "Tapi Corax kembali ke Umbraton sendirian lagi, mengatakan sesuatu tentang membuat laporan...",
  ui_story_5033_50331601_54_dialog_content = "Aku akan pergi denganmu.",
  ui_story_5033_50331601_55_dialog_content = "Ya, biarkan Casta ikut.",
  ui_story_5033_50331601_56_dialog_content = "Saya masih memiliki beberapa ... hal-hal lain untuk menghadiri. Kalian pergi ke depan.",
  ui_story_5033_50331601_57_dialog_content = "Aku percaya kita akan bertemu lagi, PlayerName. Tunggu saja Euphoria menjadi negeri ajaib sejati.",
  ui_story_5033_50331601_58_dialog_content = "Tentu saja, Pollux. Saya menantikan hari itu.",
  ui_story_5033_50331601_59_dialog_content = "<color=#e8d9bb>Umbraton, dua hari kemudian</color>",
  ui_story_5033_50331601_60_dialog_content = "Bacalah semua tentang itu! Penjahat dalam pembunuhan berantai Umbraton mati saat ditangkap!",
  ui_story_5033_50331601_61_dialog_content = "Peduli untuk kertas, Mr Corax?",
  ui_story_5033_50331601_62_dialog_content = "Bagaimana Anda mengenali saya ...?",
  ui_story_5033_50331601_63_dialog_content = "Menjauh dariku, pergi.",
  ui_story_5033_50331601_64_dialog_content = "Baiklah, tidak perlu terlalu kejam. Bacalah semua tentang itu!",
  ui_story_5033_50331601_65_dialog_content = "...",
  ui_story_5033_50331601_66_dialog_content = "Kamu terlambat.",
  ui_story_5033_50331601_67_dialog_content = "Casta bukan pilot pesawat yang hebat.",
  ui_story_5033_50331601_67X1_dialog_content = "Ikuti aku.",
  ui_story_5033_50331601_68_dialog_content = "<color=#e8d9bb>*Halaman buku dibalik*</color>",
  ui_story_5033_50331601_69_dialog_content = "Apa ini...?",
  ui_story_5033_50331601_70_dialog_content = "Kasus ditutup. Shadowlord telah melihat file tersebut, dan masalah ini diselesaikan secara kasar seperti yang dijelaskan.",
  ui_story_5033_50331601_71_dialog_content = "Bagus. Terima kasih, Corax.",
  ui_story_5033_50331601_72_dialog_content = "Anda benar-benar harus berterima kasih kepada saya!",
  ui_story_5033_50331601_73_dialog_content = "Saya jelas ada di sana dalam misi tetapi tidak berhasil membawa kembali salah satu dari dua tersangka, maaf, dua penjahat.",
  ui_story_5033_50331601_74_dialog_content = "Haha, itu benar-benar tidak beruntung.",
  ui_story_5033_50331601_75_dialog_content = "Aku…",
  ui_story_5033_50331601_76_dialog_content = "Mari kita tinggalkan itu untuk saat ini. Lanjutkan, Anda akan menemukan dokumen lain.",
  ui_story_5033_50331601_77_dialog_content = "Ini adalah rencana Shadowlord untuk membangun kembali Euphoria bersamamu. Lihat apakah ada masalah.",
  ui_story_5033_50331601_78_dialog_content = "Dengan Gustav mati, pasti gila di sana.",
  ui_story_5033_50331601_79_dialog_content = "Ada banyak geng Umbraton yang menggantungkan hidupnya pada Euphoria. Kita harus datang dengan beberapa ide baru.",
  ui_story_5033_50331601_80_dialog_content = "Shadowlord tidak ingin menapaki jalan lama yang sama. Kalau tidak, tidak ada bedanya dengan orang-orang malang itu. Kamu mengerti?",
  ui_story_5033_50331601_81_dialog_content = "Saya setuju. Itu juga yang saya pikirkan.",
  ui_story_5033_50331601_82_dialog_content = "Daging yang membusuk sudah dipotong. Saatnya untuk memulai lagi.",
  ui_story_5033_50331601_83_dialog_content = "Itu analogi yang bagus. Euphoria adalah pasien yang sakit parah yang akhirnya bagian nekrotiknya diangkat...",
  ui_story_5033_50331601_84_dialog_content = "Saatnya untuk pengobatan baru yang akan mengarah pada jaringan yang sehat.",
  ui_story_5033_50331601_85_dialog_content = "Ya, dan perawatan baru adalah rencana rekonstruksi Umbraton.",
  ui_story_5033_50331601_86_dialog_content = "Anak-anak itu akhirnya bisa tumbuh sebagai jaringan sehat Euphoria.",
  ui_story_5033_50331601_87_dialog_content = "Apa lagi yang ada dalam rencananya, Corax? Selain restrukturisasi industri?",
  ui_story_5033_50331601_88_dialog_content = "Sesuatu seperti kesejahteraan sosial?",
  ui_story_5033_50331601_89_dialog_content = "Apakah Anda memikirkan panti asuhan?",
  ui_story_5033_50331601_90_dialog_content = "Santai! Jangan ragu untuk menyebutkan apa pun yang Anda suka. Saya tidak berpikir Shadowlord akan menolak saran ini.",
  ui_story_5033_50331601_91_dialog_content = "Lagi pula, dia penggemar berat mengambil anak-anak... Ahem.",
  ui_story_5033_50331601_92_dialog_content = "Sepertinya aku memiliki kesamaan dengannya—kami berdua pesimis.",
  ui_story_5033_50331601_93_dialog_content = "Saya pikir saya mengerti.",
  ui_story_5033_50331601_94_dialog_content = "Anda berdua dapat percaya bahwa dunia tidak dapat ditolong namun masih memiliki harapan untuk generasi berikutnya.",
  ui_story_5033_50331601_95_dialog_content = "Mata anak-anak tidak berbohong, Corax. Pergi saja ke panti asuhan atau sekolah, dan Anda bisa melihatnya sendiri.",
  ui_story_5033_50331601_96_dialog_content = "Itulah satu-satunya tempat yang murni dan baik yang tersisa.",
  ui_story_5033_50331601_97_dialog_content = "Saya percaya kita harus bergantung pada anak-anak itu jika Euforia ingin cerah lagi.",
  ui_story_5033_50331601_98_dialog_content = "Sama seperti Matilda percaya pada kita, bertahun-tahun yang lalu.",
  ui_story_5033_50331601_99_dialog_content = "...",
  ui_story_5033_50331601_100_dialog_content = "Cukup sekian obrolannya. Kami akan melihat rencananya lagi dan menghubungi Anda kembali.",
  ui_story_5033_50331601_101_dialog_content = "Jika tidak ada yang lain, saya akan pergi.",
  ui_story_5033_50331601_102_dialog_content = "Sampai jumpa di Shuttle Hub.",
  ui_story_5033_50331601_103_dialog_content = "Tidak perlu, tapi terima kasih. Saya ingin mengunjungi kuburan.",
  ui_story_5033_50331601_104_dialog_content = "Untuk memberi hormat kepada Matilda? Saya pikir saya juga menyukainya, tidak apa-apa?",
  ui_story_5033_50331601_105_dialog_content = "Tentu saja. Terima kasih, Corax.",
  ui_story_5033_50331601_106_dialog_content = "Ayo, ada apa dengan semua \"terima kasih\" hari ini? Aku tidak terbiasa dengan sikapmu yang begitu formal.",
  ui_story_5033_50331601_107_dialog_content = "<color=#e8d9bb>Kolosus, Jembatan</color>",
  ui_story_5033_50331601_108_dialog_content = "Ukuran yang tepat untuk gorden. Bisa jadi rok, dengan beberapa meter lagi.",
  ui_story_5033_50331601_109_dialog_content = "*Berdesah*",
  ui_story_5033_50331601_110_dialog_content = "Meja makan, lampu lantai, karpet... Apakah ada chromatic aberration dengan karpet?",
  ui_story_5033_50331601_111_dialog_content = "*Berdesah*",
  ui_story_5033_50331601_112_dialog_content = "Rak, periksa... Dimana talenan kartun? Ah, ini dia.",
  ui_story_5033_50331601_113_dialog_content = "*Mendesah...*",
  ui_story_5033_50331601_114_dialog_content = "Apa kamu baik baik saja, PlayerName? Apakah semua ini membuatmu lelah?",
  ui_story_5033_50331601_115_dialog_content = "Aku hanya merasa sedikit sedih, Vice.",
  ui_story_5033_50331601_116_dialog_content = "Apa yang terjadi beberapa hari terakhir ini seperti mimpi.",
  ui_story_5033_50331601_117_dialog_content = "Kenapa kau selalu melakukan petualangan aneh ini saat aku pergi, hmm?",
  ui_story_5033_50331601_118_dialog_content = "Gimana ceritanya kali ini?",
  ui_story_5033_50331601_119_dialog_content = "Biarkan saya mengatur pikiran saya. Aku bahkan tidak tahu harus mulai dari mana.",
  ui_story_5033_50331601_120_dialog_content = "Baik. Omong-omong, ada apa dengan ini... \"Hidrangea Sehat\"?",
  ui_story_5033_50331601_121_dialog_content = "Pembelian impulsif, dan yang langsung saya sesali. Ini menarik banyak bug.",
  ui_story_5033_50331601_122_dialog_content = "Tetap saja, biarkan di sana. Saya suka melihatnya.",
  ui_story_5033_50331601_123_dialog_content = "Oh kamu. Anda terlihat seperti memiliki dunia di pundak Anda.",
  ui_story_5033_50331601_124_dialog_content = "Kau harus memberitahuku apa yang terjadi kali ini.",
  ui_story_5033_50331601_125_dialog_content = "Baik. Pernahkah Anda mendengar tentang Euforia?",
  ui_story_5033_50331601_126_dialog_content = "Hmm... membunyikan bel.",
  ui_story_5033_50331601_127_dialog_content = "Yah, semuanya dimulai dengan tempat yang disebut Euforia ini..."
}
return config
